INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(1, 'ruRU', 'Задание Канретада', 'Поговорите с Канретадом, чтобы восстановить ваши таланты, оружие и средство передвижения.', 'C возвращением из мира смерти, герой. Было время, когда ты с гордостью $gстоял:стояла; среди своих собратьев, и меч твой был остер. Ныне же ты – лишь тень прошлого. Но встань передо мной, и я воскрешу легендарного рыцаря, которым ты некогда $gбыл:была;.$b$bЯ восполню твои силы, восстановлю оружие и подготовлю тебя к новым подвигам.', '', '', '', '', '', 'Вернитесь к Канретаду.', 19865),
(2, 'ruRU', 'Коготь гиппогрифа Острокогтя', 'Принесите коготь гиппогрифа Острокогтя Сенани Громовое Сердце в Приют Серебряного Ветра.', 'Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы.$b$bСенани Громовое Сердце в приюте Серебряного Ветра несомненно пожелает увидеть этот трофей – доказательство ваших деяний.', '', '', '', '', '', '', 19865),
(5, 'ruRU', 'Урчащий живот Трясунчика', 'Поговорите с шеф-поваром Груалем.', 'Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за нее хорошо заплачу.$B$BУстрой мне пир, и не пожалеешь.$B$BГоворят, что шеф-повар Груаль в таверне "Алый ворон" делает превосходные темные пирожки с крабами...', '', '', '', '', '', '', 19865),
(6, 'ruRU', 'Награда за голову Гаррика Тихокрада', 'Убейте Гаррика Тихокрада и принесите его голову заместителю судьи Виллему в Аббатство Североземья.', 'Гаррик Тихокрад – головорез, который уже много недель не дает покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесешь мне голову этого негодяя – получишь награду!$B$BНо будь $Gосторожен:осторожна;, $n. Гаррик собрал разбойничью шайку. До него непросто будет добраться.', '', '', '', '', '', 'Вернитесь к заместителю судьи Виллему в Долину Североземья, что в Элвиннском лесу.', 19865),
(7, 'ruRU', '140513', 'Уничтожьте 6 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.', 'Первое твое задание, $n, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.', '', '', '', '', '', 'Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.', 19865),
(8, 'ruRU', 'Выгодная сделка', 'Доставьте ненадписанное письмо Ренни – хозяйке таверны в Тирисфальских лесах.', 'Эй, $gприятель:подруга;! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! $b$bУ меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-ее-там. Неважно, какая у нее там фамилия! $b$bДа и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и $gсам:сама; сможешь там отдохнуть, если захочешь. По крайней мере, ты $gдолжен:должна; туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.', '', '', '', '', '', '', 19865),
(9, 'ruRU', 'Поля смерти', 'Убейте 20 дозорных полей по просьбе фермера Сальдена.', 'Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех. Только не меня! Однако угодья захватили големы – дозорные полей.$b$bЕсли вы готовы поработать, я попросил бы вас пойти и убить 20 таких големов. Возвращайтесь за оплатой, когда все будет сделано. Когда расправитесь с теми, что обитают на моем поле, зачистите поля и моих соседей тоже.', '', '', '', '', '', 'Вернитесь к фермеру Сальдену на ферму Сальдена, что в Западном Крае.', 19865),
(10, 'ruRU', 'Спасение Холстомера', 'Узнайте, что стало с младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск.', 'Ох, это ужасно! Я послал моего лучшего помощника, младшего геодезиста Холстомера в пустыню, на юго-восток отсюда. Именно там располагается Зияющая бездна. Вот, а теперь он пропал, и в последнем докладе шла речь о странных насекомых. Неужели они наводнили уже два основных района пустыни?$b$bПрошу тебя, доберись до Зияющей бездны и поищи там Холстомера! Его... или хотя бы оборудование. Боюсь, больше от бедняги ничего и не осталось.', '', '', '', '', '', 'Вернитесь к старшему геодезисту Рудознатцу в Прибамбасск, что в Танарисе.', 19865),
(11, 'ruRU', 'Награда за гноллов из стаи Речной Лапы', 'Принесите 8 раскрашенных поручей гноллов в казармы заместителю судьи Рейнеру.', 'На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов.$B$BАрмия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов.', '', '', '', '', '', 'Вернитесь к заместителю судьи Рейнеру на лесную опушку, что в Элвиннском лесу.', 19865),
(12, 'ruRU', 'Народное ополчение', 'Убейте 15 звероловов и 15 контрабандистов из Братства Справедливости и вернитесь к Гриану Камнегриву.', 'У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир. К сожалению, приходится это делать путем кровопролития.$b$bОдин из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику. У меня есть сообщения, что звероловов Братства замечали около рудника Янго к северо-западу отсюда, а также неподалеку от фермы Мольсена и тыквенной фермы Хмуроброва. Если ты хочешь присоединиться к ополчению, убей 15 звероловов и 15 контрабандистов из Братства Справедливости, а затем возвращайся ко мне.', '', '', '', '', '', 'Вернитесь к Гриану Камнегриву на Сторожевой холм, что в Западном Крае.', 19865),
(13, 'ruRU', 'Народное ополчение', 'Убейте 15 погромщиков и 15 мошенников из Братства Справедливости и вернитесь к Гриану Камнегриву на Сторожевой холм.', 'Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и Поместья Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, $n, и пусть весь Западный Край узнает о силе Света.$b$bЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты $gубил:убила; 15 погромщиков и 15 мошенников из Братства Справедливости.', '', '', '', '', '', 'Вернитесь к Гриану Камнегриву на Сторожевой холм, что в Западном Крае.', 19865),
(14, 'ruRU', 'Народное ополчение', 'Убейте 15 разбойников, 5 налетчиков и 5 кастетчиков из Братства Справедливости. Вернитесь к Гриану Камнегриву на Сторожевой холм.', 'Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края. Мы считаем, что они скрываются в Холмах Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения.', '', '', '', '', '', 'Вернитесь к Гриану Камнегриву на Сторожевой холм, что в Западном Крае.', 19865),
(15, 'ruRU', 'Разведка в руднике Горного эха', 'Уничтожьте 8 кобольдов-рабочих и вернитесь к маршалу Макбрайду.', '$n, мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали. Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда.$B$BОтправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много... Убей-ка штук восемь этих тварей, посмотри, сколько еще осталось, и доложи мне.', '', '', '', '', '', 'Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.', 19865),
(16, 'ruRU', 'Жажда Джерарда', '', '', '', '', '', '', '', 'Вернитесь к Джерарду Румпелю в Сумеречный лес.', 19865),
(18, 'ruRU', 'Братство воров', 'Принесите 8 красных холщовых бандан заместителю судьи Виллему к Аббатству Североземья.', 'Тут возле Североземья недавно новая воровская шайка завелась. Зовут себя Братством Справедливости. Видели их за рекой, на востоке.$B$BНе знаю, что у них на уме, но наверняка ничего хорошего! Принеси мне их банданы, и в награду получишь оружие.', '', '', '', '', '', 'Вернитесь к заместителю судьи Виллему в Долину Североземья, что в Элвиннском лесу.', 19865),
(19, 'ruRU', 'Тарил''зун', 'Принесите маршалу Маррису в Красногорье голову Тарил''зуна.', 'Вестники и отступники из клана Черной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи. Их предводитель – орк по имени Тарил''зун. Он уже натворил достаточно дел. Принеси мне его голову!', '', '', '', '', '', 'Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.', 19865),
(20, 'ruRU', 'Угроза Черной горы', 'Принесите маршалу Маррису в Приозерье 10 иссеченных в бою топоров.', 'К нам явились орки Черной горы из Пылающих степей и захватили крепость Каменной стражи. Они грабят области к северу от Озер, и жители тех земель бежали в город, набились в него, словно сельди в бочку.$B$BПомоги Приозерью избавиться от этой угрозы. Перебей орков Черной горы и принеси в доказательство десять иссеченных в бою топоров.$B$BХотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья. Если встретишь их – убивай без колебаний.', '', '', '', '', '', 'Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.', 19865),
(21, 'ruRU', 'Схватка у рудника Горного эха', 'Уничтожьте 8 кобольдов-рудокопов и вернитесь к маршалу Макбрайду.', 'Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку. Возвращайся на рудник и помоги очистить его от кобольдов. $B$BВремя дорого, $n. Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье.', '', '', '', '', '', 'Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.', 19865),
(22, 'ruRU', 'Пирожок из печени кровоклыка', 'Принесите Сальме Сальден 8 кусков печени кровоклыка, чтобы она могла испечь пирог.', 'Лук очищен. Чеснок раздавлен. Розмарин измельчен. Основа выпечена. Укроп нарезан. Соус вымешан до гладкости. Все, что мне еще нужно для моего знаменитого пирога – это 8 кусков печени кровоклыка!', '', '', '', '', '', 'Вернитесь к Сальме Сальден на ферму Сальдена, что в Западном Крае.', 19865),
(23, 'ruRU', 'Лапа Топтыжня', 'Принесите лапу Топтыжня капитану Таркану в приют Серебряного Ветра.', 'Могучий медведь Топтыжень пал от вашей руки!$b$bНа его лапе есть маленький знак полумесяца, который означает, что зверя дрессировали ночные эльфы, натаскивая его на поиск противников, скрывающихся в лесах. Неизвестно, сколько ваших союзников пали жертвой этой твари.$B$BЭту лапу надо отнести Таркану в Приют Серебряного Ветра. Он будет рад узнать, что противник лишился такого серьезного оружия.', '', '', '', '', '', '', 19865),
(24, 'ruRU', 'Голова Тенумбры', 'Принесите голову Тенумбры капитану Гоггату в дозор Адского Крика.', 'Некогда стремительная Тенумбра лежит у ваших ног. Вы победили.$b$bЭто легендарное существо было гордостью ночных эльфов. Голова убитого ночного саблезуба – достойный трофей этой охоты и символ поражения Альянса в Ясеневом лесу.$b$bКапитан Гоггат из Дозора Адского Крика непременно будет счастлив получить голову убитого ночного саблезуба.', '', '', '', '', '', '', 19865),
(25, 'ruRU', 'А теперь – угомонись', 'Истребите 12 злобных элементалей воды и Приливницу на озере Мистраль, после чего вернитесь к капитану Таркану в приют Серебряного Ветра.', 'Ты бы это $Gвидел:видела;, |3-6($c)!$b$bЭльфы полагали, что их Приют Серебряного Ветра невозможно захватить. Учитывая, что на их стороне была целая армия водных элементалей, они были правы.$b$bПочти.$b$bОдин из наших магов умудрился призвать злобного элементаля, который обратил остальных в яростных, неуправляемых существ.$b$bХа, жаль, что тебя там не было – какие у них были лица!$b$b<Таркан хохочет.>$b$bОдна проблема – маг, призвавший эту тварь, погиб в бою. Теперь кто-то должен угомонить наше создание.', '', '', '', '', '', '', 19865),
(26, 'ruRU', 'Необходимый урок', 'Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.', '$n, я с удовольствием наблюдал за твоими успехами. Ты непременно станешь $Gзнаменитым защитником:знаменитой защитницей; природы.$B$BПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.', '', '', '', '', '', '', 19865),
(33, 'ruRU', 'Волки на границе', 'Принесите 8 шкур зараженных волков Игану Меховщику к Аббатству Североземья.', 'Видимо, эта волчья болезнь не пройдет сама собой. Каждый день количество зараженных волков все возрастает. Мне больно думать об уничтожении детей природы, но мы должны убить этих заболевших молодых волков прежде, чем начнется эпидемия.$B$BУбей зараженных молодых волков в долине и принеси мне их шкуры в доказательство того, что дело сделано.', '', '', '', '', '', 'Вернитесь к Игану Меховщику в Долину Североземья, что в Элвиннском лесу.', 19865),
(34, 'ruRU', 'Незваный гость', 'Убейте Грубобрюха. Принесите Марти Джанроз клык вепря.', 'Мой сад снова разграблен и вытоптан. И я знаю, кто это сделал! Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом.$B$BТеперь мне долго не удастся посадить нарциссы. Они загублены! И во всем виноват мерзкий кабан. Положи конец этому паразиту! Принеси мне его клык, и я с удовольствием вознагражу тебя. Говорят, он пасется в полях на юго-западе от Приозерья, но порой заходит и сюда, в мой сад.', '', '', '', '', '', 'Вернитесь к Марти Джанроз в Приозерье, что в Красногорье.', 19865),
(35, 'ruRU', 'Новые заботы', 'Маршал Дугхан просит вас поговорить со стражником Томасом.', 'Если ты думаешь, что слухи о мурлоках могут оказаться правдой, отправляйся к восточному мосту Элвиннского леса и поговори со стражником Томасом. Он уже неделю несет стражу у моста и должен знать, что там происходит на самом деле.$B$BУ меня есть штормградский скакун, ты можешь воспользоваться им, чтобы добраться до стражника Томаса. Скажи мне, когда будешь $gготов:готова; отправиться.', '', '', '', '', '', '', 19865),
(36, 'ruRU', 'Похлебка Западного Края', 'Отнесите Сальме Сальден рецепт похлебки Западного Края.', 'Никогда я не думала, что наступит день, когда я покину ферму. Но поля кишат разбойниками, и для нас теперь тут слишком опасно. Как только фермер Хмуробров починит повозку, мы отправимся в путь.$b$bМожет быть, ты окажешь мне услугу? Я напишу рецепт похлебки Западного Края, а ты отнесешь его Сальме Сальден вон на ту ферму – она сразу за развилкой дороги.', '', '', '', '', '', '', 19865),
(37, 'ruRU', 'Пропавшие стражи', 'Отправляйтесь на север по реке и отыщите следы пропавших стражников – Рольфа и Малакаи.', 'Несколько дней назад мы отправили на обследование берегов реки двух наших стражей, Рольфа и Малакаи; ни один из них до сих пор не вернулся. Чтобы составить полный отчет, мне нужно выяснить, что с ними случилось.$B$BОтправляйся на север вдоль реки и разыщи стражей... или хотя бы их останки.', '', '', '', '', '', '', 19865),
(38, 'ruRU', 'Похлебка Западного Края', 'Принесите Сальме Сальден 3 куска жилистого мяса стервятника, 3 рыла кровоклыка, 3 глаза мурлока и 3 окры.', 'Помоги мне сварить похлебку Западного Края! Мне нужны для нее следующие ингредиенты:$b$b3 куска жилистого мяса стервятника$b3 рыла кровоклыка$b3 глаза мурлока$b3 окры', '', '', '', '', '', 'Вернитесь к Сальме Сальден на ферму Сальдена, что в Западном Крае.', 19865),
(39, 'ruRU', 'Донесение Томаса', 'Доставьте донесение в Златоземье маршалу Дугхану.', 'Нужно сообщить маршалу Дугхану о смерти Малакаи и Рольфа. Наши войска на востоке Элвиннского леса не смогут справиться с мурлоками.$B$BЯ знаю, лишних солдат у нас нет, но, может, Дугхан пришлет хоть какую-то помощь...', '', '', '', '', '', '', 19865),
(40, 'ruRU', 'Водяная нечисть', 'Реми Повторюх просит вас найти в Златоземье маршала Дугхана и поговорить с ним.', '$n, в Элвиннском лесу появилась новая напасть. Мурлоки поднялись вверх по рекам в восточной части леса, они распугивают рыбу и нападают на мирных жителей.$B$BЯ предупреждал маршала Дугхана, но его больше беспокоит нашествие гноллов и бандитов. Мурлоков он вообще не принимает в расчет. $B$BЯ прошу тебя, $n, поговори с Дугханом и постарайся убедить его послать отряд на восток!', '', '', '', '', '', '', 19865),
(45, 'ruRU', 'Судьба Рольфа', 'Обыщите поселение мурлоков и найдите Рольфа – или подтверждение его смерти.', 'При осмотре местности были обнаружены запутанные следы, ведущие на восток вдоль берега Озера Каменных Столбов. В отдалении видно поселение мурлоков.$B$BВозможно, именно здесь и окончил свой путь Рольф...', '', '', '', '', '', '', 19865),
(46, 'ruRU', 'Награда за мурлоков', 'Принесите 8 рваных плавников мурлоков к восточному мосту Элвиннского леса и отдайте их стражнику Томасу.', 'Армией Штормграда обещана награда за мурлоков-скрытней и мурлоков-добытчиков из Элвиннского леса. Убей их и принеси их рваные плавники стражнику Томасу. Армия Штормграда хорошо за это заплатит.$B$BМурлоки построили селение на Озере Каменных Столбов – это к северу отсюда. Еще одно селение расположено на юге – там, где русло реки разделяется надвое.', '', '', '', '', '', 'Вернитесь к стражнику Томасу в Элвиннский лес.', 19865),
(47, 'ruRU', 'Золотая пыль', 'Принесите 10 порций золотой пыли в Златоземье Реми Повторюху. Золотую пыль можно добыть у кобольдов в Элвиннском лесу.', 'Кобольды в этих местах иногда носят с собой золотую пыль. Достань мне этой пыли, и я дам за нее лучшую цену в городе. Да, лучшую цену в городе!$B$BКобольдов можно найти на юге, на руднике Подземных глубин, или на северо-востоке, рядом с Яшмовой шахтой.', '', '', '', '', '', 'Вернитесь к Реми Повторюху в Златоземье, что в Элвиннском лесу.', 19865),
(52, 'ruRU', 'Защита границы', 'Убейте 8 лесных хищников и 5 молодых лесных медведей. Затем вернитесь к стражнику Томасу у восточного моста Элвиннского леса.', 'Приветствую, $n. Чем дальше от Златоземья, тем агрессивнее становятся дикие звери: на Лесопилку Восточной долины постоянно нападают волки и медведи.$B$BХочешь нам помочь?', '', '', '', '', '', 'Вернитесь к стражнику Томасу в Элвиннский лес.', 19865),
(54, 'ruRU', 'Донесение в Златоземье', 'Отнесите документы маршала Макбрайда маршалу Дугхану в Златоземье, что в Элвиннском лесу.', '$n, ты – |3-6($c), чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса.$B$BЕсли ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье. Златоземье находится на южном тракте, за пограничными воротами.', '', '', '', '', '', '', 19865),
(57, 'ruRU', 'Ночной Дозор', 'Убейте 15 скелетов-губителей и 15 ужасных скелетов по просьбе командира Алтеи Чернодрев.', '$n, я получила сведения о появлении нежити в наших лесах! Если ты не боишься, отправляйся на кладбище Вороньего холма и убей 15 скелетов-губителей и 15 ужасных скелетов. Также говорят, что скелеты появились и к югу от Темнолесья, на Безмятежном кладбище. Мы должны изгнать нежить из Сумеречного леса!', '', '', '', '', '', 'Вернитесь к командиру Алтее Чернодрев в Темнолесье, что в Сумеречном лесу.', 19865),
(59, 'ruRU', 'Броня из кожи и ткани', 'Отдайте Саре Тимберлейн знак брони Штормграда.', 'Твои хитроумие и доблесть должны быть вознаграждены. Я приготовил для тебя знак: он пригодится для какой-нибудь части доспехов. Отнеси его Саре Тимберлейн на лесопилку Восточной долины: она изготовит для тебя броню. Когда получишь новые доспехи, используй их для защиты Элвиннского леса от врагов, $n.$B$BЛесопилка находится к востоку от заставы сразу за мостом.', '', '', '', '', '', '', 19865),
(60, 'ruRU', 'Свечи кобольдов', 'Принесите 8 больших свечей в Златоземье Вильяму Песту.', 'Приветствую тебя, $gдобрый путник:прекрасная госпожа;! Не найдется ли у тебя свободной минутки?$B$BМы с братом держим аптеку в Штормграде, и мне тут понадобились большие свечи. Воск нужен, понимаешь? Вот я и думаю: может, ты мне поможешь?$B$BСвечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских шахтах видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке... Может, прогуляешься туда и раздобудешь для меня свечи?', '', '', '', '', '', 'Вернитесь к Вильяму Песту в Златоземье, что в Элвиннском лесу.', 19865),
(61, 'ruRU', 'Посылка в Штормград', 'Доставьте посылку Вильяма Моргану Песту в Торговый квартал Штормграда.', 'В Штормграде мой брат Морган ждет посылки со свечами. У меня нет времени съездить туда самому, но если ты окажешь нам эту услугу, Морган хорошо тебе заплатит.$B$BВот, я тут упаковал свечи. А Моргана найти несложно, он работает в Торговом квартале Штормграда, в аптеке Песта.', '', '', '', '', '', '', 19865),
(62, 'ruRU', 'Рудник Подземных глубин', 'Исследуйте рудник Подземных глубин и вернитесь в Златоземье с докладом для маршала Дугхана.', 'Рудник в Североземье – не единственная головная боль. До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды.$B$BНужно исследовать рудник и подтвердить эти известия или опровергнуть их. Я буду ждать отчета. Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур.', 'Проведите разведку рудника Подземных глубин.', 'Проведите разведку рудника Подземных глубин.', '', '', '', 'Вернитесь к маршалу Дугхану в Златоземье, что в Элвиннском лесу.', 19865),
(64, 'ruRU', 'Забытая вещь', 'Верните фермеру Хмуроброву его карманные часы, которые находятся в платяном шкафу в его доме на тыквенной ферме на западе.', 'Это было ужасно! Верна разбудила меня, когда услышала гвалт в поле. Поля были полны хулиганья. Мы бежали в спешке, и я забыл взять с собой карманные часы. Папаша Верны подарил мне эти часы в день нашей с ней свадьбы, и мне прямо нехорошо от мысли, что ими могли завладеть те воры. Я оставил часы в доме, в платяном шкафу. Ищи тыквенную ферму к западу отсюда – ты ее не пропустишь. Если вернешь мне мои часы, я буду очень признателен!', '', '', '', '', '', 'Вернитесь к фермеру Хмуроброву во Владение Янсена, что в Западном Крае.', 19865),
(65, 'ruRU', 'Братство Справедливости', 'Поговорите с Вилли в Приозерье по просьбе Гриана Камнегрива.', 'Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовет себя Братством Справедливости. Мне нужно, чтобы ты $gпроник:проникла; в эту бандитскую шайку. Нам нужно узнать, кто ее главарь, и где они прячутся. В деревне Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан.$b$bОтправляйся в деревню Приозерье, что расположена в Красногорье, к востоку от Элвиннского леса, и все разузнай.', '', '', '', '', '', '', 19865),
(66, 'ruRU', 'Легенда о Сталване', 'Найдите клерка Далтри в ратуше Темнолесья.', 'Вчера ночью меня охватил беспричинный ужас. Я почувствовала, что моя внучка Алисса оказалась в страшной опасности. Я разложила карты... и со стола на меня взглянула Смерть.$B$BПогрузившись в длительный и тяжкий транс, я сумела разгадать эту темную тайну. Мне открылось имя: Сталван.$B$BОтыщи клерка в городской Ратуше и постарайся побольше разузнать об этом Сталване. Я опасаюсь за всех нас.', '', '', '', '', '', '', 19865),
(67, 'ruRU', 'Легенда о Сталване', 'Отправьтесь в Лунореченскую школу и сообщите все сведения о Сталване клерку Далтри.', 'Сталван, значит? Дай-ка погляжу в журнал.$b$BСталван... Сталван... Ну-ка... А, вот он! У меня есть запись о некоем господине Сталване Мистмантле. Последний адрес – Лунореченская школа. Но это было так давно!$b$bОкажи любезность, дай знать, если выяснишь что-либо об этом типе. Записи должны содержаться в порядке.', '', '', '', '', '', '', 19865),
(71, 'ruRU', 'Доклад для Томаса', 'Отдайте стражнику Томасу у восточного моста Элвиннского леса медальоны стражей Рольфа и Малакаи.', 'Теперь, когда вы нашли оба медальона, отнесите их к мосту и отдайте стражнику Томасу: он должен узнать о смерти обоих стражей.', '', '', '', '', '', '', 19865),
(73, 'ruRU', '<TXT> Без награды', '', '', '', '', '', '', '', '', 19865),
(76, 'ruRU', 'Яшмовая шахта', 'Обследуйте Яшмовую шахту и вернитесь с докладом в Златоземье к маршалу Дугхану.', 'Благодаря тебе мы знаем, что рудник Подземных глубин заполонили кобольды. Но нам нужен разведчик, чтобы выяснить, что творится в Яшмовой шахте.$B$BОтправляйся туда и доложи мне, если обнаружишь кобольдов. Иди на восток по дороге, пока не доберешься до Башни Азоры, оттуда поверни на север, и у подножия гор отыщешь шахту.', 'Проведите разведку в Яшмовой шахте.', 'Проведите разведку в Яшмовой шахте.', '', '', '', 'Вернитесь к маршалу Дугхану в Златоземье, что в Элвиннском лесу.', 19865),
(82, 'ruRU', 'Исследование Ядовитого улья', 'Принесите 5 частей тел насекомых Сентипаар из Ядовитого улья алхимику Пестычинсу в Прибамбасск.', 'Все эти сообщения о жуках... нам известно, что они опустошают пруды в Ядовитом улье. А НЕИЗВЕСТНО нам... все остальное.$b$bДля начала надо узнать, кто наш враг! Ступай в Ядовитый улей и добудь части тел проклятущих насекомых Сентипаар. Отнеси их алхимику Пестычинсу, пусть повозится. Если уж он возьмется за работу, скоро мы обо всем узнаем!', '', '', '', '', '', 'Вернитесь к алхимику Пестычинсу в Прибамбасск, что в Танарисе.', 19865),
(83, 'ruRU', 'Превосходные льняные изделия', 'Принесите 6 красных льняных повязок на Лесопилку Восточной долины и отдайте их Саре Тимберлейн.', 'Головорезы Элвиннского леса носят льняные повязки, этот материал я могла бы использовать для производства превосходных льняных изделий.$B$BПринеси мне льняные повязки, а я сделаю из них кое-что полезное для тебя.$B$BЭтих бандитов полно в Элвиннском лесу.', '', '', '', '', '', 'Вернитесь к Саре Тимберлейн на Лесопилку Восточной долины, что в Элвиннском лесу.', 19865),
(84, 'ruRU', 'Назад к Билли', 'Отнесите пирог со свининой на Виноградники Маклура и отдайте его Билли.', 'Вот, держи. Отдай этот пирог Билли, да не забудь сказать, что я желаю ему подавиться!', '', '', '', '', '', '', 19865),
(85, 'ruRU', 'Потерянное ожерелье', 'Поговорите с Билли Маклуром.', 'Я потеряла ожерелье. Сдается мне, его стащил этот сорванец Билли Маклур! Вечно он шастает по виноградникам, как крыса какая-то! Если решишь его искать, то сходи на виноградники Маклура, это к востоку отсюда.$B$BПожалуйста, разыщи мое ожерелье, порадуй старуху-вдову!', '', '', '', '', '', '', 19865),
(86, 'ruRU', 'Пирог для Билли', 'Принесите 4 куска нежной кабанины на ферму Стоунфилд и отдайте тетушке Бернис.', 'Может, если бы я получил пирог, то смог бы вспомнить, у кого сейчас это твое ожерелье. Кстати... Говорят, у тетушки Бернис получаются отличные пироги со свининой.$B$BПринеси ей нежной кабанины – около ферм кабанов видимо-невидимо – и попроси испечь для тебя пирог.', '', '', '', '', '', 'Вернитесь к "Тетушке" Бернис Стоунфилд на ферму Стоунфилдов, что в Элвиннском лесу.', 19865),
(87, 'ruRU', 'Фикс', 'Верните ожерелье тетушке Бернис на ферму Стоунфилдов.', 'Я играл около рудника Подземных Глубин и, похоже, уронил... М-м... В смысле, я там видел ожерелье этой самой дамы. Не знаю, как оно попало туда... я тут ни при чем!$B$BВ общем, короче, я видел, как здоровенный кобольд с золотыми зубами схватил ожерелье и скрылся в своем логове над шахтой. Если отыщешь этого кобольда, найдешь и ожерелье, точно тебе говорю!', '', '', '', '', '', 'Вернитесь к "Тетушке" Бернис Стоунфилд на ферму Стоунфилдов, что в Элвиннском лесу.', 19865),
(88, 'ruRU', 'Принцесса должна умереть!', 'Убейте Принцессу, заберите ее ошейник и отнесите на ферму мамаше Стоунфилд.', 'У семейства Бреквеллов имеется свинья. Не простая, а призовая, по кличке Принцесса. И эта громадная гора сала то и дело пробирается на мой огород и пожирает мои овощи!$B$BИ так вышло, что сейчас она как раз там! Принцесса должна умереть! Принеси мне ее ошейник в доказательство того, что это свершилось, а взамен получишь кое-что полезное!$B$BТы найдешь Принцессу прямо в центре арбузного поля. Убей ее!', '', '', '', '', '', 'Вернитесь к мамаше Стоунфилд на ферму Стоунфилдов, что в Элвиннском лесу.', 19865),
(89, 'ruRU', 'Мост Безмолвия', 'Принесите 5 железных пик и 5 железных клепок штейгеру Ослоу в Приозерье.', 'Из-за последнего нашествия орков нам пришлось переплавить весь металл на пули, мечи и доспехи. Мы посылали в Штормград за новыми поставками, но отряд гноллов Красногорья разграбил обоз и сбежал в холмы за Приозерьем.$b$BНам не хватает материалов на ремонт моста. Если ты принесешь мне 5 железных пик и 5 железных клепок, $n, я прикажу тебя наградить.$B$BЗа дело!', '', '', '', '', '', 'Вернитесь к штейгеру Ослоу в Приозерье, что в Красногорье.', 19865),
(91, 'ruRU', 'Закон Соломона', 'Принесите 10 подвесок Темношкуров помощнику судьи Конаху в ратушу Приозерья.', 'В восточных предгорьях нашего края обосновался враг Штормграда. С помощью тайной магии этот негодяй по имени Моргант сеет ужас и страдания в нашем городе и окрестностях.$b$bОн прибрал под свою руку гноллов из стаи Темношкуров, и они исполняют его повеления. Согласно закону Приозерья, пособничество врагу королевства карается смертью.$b$bГноллов следует уничтожить!$b$bПринеси мне 10 подвесок Темношкуров и получишь награду.', '', '', '', '', '', 'Вернитесь к помощнику судьи Конаху в Приозерье, что в Красногорье.', 19865),
(92, 'ruRU', 'Гуляш по-красногорски', 'Принесите Бреанне пять кусков жесткого мяса кондора, пять рыл большого кровоклыка и пять порций хрустящего паучьего мяса.', 'Я бы с радостью сделала для тебя гуляш по-красногорски, но есть небольшое затруднение. Во время недавнего вторжения орков мне пришлось кормить целый отряд солдат Штормграда, и все кладовые опустели... Хотя если ты снабдишь меня всеми необходимыми продуктами, я уж расстараюсь!$b$bПринеси мне пять кусков жесткого мяса кондора, пять рыл больших кровоклыков и пять порций хрустящего паучьего мяса.', '', '', '', '', '', 'Вернитесь к шеф-повару Брианне в Приозерье, что в Красногорье.', 19865),
(95, 'ruRU', 'Месть Свена', 'Выясните, что зарыто за старым пнем на ферме, где работал Свен.', 'Раньше я работал на одной из ферм на юго-востоке... а потом темные всадники спустились с перевала Мертвого Ветра и перебили всю мою семью, пока я был в отлучке!$B$BВернувшись, я увидел неподалеку от амбара неясную фигуру человека, который что-то закапывал. Он успел сбежать от меня, а задерживаться я не мог, потому что преследовал темных всадников. Так я и не узнал, что там спрятано.$B$BЕсли ты можешь выяснить, что закопал в землю этот незнакомец, я буду очень признателен. Поищи возле старого пня, рядом с амбаром.', '', '', '', '', '', '', 19865),
(101, 'ruRU', 'Тотем кары', 'Принесите 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда мадам Еве в Темнолесье.', 'По лесу расползается тление и порча, $n, и все мы вынуждены позаботиться о самозащите. Ветер несет мне вести о великой опасности, поджидающей тебя в ближайшем будущем.$b$bЕсли ты желаешь оградить себя от нее, $gблагородный:благородная:c; |3-6($c), принеси мне 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда. Тогда я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя.', '', '', '', '', '', 'Вернитесь к мадам Еве в Темнолесье, что в Сумеречном лесу.', 19865),
(102, 'ruRU', 'Патрулирование Западного Края', 'Принесите капитану Данувину на Сторожевой холм 8 лап гноллов.', 'Штормград отвернулся от нас. Злобный ветер несчастий носится по равнинам Западного Края. Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь. Мы, бывшие фермеры, намерены постоять за себя.$b$bТвое задание, если ты за него возьмешься, будет состоять в том, чтобы патрулировать луга Западного Края. Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мертвых копей. Принеси мне 8 лап гноллов, и я вознагражу тебя за проявленное мужество.', '', '', '', '', '', 'Вернитесь к капитану Данувину на Сторожевой холм, что в Западном Крае.', 19865),
(106, 'ruRU', 'Юные влюбленные', 'Отдайте любовное послание Мейбелл Томми Джо Стоунфилду.', 'За что мне это наказание? Мое сердце отдано Томми Джо Стоунфилду, я жить без него не могу, но наши родители – заклятые враги! Я не только встретиться – даже взглянуть на него не могу!$B$BПожалуйста, отнеси Томми Джо это письмо. Он обычно бывает у реки к западу от фермы Стоунфилдов, а сама ферма – тоже к западу отсюда...', '', '', '', '', '', '', 19865),
(107, 'ruRU', 'Записка для Вильяма', 'Отнесите записку бабули Стоунфилд Вильяму Песту.', 'Бьюсь об заклад, у Вильяма Песта найдется зелье, которое поможет соединить наших юных влюбленных!$B$BВот, держи: отнесешь эту записку Вильяму. Найдешь его в Златоземье, в таверне "Гордость льва".', '', '', '', '', '', '', 19865),
(109, 'ruRU', 'Доклад Гриану Камнегриву', 'Поговорите с Грианом Камнегривом. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.', 'Похоже, |3-6($c), тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву. Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.', '', '', '', '', '', '', 19865),
(110, 'ruRU', 'Анализ частей насекомых', 'Найдите в Прибамбасске алхимика Пестычинса и получите результаты анализа частей насекомых.', 'Мне понадобится время на изучение оборудования Холстомера... и на приведение в порядок его дел. Ох, печенкой чую, не последняя это потеря, проклятые жуки еще покажут нам, где раки зимуют!$b$bПоговори, пожалуйста, с алхимиком Пестычинсом, узнай, как проходят исследования частей насекомых. Если все готово, принести мне результаты.', '', '', '', '', '', '', 19865),
(111, 'ruRU', 'Разговор с бабулей', 'Поговорите с бабулей Стоунфилд.', 'Прошу тебя, $n, поговори с моей бабулей. Если кто и может сделать так, чтобы мы с Мейбелл были вместе, так это она.$B$BБабуля сейчас дома – это к востоку отсюда...', '', '', '', '', '', '', 19865),
(112, 'ruRU', 'Хрустальный фукус', 'Принесите Вильяму Песту в Златоземье 4 ветки хрустального фукуса.', 'Да, я могу приготовить для Мейбелл напиток невидимости, чтобы она могла убежать с Виноградников Маклура к своему Томми Джо. Но для этого мне нужен хрустальный фукус.$B$BЭти водоросли растут в океане, и мурлокам иногда удается добыть их. Может, у тех, что живут на берегах Хрустального Озера, найдется нужный компонент.Озеро находится к востоку от Златоземья.', '', '', '', '', '', 'Вернитесь к Вильяму Песту в Златоземье, что в Элвиннском лесу.', 19865),
(113, 'ruRU', 'Анализ частей насекомых', 'Отнесите отчет старшему исследователю Рудознатцу в Прибамбасск. Получите копию отчета, как просил алхимик Пестычинс.', 'Старший геодезист Рудознатец должен немедленно увидеть мой отчет. Более того... его должны увидеть все, кто умеет читать. Серьезная опасность грозит не только Танарису и Прибамбасску, но если сидеть, сложа руки, то и всему южному Калимдору. Да что там, всему Азероту – эти твари не собираются останавливаться.$b$bПусть Рудознатец сделает копию моего отчета, распространи ее среди всех своих союзников. Пусть все узнают об этом!', '', '', '', '', '', '', 19865),
(114, 'ruRU', 'Бегство', 'Отнесите напиток невидимости Мейбелл Маклур.', 'Отнеси этот напиток невидимости юной Мейбелл. Его действия хватит на то, чтобы девушка успела встретиться с Томми Джо.', '', '', '', '', '', '', 19865),
(115, 'ruRU', 'Темная магия', 'Принесите 3 полуночных сферы маршалу Маррису в Приозерье.', 'Орки из клана Черной горы позвали на помощь чародеев, а те принесли с собой источники темной силы – полуночные сферы. Чародеи наносят чувствительные удары по защитникам Красногорья, и мы должны как можно скорее лишить их столь мощного оружия.$B$BДобудь для меня полуночные сферы. Ты найдешь их у чародеев Черной горы. Я придумаю, как избавиться от Сфер, чтобы мир стал лучше и чище!', '', '', '', '', '', 'Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.', 19865),
(116, 'ruRU', 'Сухие времена', 'Принесите кабатчику Дэниэлсу из Приозерья бочонок светлого громоварского из Западного края, бочонок "Мерло" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья.', 'У меня возникло небольшое затруднение, $n. Еще немного, и все бутылки опустеют, а поставок алкоголя давно не было. Проклятые орки.$b$bНе хочешь подзаработать?$b$BПринеси мне бочонок светлого громоварского от Мрачнобуха Громовара из Западного Края, бочонок "Мерло" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу.', '', '', '', '', '', 'Вернитесь к кабатчику Дэниэлсу в Приозерье, что в Красногорье.', 19865),
(117, 'ruRU', 'Громоварское светлое', 'Принесите Мрачнобуху Громовару 5 шишек хмеля.', 'Торопись, мой друг, и иди побыстрей,$bЧтоб нашего пойла отведать скорей.$bОно ближе к пиву – не спутаешь с кашей,$bНо нужен нам хмель, чтоб сварить пойло наше.', '', '', '', '', '', 'Вернитесь к Мрачнобуху Громовару на Холмы Кинжалов, что в Западном Крае.', 19865),
(118, 'ruRU', 'Цена подков', 'Отнесите записку Вернера кузнецу Аргусу в Златоземье, что в Элвиннском лесу.', 'Я потратил так много железа на доспехи и оружие для стражников Штормграда, что теперь его не хватает даже на подковы для лошадей!$B$BОтнеси эту записку кузнецу Аргусу в Златоземье, я хочу попросить его прислать мне партию подков.', '', '', '', '', '', '', 19865),
(119, 'ruRU', 'Доставка подков', 'Вернитесь к Вернеру Осгуду в Приозерье, что в Красногорье. Отдайте ему ящик с подковами.', 'Ладно, так и быть, пошлю ему 50 подков...$B$BВот они, уже упакованы, осталось только доставить! Передай Вернеру, что с ним приятно иметь дело. Пусть не забудет прочитать записку, прикрепленную к ящику!', '', '', '', '', '', '', 19865),
(120, 'ruRU', 'Гонец в Штормград', 'Мировой судья Соломон просит вас отнести отчет генералу Маркусу Джонатану в Штормград.', 'Тяжелые настали времена, |3-6($c). Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять. Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану. И поскорее возвращайся с вестями – неважно, добрыми или злыми.$b$bСпеши!', '', '', '', '', '', '', 19865),
(121, 'ruRU', 'Гонец в Штормград', 'Отнесите ответ генерала Маркуса Джонатана мировому судье Соломону в Приозерье.', 'Пока я жду ответа от короля, хочу, чтобы ты $gотнес:отнесла; это письмо мировому судье Соломону. $B$B$GСвободен:Свободна;, |3-6($c)!', '', '', '', '', '', '', 19865),
(122, 'ruRU', 'Брюшная чешуя', 'Добудьте 6 лоскутов чешуи с брюха черных дракончиков и отнесите их Вернеру Осгуду в Красногорье.', 'В обмен на подковы Аргус из Златоземья просит брюшную чешую черных дракончиков. Если ты добудешь мне 6 лоскутов чешуи, я смогу расплатиться с Аргусом... И для тебя что-нибудь сделаю.$B$BЧерных дракончиков можно отыскать к югу от Приозерья, но им не сидится на одном месте. Проще всего высматривать их, направляясь по другим делам, и охотиться по случаю.', '', '', '', '', '', 'Вернитесь к Вернеру Осгуду в Приозерье, что в Красногорье.', 19865),
(123, 'ruRU', 'Вымогатель', 'Отправляйтесь к маршалу Маккри на лесопилку Восточной долины, что в Элвиннском лесу, и отдайте ему расписание Вымогателя.', 'На этом листке – расписание поставок золота из рудников в Элвиннском лесу. Поставки расписаны по дням и часам, а в качестве получателя указан некий "Вымогатель".$B$BСудя по всему, Вымогатель обосновался неподалеку от тыквенного поля Бреквеллов в восточной части Элвиннского леса.$B$BПохоже, это важные сведения. Было бы неплохо сообщить их маршалу Маккри, он сейчас на лесопилке Восточной долины.', '', '', '', '', '', '', 19865),
(124, 'ruRU', 'Лай гноллов', 'Убейте 10 громил из стаи Красногорья и 8 мистиков из стаи Красногорья. Вернитесь к Вернеру Осгуду.', 'Будто нам одних орков мало! А теперь вдоль хребта рядом с моими стойлами шастают громилы и мистики гноллов и при случае воруют лошадей...$B$BЕсли ты сможешь избавить меня от этих проходимцев, мы с лошадьми будем весьма признательны.', '', '', '', '', '', 'Вернитесь к Вернеру Осгуду в Приозерье, что в Красногорье.', 19865),
(125, 'ruRU', 'Утраченные инструменты', 'Достаньте ящик с инструментами штейгера Ослоу со дна Озера Безмолвия.', 'Мне не помешала бы помощь, $n. Наш город в осаде, и достать припасы и оборудование все труднее. Мои инструменты везли из Златоземья в фургоне, но мост был уничтожен. Мы перегрузили их в лодку, но тут орки пробили ее снарядом из катапульты! И вот невезенье, ящик опустился на самое дно озера.$b$bДостань его, $n, и я щедро вознагражу тебя.', '', '', '', '', '', 'Вернитесь к штейгеру Ослоу в Приозерье, что в Красногорье.', 19865),
(126, 'ruRU', 'Вой в холмах', 'Принесите лапу Изувоя Вернеру Осгуду в Приозерье.', '$n, гноллы по-прежнему здесь. Я слышу, как они завывают, охотясь в холмах над Приозерьем. И один из них воет громче других – это Изувой, их вождь.$B$BСтоит его прикончить, и вся стая разбежится! Убей его и принеси в доказательство отрубленную лапу.$B$BСоблюдай осторожность, этот гнолл заслуженно возглавляет целую стаю. Он совсем не прост...', '', '', '', '', '', 'Вернитесь к Вернеру Осгуду в Приозерье, что в Красногорье.', 19865),
(127, 'ruRU', 'Продажа рыбы', 'Принесите 10 тушек пятнистой рыбы-луны портовому начальнику Барену в Приозерье.', 'Озеро Безмолвия славится пятнистой рыбой-луной. На нее всегда есть спрос... А мой запас подходит к концу!$B$BПринеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты $gсам:сама; не умеешь удить, то... Попытайся отнять рыбу у мурлоков!', '', '', '', '', '', 'Вернитесь к портовому начальнику Барену в Приозерье, что в Красногорье.', 19865),
(128, 'ruRU', 'Награда за головы орков Черной горы', 'Убейте 15 воителей из клана Черной горы.', 'Мы должны уничтожить клан Черной горы. Враг вторгся в наши земли. Эти горы по праву принадлежат королю Штормграда. До нас дошли сведения, что главы всех видов войск клана называются воителями. Их можно отыскать в северном лагере, к западу от дороги, ведущей в Пылающие степи.$b$bМировой судья Соломон распорядился перебить этих гнусных тварей. Убей 15 воителей из клана Черной горы и возвращайся ко мне.', '', '', '', '', '', 'Вернитесь к стражнику Хоуву в Приозерье, что в Красногорье.', 19865),
(132, 'ruRU', 'Братство Справедливости', 'Отнесите записку Вилли Гриану Камнегриву в Западный Край.', 'То, о чем я хочу вам рассказать, может стоить мне жизни. Бандиты из Братства Справедливости замышляют что-то крупномасштабное. Последнее, что я слышал, – что они действуют заодно со всякими гноллами, кобольдами и даже гоблинами.$b$bОтнеси эту записку Камнегриву. В ней разъясняется все, что я знаю на эту тему.', '', '', '', '', '', '', 19865),
(133, 'ruRU', 'Чучело вурдалака', 'Добудьте 7 ребер вурдалаков и принесите их в хижину Аберкромби.', 'Я живу вдали от города, никто меня не защищает, и даже странно, как это меня до сих пор не сожрали вурдалаки и мертвяки! Только вчера несколько костеглодов ломились ко мне в дом!..$B$BЯ хочу сделать особую фигурку – что-то вроде пугала для этой нежити. Для этого мне понадобится несколько ребер вурдалаков. Их можно добыть, убивая плотоядов, костеглодов, мозгоедов, гнилую нежить и распространителей чумы.$B$BПринеси мне ребра, и я дам тебе несколько монет.', '', '', '', '', '', 'Вернитесь к Аберкромби на Кладбище Вороньего Холма, что в Сумеречном лесу.', 19865),
(137, 'ruRU', '<NYI> <TXT> Рекомендация Штормграда', 'Отдайте генералу Маркусу Джонатану в Штормграде рекомендации из Элвиннского леса.', 'Если у тебя есть рекомендации от одного из наших маршалов, покажи их мне. Взамен я дам тебе пару Львиных перчаток.', '', '', '', '', '', 'Вернитесь к генералу Маркусу Джонатану на Аллею Героев, что в Штормграде.', 19865),
(147, 'ruRU', 'Охота на человека', 'Найдите и убейте "Вымогателя", а затем принесите его кольцо маршалу Маккри.', 'Если Вымогатель забирает золото с наших рудников, значит, он обворовывает королевство! Он должен предстать перед судом – а мне понадобится то кольцо, которое упоминалось в записке. Возможно, оно поможет нам узнать, на кого работает этот Вымогатель...$B$BЗдесь написано, что Вымогатель скрывается на тыквенном поле Бреквеллов. Попробуй поискать его там.', '', '', '', '', '', 'Вернитесь к маршалу Маккри на лесопилку Восточной долины в Элвиннском лесу.', 19865),
(148, 'ruRU', 'Припасы из Темнолесья', 'Поговорите с мадам Евой.', 'Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели.$B$BНе $gмог:могла; бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Ее можно приобрести у мадам Евы, которая живет на центральной площади города.', '', '', '', '', '', '', 19865),
(150, 'ruRU', 'Мурлоки-браконьеры', 'Принесите 8 плавников мурлоков портовому начальнику Барену в Приозерье.', 'Мурлоки начинают нас беспокоить. Все больше мурлокских рыбаков селится вдоль побережья Озера Безмолвия и вовсю ловит рыбу! Надо изгнать их, пока они не опустошили все озеро!$B$BУбей побольше мурлоков! Принеси мне восемь их плавников, и я найду, чем тебе отплатить...', '', '', '', '', '', 'Вернитесь к портовому начальнику Барену в Приозерье, что в Красногорье.', 19865),
(151, 'ruRU', 'Бедная старая Савраска', 'Принесите 8 горстей овса Верне Хмуробров.', 'Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений... Я ее покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге. Я была бы вам очень благодарна, $gсэр:леди;, если бы вы могли принести ей несколько горстей овса с окрестных полей.$b$bУверена, что вы найдете овес на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях. К юго-западу отсюда расположено несколько фермерских хозяйств.', '', '', '', '', '', 'Вернитесь к Верне Хмуробров во Владение Янсена, что в Западном Крае.', 19865),
(152, 'ruRU', 'Борьба за чистоту берегов', 'Убейте 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков-мурлоков и вернитесь к капитану Грейсону на Маяк в Западном Крае.', 'Ты, должно быть, $gвидел:видела; все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово. Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности. На сегодняшний день мурлоки являются большой проблемой...$b$bРазберись с ними – убей 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков, – и награда будет ждать тебя.', '', '', '', '', '', 'Вернитесь к капитану Грейсону к маяку в Западном Крае.', 19865),
(153, 'ruRU', 'Красные кожаные банданы', 'Принесите разведчику Галиану на Сторожевой холм 15 красных кожаных бандан.', 'В Братстве Справедливости идет постоянная кипучая деятельность. Я уже долго слежу за их передвижениями. Между прочим, я заметил, что многих бандитов можно опознать по красным кожаным банданам.$b$bПринесите мне 15 таких бандан, и я позабочусь о том, чтобы вы получили вознаграждение.', '', '', '', '', '', 'Вернитесь к разведчику Галиану на Сторожевой холм, что в Западном Крае.', 19865),
(154, 'ruRU', 'Гребень для Евы', 'Верните гребень для призрачных волос мадам Еве в Темнолесье.', 'НЕТ!!!$B$BУбери его, убери от меня этот гребень!$B$BЯ чудовище, меня больше никто не назовет прекрасной!', '', '', '', '', '', '', 19865),
(162, 'ruRU', 'Возвышение силитидов', 'Отнесите отчет о наблюдении за насекомыми Грацине Силе Духа в Дарнас.', 'Прошу тебя, отнеси этот отчет кому-нибудь, сведущему в такого рода вопросах.$b$bЯ слышал про одну ночную эльфийку по имени Грацина Сила Духа. Она посвятила много времени изучению форм жизни, встречающихся лишь в Азероте; она и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к ней. Нам любая помощь не помешает.$b$bГоворят, она сейчас в Храме Луны в Дарнасе.', '', '', '', '', '', '', 19865),
(163, 'ruRU', 'Вороний Холм', 'Выясните, кто поселился на Вороньем Холме.', 'Что-то неладно на Вороньем Холме, $n. Калор клянется, что он заметил кого-то – или что-то – в одном из домов. Две ночи подряд он видел крадущиеся тени, а на третью – свет в одном из окон.$b$bЕсли тебя и в самом деле беспокоит безопасность Темнолесья, выясни, что за чудовище скрывается на Вороньем холме.', '', '', '', '', '', '', 19865),
(164, 'ruRU', 'Припасы для Свена', 'Отнесите Свену припасы.', 'Ты знаешь Свена? Вот кто настоящий служитель Света! Он и его последователи стоят лагерем в северо-западной части Сумеречного леса.$b$bУвы, их так мало, что некого отправить за припасами в город. Не поможешь ли ты ему?', '', '', '', '', '', '', 19865),
(165, 'ruRU', 'Отшельник', 'Навестите старика в хижине рядом с кладбищем Вороньего холма.', 'Одно время в город частенько приходил старик и покупал припасы, но в последнее время я его не видела. Он живет в хижине рядом с кладбищем Вороньего холма, если я верно запомнила. Не навестишь ли ты его? Вдруг с ним что-то случилось?', '', '', '', '', '', '', 19865),
(167, 'ruRU', 'О, брат мой...', 'Принесите значок Лиги исследователей, принадлежавший Вилдеру Крапивцу, в Штормград.', 'Мы находились в обширных шахтах Западного Края, скрытых глубоко под землями Луноречья. Понятия не имею, откуда явились эти мерзкие вороватые вонючки. Так или иначе – туннель обрушился на нас. Мне удалось выбраться, но остальные... о них я ничего не знаю.$b$bВдруг тебе повезет больше, чем мне? Я ищу своего брата. Он всегда носил значок Лиги исследователей. Если ты не найдешь брата, постарайся найти хотя бы его значок.', '', '', '', '', '', 'Вернитесь к Вилдеру Крапивцу в Штормград.', 19865),
(168, 'ruRU', 'Сбор воспоминаний', 'Добудьте 4 карточки Союза шахтеров и верните их Вилдеру Крапивцу в Штормград.', 'Многие из моих друзей погибли в тот роковой день, когда обрушился штрек. Если тебя как-нибудь занесет в ту шахту в Луноречье, пожалуйста, постарайся добыть что-то, что поможет их опознать. А если найдешь их карточки Союза шахтеров, принеси их мне, я отправлю их семьям погибших.', '', '', '', '', '', 'Вернитесь к Вилдеру Крапивцу в Штормград.', 19865),
(169, 'ruRU', 'Разыскивается: Гат''Илзогг', 'Убейте Гат''Илзогга и принесите его голову мировому судье Соломону в Приозерье.', 'Розыск! Гат''Илзогг, вождь клана Черной горы, разыскивается за нападение на крепость Каменной Стражи и набеги на окрестности Приозерья. $b$bГат''Илзогг крайне опасен. По последним сведениям, он находится в недавно захваченной крепости и замышляет новые преступления против Королевства. Нашествие орков должно быть остановлено любой ценой. Храбрец, доставивший голову Гат''Илзогга мировому судье Соломону, будет щедро вознагражден.', '', '', '', '', '', 'Вернитесь к мировому судье Соломону в Приозерье, что в Красногорье.', 19865),
(171, 'ruRU', 'Опекун Альянса', 'Купите стойку с пластиковыми мечами у Крэггла Головодерга, а затем отведите своего подопечного-сироту обратно в приют Штормграда и верните детскую свистульку попечительнице сирот Найтингейл в Соборном квартале Штормграда.', 'Ты $gбыл:была; очень $gдобр:добра; ко мне, $n. Я и представить не мог, что Детская неделя пройдет так весело. Спасибо.$b$bВот бы всем ребятам в приюте повезло, как мне, – мы сделали столько всего интересного! Как ты думаешь, сможем мы еще раз найти Крэггла Головодерга и купить у него стойку с пластиковыми мечами? Думаю, он так и ходит со своей тележкой поблизости от Торгового квартала. Тогда и остальные ребята в приюте тоже смогут повеселиться!$b$bА после этого я вернусь домой.', '', '', '', '', '', 'Вернитесь к попечительнице сирот Найтингейл в Штормград.', 19865),
(172, 'ruRU', 'Детская неделя', 'Воспользуйтесь орочей детской свистулькой. Присматривайте за сиротой в течение Детской недели.', 'Ты хочешь помочь сиротам? Да благословят тебя боги! Твоя помощь во время Детской недели будет очень кстати!$b$bВот, возьми эту свистульку. Действовать она будет недолго – до конца Детской недели. Свистни в нее – и появится сирота, за которым ты обещаешь присматривать. Свистни еще раз – ребенок уйдет.$b$bПрошу тебя, $n, пользуйся свистулькой почаще, не забывай своего подопечного! Для детей это так важно...', '', '', '', '', '', '', 19865),
(173, 'ruRU', 'Воргены в лесу', 'Калор из Темнолесья просит вас убить 6 тенеткачей Ночной Погибели.', 'На Сумеречный лес наступают силы тьмы, и цель мастера Карвина – борьба с этим злом. Благодаря нашим усилиям народ Темнолесья живет в безопасности.$b$bТы считаешь, что $gдостоин:достойна; вступить в наши ряды?$b$bКогда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Карвина. Если ты хочешь показать, на что $gспособен:способна;, то слова тебе не помощники.$b$bВыступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду.', '', '', '', '', '', 'Вернитесь к Калору в Темнолесье, что в Сумеречном лесу.', 19865),
(175, 'ruRU', 'Взгляни на звезды', 'Найдите Мэри и уговорите ее пожертвовать зеркало для проекта Виктора.', 'Согласно чертежам Кога, мне нужно отыскать способ отражать свет. Помнится, есть у нас одна особа по имени Мэри, которая вечно таскает с собой зеркальце. Может быть, ты отыщешь ее и она одолжит нам свою отражающую поверхность? Кажется, она когда-то жила в южной части Сумеречного леса.', '', '', '', '', '', '', 19865),
(176, 'ruRU', 'Разыскивается: "Дробитель"', 'Решите "проблему с Дробителем" и вернитесь к маршалу Дугхану.', 'Разыскивается: Дробитель$B$BВ юго-западной части Элвиннского леса рыщет могучий гнолл по прозванию Дробитель. Несмотря на все усилия, поймать его так и не удалось.$B$BАрмия Штормграда назначила за этого гнолла щедрую награду. Чтобы получить ее, необходимо пробраться в леса и убить Дробителя.', '', '', '', '', '', 'Вернитесь к маршалу Дугхану в Златоземье, что в Элвиннском лесу.', 19865),
(179, 'ruRU', 'Дворфийские экипировщики', 'Принесите Стену Крепкоруку 8 кусков жесткого волчьего мяса.', 'Ну-ка, ну-ка, что тут у нас?.. Холодновато в наших краях, верно? Готов спорить, у тебя все время мерзнут руки. Ну, угадал?$b$bЯ скажу, что тебе нужно: пара хороших теплых перчаток. Ну да, душа у меня добрая, так что замерзнуть я тебе не дам. Только вот есть одно условие.$b$bПринеси мне волчьего мяса – и мы, считай, в расчете. Справедливо, как думаешь? Мне – мясо, а уж я-то позабочусь о том, чтобы у тебя пальцы больше не мерзли. Ну, что скажешь?', '', '', '', '', '', 'Вернитесь к Стену Крепкоруку в Холодную долину, что в Дун Мороге.', 19865),
(180, 'ruRU', 'Разыскивается: лейтенант Фангор', 'Убейте лейтенанта Фангора и принесите его лапу мировому судье Соломону в Приозерье.', 'Разыскивается: лейтенант Фангор$b$bГлава гнолльской стаи Темношкуров, соратник Морганта, врага Города и Королевства. По приказу чиновника Соломона подлый предатель Штормграда приговаривается к смерти. Тот, кто приведет приговор в исполнение, должен в доказательство принести лапу Фангора мировому судье Соломону.', '', '', '', '', '', 'Вернитесь к мировому судье Соломону в Приозерье, что в Красногорье.', 19865),
(181, 'ruRU', 'Взгляни на звезды', 'Отыщите Ззарк''Вула в кургане на юге Сумеречного леса и принесите его монокль Виктору в Темнолесье.', 'Для завершения работы не хватает только одного предмета. Согласно чертежам Кога, нам нужна линза. Единственную подходящую линзу в наших краях будет нелегко достать.$B$BВ кургане на юге Сумеречного леса живет огр по имени Ззарк''Вул. Если сможешь, принеси мне его монокль, и я использую его вместо линзы!', '', '', '', '', '', 'Вернитесь к Виктору Призм’’Антрасу в Темнолесье, что в Сумеречном лесу.', 19865),
(182, 'ruRU', 'Угроза атаки троллей', 'Убейте 10 троллей-подростков из племени Мерзлогривов.', 'Тролли проявляют какую-то небывалую активность. Мы и раньше видели, что они иногда собирают боевые отряды, но чтобы такое...$b$bОсобенно меня беспокоит защита Старой Наковальни. Мне совсем не хочется, чтобы тролли атаковали Старую Наковальню в то время, как все наши силы брошены на троггов. Прореди немного их ряды. Пусть знают, что мы не беззащитны.', '', '', '', '', '', 'Вернитесь к Грелину Белобороду в Дун Морог.', 19865),
(183, 'ruRU', 'Охотник на вепрей', 'Убейте 12 малых скальных вепрей по просьбе Талина Остроглаза.', 'Нет ничего лучше охоты на диких вепрей, верно?$b$bПравда, здесь, в Холодной долине, их расплодилось столько, что весь интерес пропадает. Их и загонять не надо – они злые, как демоны, и сами бросаются прямо на охотника. Я бы даже сказал, что этих злобных свиней так много, что и охотиться-то стало опасно...$b$bКороче говоря, я буду благодарен, если ты поможешь мне прикончить хотя бы нескольких кабанов.', '', '', '', '', '', 'Вернитесь к Талину Остроглазу в Холодную долину, что в Дун Мороге.', 19865),
(184, 'ruRU', 'Документ Хмуроброва', 'Доставьте документ Хмуроброва во Владение Янсена в Западном Крае.', 'Это закладная на ферму в Западном Крае. Она подписана Теодором Хмуробровом и его женой, Верной. На обороте документа торопливо нацарапаны слова:$B$B"Мы нажали на Хмуроброва и получили от него нужную бумагу. Если тебе захочется заполучить один из участков, она тебе пригодится.$B$BС Хмуробровами проблем не предвидится: я видел, как они покидают Западный Край, у них как раз телега сломалась."$B$BНаверное, Хмуробровы были бы рады получить этот документ назад...', '', '', '', '', '', '', 19865),
(185, 'ruRU', 'Охота на тигров', 'Выследите 10 молодых тигров Тернистой долины.', 'Когда я была юной девушкой, мой отец обучил меня искусству охоты на тигров.$B$BМолодых тигров куда легче выследить и убить. Тигрят полно вокруг нашего лагеря.$B$BТак что проверь, как ты умеешь брать след, и попробуй выследить несколько зверей. Начинай охотиться к югу от лагеря.', '', '', '', '', '', 'Вернитесь к Аджек Руак в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.', 19865),
(186, 'ruRU', 'Охота на тигров', 'Убейте 10 тигров Тернистой долины.', 'Одно дело тигрята, совсем другое – взрослые хищники. Но самым сложным испытанием станет охота на взрослых тигров Тернистой долины.$b$bОбычно взрослые тигры бродят к югу от Лагеря Курцена восточнее реки.', '', '', '', '', '', 'Вернитесь к Аджек Руак в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.', 19865),
(187, 'ruRU', 'Тигриная отвага', 'Убейте 5 старых тигров Тернистой долины.', 'Старые тигры Тернистой долины – самые матерые. Немало |3-8($c) из числа |3-8($r) погибло от их зубов и острых как бритвы когтей.$B$BЕсли тебе удастся одолеть этих тварей, такая новость, несомненно, порадует Аджек. Большая популяция матерых тигров обитает к югу отсюда, вблизи Разлома, на границе с мысом Тернистой долины.', '', '', '', '', '', 'Вернитесь к Аджек Руак в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.', 19865),
(188, 'ruRU', 'Охота на тигров', 'Убейте Син''Далл и вернитесь с ее лапой.', 'В легендах говорится о хитрой тигрице... настолько могучей, что силой она превосходила даже взрослых самцов. Охотники из экспедиции Эрнестуэя пытались ее выследить, но безуспешно. Многие из них были растерзаны ее могучими когтями. Останки несчастных еще можно найти на горных склонах к северу от Гром''гола.$b$bЭту тигрицу зовут Син''Далл.$B$BТы сделаешь то, что $gни одному:ни одной:r; |3-2($r) раньше не удавалось: выследи, убей зверя и принеси лапу Син''Далл.', '', '', 'Син''Далл', '', '', 'Вернитесь к Аджек Руак в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.', 19865),
(189, 'ruRU', 'Уши троллей Кровавого Скальпа', 'Добудьте 15 ушей троллей из племени Кровавого Скальпа и принесите их Кебоку в Пиратскую Бухту.', 'Проклятые тролли! Они постоянно убивают наших агентов! Я потерял в стычках с ними лучших своих бойцов. Цена операции все растет и растет! Как я объясню это барону Ревилгазу?$B$BНужно действовать решительно... Думай, Кебок... Тебя назначили на эту должность не за безделье... Придумал! Тебя... $n зовут, правда? Ты ведь мне поможешь? А уж я заплачу!$B$BПредлагаю сделку... ты принесешь мне уши пятнадцати троллей из племени Кровавого Скальпа, а я дам тебе денег.', '', '', '', '', '', 'Вернитесь к Кебоку в Пиратскую Бухту, что в Тернистой долине.', 19865),
(190, 'ruRU', 'Охота на пантер', 'Убейте 10 молодых пантер.', 'Если хочешь работать вместе со спецами, которыми руководит Хеминг Эрнестуэй-младший, придется тебе доказать, что ты умеешь охотиться на пантер. Начни с самого простого – молодых пантер. По мере роста охотничьего мастерства тебе, несомненно, придется столкнуться с более сложными и опасными задачами.$B$BДля начала отправляйся на восток. Когда овладеешь искусством охоты на пантер, возвращайся.', '', '', '', '', '', 'Вернитесь к сэру С. Дж. Эрлджедину в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.', 19865),
(191, 'ruRU', 'По следу пантеры', 'Убейте на охоте 10 пантер.', 'С самыми молодыми пантерами справиться легко. Взрослые, как правило, сильнее и быстрее, так что их одолеть труднее. Они будут твоей следующей целью.$b$bСледы взрослых пантер ведут на запад.', '', '', '', '', '', 'Вернитесь к сэру С. Дж. Эрлджедину в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.', 19865),
(192, 'ruRU', 'Охота на пантер', 'Убейте 5 тенебрюхих пантер.', 'А теперь – самое трудное. Чем пантеры взрослее, тем хитрее. Они буквально сливаются с окружающей средой и их нелегко обнаружить. Этих хитрющих зверюг называют "тенебрюхими" за способность внезапно появляться из темноты... и набрасываться на добычу. А зубки у них о-го-го, можешь не сомневаться!$B$BЕсли хочешь, чтобы тебя признали $gнастоящим охотником:настоящей охотницей; на пантер, тебе нужно убить тенебрюхих пантер. А по-другому – никак. Эти животные встречаются на юго-востоке, за рекой.', '', '', '', '', '', 'Вернитесь к сэру С. Дж. Эрлджедину в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.', 19865),
(193, 'ruRU', 'Охота на пантер', 'Добудьте клык Баг''тиры.', 'Тебе почти удалось доказать, что ты $gвеликий охотник:великая охотница; на пантер. Множество песен сложено о могучей пантере по кличке Баг''тира, живущей в джунглях. Хватит у тебя сноровки с ней справиться?$B$BЧтобы доказать свое мастерство, принеси клык Баг''тиры Эрлджедину.', '', '', 'Баг''тира', '', '', 'Вернитесь к сэру С. Дж. Эрлджедину в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.', 19865),
(194, 'ruRU', 'Охота на ящеров', 'Убейте 10 ящеров Тернистой долины.', 'Значит, ты считаешь себя $gпревосходным охотником:превосходной охотницей;? Проверим. Ступай в джунгли и подстрели 10 ящеров Тернистой долины. Посмотрим, как ты справишься с крупной дичью.$B$BИ нет, я не скажу, где их искать! Поиск добычи – это, считай, половина испытания.$b$bЛадно, так и быть... Иди на запад.', '', '', '', '', '', 'Вернитесь к Хемингу Эрнестуэю-младшему в экспедицию Эрнестуэя, что в Северной Тернистой долине.', 19865),
(195, 'ruRU', 'Охота на ящеров', 'Убейте 10 ящеров-кнутохвостов.', 'Пришло время усложнить задачу. Пожалуй, отправиться в джунгли и разобраться с десятком ящеров-кнутохвостов – подходящее задание. Эти твари будут посильнее, чем те, с которыми тебе уже доводилось встречаться..$b$bЯщеры-кнутохвосты обитают, главным образом, к юго-востоку от нас, вблизи Руин Кал''аи.', '', '', '', '', '', 'Вернитесь к Хемингу Эрнестуэю-младшему в экспедицию Эрнестуэя, что в Северной Тернистой долине.', 19865),
(196, 'ruRU', 'Большая охота', 'Отправляйтесь на охоту и убейте 10 тропических ловцов.', 'Там в лесах за рекой к югу отсюда водятся особенно хитрые и осторожные ящеры, которых местные называют "тропическими ловцами". Их нелегко обнаружить и весьма непросто убить.$b$bЕсли успешно поохотишься на этих тропических ловцов, тебе будет чем похваляться, сидя у костерка...', '', '', '', '', '', 'Вернитесь к Хемингу Эрнестуэю-младшему в экспедицию Эрнестуэя, что в Северной Тернистой долине.', 19865),
(197, 'ruRU', 'Охота на ящеров', 'Убейте Тетис.', 'Прежде чем вернуться в лагерь экспедиции Эрнестуэя, тебе придется выполнить невыполнимое – убить ящера, которого не сумел одолеть ни один охотник. Эту тварь зовут Тетис. Данный зверь сеет ужас на юго-восточной окраине Северной Тернистой долины.$B$BПринеся коготь Тетис тому дворфу-охотнику, ты докажешь свое незаурядное дарование к охоте, |3-6($r).', '', '', 'Тетис', '', '', 'Вернитесь к Хемингу Эрнестуэю-младшему в экспедицию Эрнестуэя, что в Северной Тернистой долине.', 19865),
(201, 'ruRU', 'Поиск лагеря', 'Найдите лагерь охотников и сообщите о его местонахождении Кразеку из Пиратской Бухты.', 'Мне сообщили о группе охотников, разбивших лагерь вверх по реке от рудника Торговой Компании возле озера Назферити. Я бы не придал этому значения, но говорят, будто один из тамошних охотников – сам Хеминг Эрнестуэй-младший. Мне не верится, но у него настолько высокие связи, если ты понимаешь о чем я, что лучше заранее обезопасить себя.$B$BПочему бы тебе не заглянуть в этот лагерь и не разузнать, что они замышляют?', 'Отыщите лагерь охотников', 'Отыщите лагерь охотников', '', '', '', 'Вернитесь к Кразеку в Пиратскую Бухту, что в Тернистой долине.', 19865),
(203, 'ruRU', 'Второе восстание', 'Убейте 15 партизан Курцена.$B$BВернитесь к сержанту Йохве в Лагерь повстанцев.', 'Мы решительно проигрываем полковнику Курцену. Он не только блестящий тактик – его войска превосходят нас в численности в десять раз! Чтобы выжить, нам придется прибегнуть к его же подлой тактике.$B$BПроберись в лагерь на востоке и убей как можно больше его бойцов. И скройся до прибытия подкрепления.', '', '', '', '', '', 'Вернитесь к сержанту Йохве в Лагерь Повстанцев, что в Тернистой долине.', 19865),
(207, 'ruRU', 'Тайна Курцена', 'Найдите 4 таблички, перерисуйте их и принесите их брату Нимезу.', 'Когда-то полковник Курцен был великим и благородным человеком – я хочу выяснить, что заставило его свернуть с пути истинного! Должно быть, он находится под воздействием магии троллей. Надо изучить древние легенды, чтобы убедиться в этом.$B$BВ руинах тролльских городов в Тернистой долине спрятаны 4 таблички. Мне необходимо их добыть и прочесть! Перерисуй с них все отметки и принеси рисунки мне.$B$BПервая табличка находится в руинах Бал''лал, вторая – на Коварном рифе, а третья и четвертая – в руинах Зул''Кунды.', '', '', '', '', '', 'Вернитесь к брату Нимезу в Лагерь Повстанцев, что в Тернистой долине.', 19865),
(208, 'ruRU', 'Охотник на крупную дичь', 'Добудьте голову короля Бангалаша, огромного белого тигра.', '$n, ты $gдостоин:достойна; занять место среди нас. И на полях битвы в Лордероне, и в глубоких джунглях, мне редко приходилось видеть столь умелое обращение с оружием.$B$BТебе удалось убить свирепую Син''Далл, неуловимую Баг''тиру и коварную Тетис. Осталось одно – добыть голову короля Бангалаша. Давненько я точу зуб на этого белого тигра, обитающего к югу отсюда. Убей короля Бангалаша, и мы признаем, что тебе нет равных в искусстве охоты.', '', '', 'Король Бангалаш', '', '', 'Вернитесь к Хемингу Эрнестуэю-младшему в экспедицию Эрнестуэя, что в Северной Тернистой долине.', 19865),
(209, 'ruRU', 'Клыки троллей', 'Добудьте 18 клыков троллей из племени Дробителей Черепов и принесите их Кебоку в Пиратскую бухту.', 'Убивать тигров и добывать их клыки на экспорт в Южные моря – трудно и дорого. К счастью, мы придумали способ обрабатывать простые рогоподобные предметы и изготавливать неотличимые подделки.$B$BЛучше всего, как ни смешно, подходят клыки троллей из племени Дробителей Черепов.$B$BШ-ш-ш, спокойно, чем меньше знает покупатель, тем крепче он спит, верно? Принеси мне побольше таких клыков, чтобы мы могли подготовить ежемесячную поставку!', '', '', '', '', '', 'Вернитесь к Кебоку в Пиратскую Бухту, что в Тернистой долине.', 19865),
(210, 'ruRU', 'Горшок Кразека', 'Отнесите разбитый горшок Кразека гоблину Кразеку.', 'Готовка по большей части лежит на мне. И она доставляла мне много хлопот, пока я не купил механический горшок у одного гоблина в Пиратской Бухте. Это чудо какое-то! Он сэкономил мне много часов... Пока не сломался!$B$BМожет, ты отнесешь его назад к продавцу, в ремонт? Продавца зовут Кразек.', '', '', '', '', '', 'Поговорите с Кразеком в Пиратской Бухте, что в Тернистой долине.', 19865),
(211, 'ruRU', 'Увы тебе, Андорал', 'Принесите осколок оберега Аража командиру Ашламу Неутомимому в Лагерь Промозглого Ветра в Западных Чумных землях.', 'Увы, пришло время напасть на Андорал и изгнать оттуда лича!$b$bЗлобный Араж Призыватель обосновался в самом сердце руин. Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы. Без многочисленных помощников тебе нечего и думать одержать над ним верх.$b$bУбей Аража и принеси мне его кристалл-талисман!', '', '', '', '', '', 'Вернитесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра, что в Западных Чумных землях.', 19865),
(213, 'ruRU', 'Недружественное поглощение', 'Добудьте 8 упавших кристаллов и принесите их Кебоку в Пиратскую Бухту.', 'Он слишком далеко зашел! Мало того, что этот Гелриз теснит управляющих, назначенных торговыми олигархами, теперь он попытался обвести вокруг пальца знаменитейшего пирата!$B$BРевилгаз заявил, что не потерпит такого, и велел любым способом решить проблему.$B$BЛюбым способом? Я выбираю кражу. Геологов Торговой Компании, работающих рядом с озером Назферити, заинтересовали странные синие кристаллы, найденные в руднике. Принеси мне образцы этих камней, и меня не волнует, что тебе придется сделать с геологами для выполнения задания.', '', '', '', '', '', 'Вернитесь к Кебоку в Пиратскую Бухту, что в Тернистой долине.', 19865),
(215, 'ruRU', 'Тайны джунглей', 'Поговорите с лейтенантом Дореном в Лагере повстанцев.', 'Спасибо, что $gспас:спасла; меня, $n. Понимаю, как это выглядит... но позволь мне объяснить.$B$BЛейтенант Дорен поручил мне снова завербоваться к Курцену, чтобы следить за его солдатами и предоставлять столь необходимые сведения повстанцам. Ты $gвидел:видела;, чем обернулась для меня попытка проникнуть в лагерь Курцена. Я думал, что это – мой шанс... Еще раз спасибо за спасение.$B$BЭто была тайная миссия, никому о ней не говори. Но лейтенант Дорен может все объяснить.', '', '', '', '', '', 'Поговорите с лейтенантом Дореном в Лагере Повстанцев, что в Тернистой долине.', 19865),
(216, 'ruRU', 'Между молотом и Колючим Мехом', 'Каранг Амаккар из дозора Адского Крика поручил вам убить 15 фурболгов из племени Колючего Меха в деревне Колючего Меха.', 'Эти фурболги Колючего Меха мешают нашему продвижению! Деревня Колючего Меха, что лежит на западе, преграждает нам путь к заставе Расщепленного Древа. Это на дороге, что идет в обход деревни Астранаар. Если мы не будем ее контролировать, Альянс получит дополнительный путь для вторжения.$B$B$n, мы должны заткнуть эту дыру!$B$BИди в деревню Колючего Меха и перебей фурболгов. Выполнишь задачу – получишь награду, но важнее будет то, что ты выполнишь свой долг перед Ордой!', '', '', '', '', '', 'Возвращайтесь к Каранг Амаккару в Дозор Адского Крика, что в Ясеневом лесу.', 19865),
(218, 'ruRU', 'Лед и огонь', 'Убейте Грик''нира Холодного, 6 клинков племени Мерзлогривов, 3 новобранцев племени Мерзлогривов и своенравного элементаля огня.', 'Сорен правильно сделал, что послал тебя сюда. Эти сведения нам пригодятся.$B$BПравда, дело в том, что это сильно прибавляет нам работы. Тролли, хоть они сейчас и пребывают в полнейшем замешательстве, все равно жаждут выгнать дворфов из Холодной долины. И я уж точно не позволю какому-то огненному демону превратить нашу снежную долину в горное озеро.$B$BВожак троллей, его прислужники и огненная тварь должны быть в пещере к юго-востоку отсюда. Разберись с ними со всеми.', '', '', 'Грик''нир Холодный', '', '', 'Вернитесь к Грелину Белобороду в Дун Морог.', 19865),
(219, 'ruRU', 'Пропавший без вести', 'Проводите капрала Кишана до Красногорья.', 'Наконец-то, сторонники Альянса!$b$bПомогите... Пожалуйста...$b$bПоследнее, что я помню – как орки окружили наш отряд. Меня ударили по затылку, и в глазах потемнело. А теперь я пленник в этой пещере. Спасите меня, я тяжело ранен.$b$bМне понадобится помощь, чтобы добраться до города... Пожалуйста... Вы моя последняя надежда...', 'Проводите капрала Кишана до Красногорья.', 'Проводите капрала Кишана до Красногорья.', '', '', '', 'Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.', 19865),
(221, 'ruRU', 'Воргены в лесу', 'Убейте 12 вестников Тьмы из стаи Ночной Погибели.', 'Может, ты $gзаметил:заметила; крупных воргенов, бродящих по лесу в компании тенеткачей? Судя по всему, большую часть воргенских сил и составляют эти самые вестники Тьмы.$b$bСтранствуя по лесу, я узнал, что они захватили и Гниющий сад на юго-западе от города. Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться.$b$bБудь $gосторожен:осторожна;.', '', '', '', '', '', 'Вернитесь к Калору в Темнолесье, что в Сумеречном лесу.', 19865),
(223, 'ruRU', 'Воргены в лесу', 'Отнесите записку Калора Джонатану Карвину.', 'Вот, $n. Отнеси это письмо мастеру Карвину.$b$b*Он отдает вам поблекший пергамент.*$b$bЕсли к нам потянутся такие, как ты, в отряде будет больше людей, чем в Ночном Дозоре! Быть может, тогда мы завершим работу, которую сейчас делаем с большим трудом.', '', '', '', '', '', '', 19865),
(225, 'ruRU', 'Заброшенная могила', 'Поговорите с Широй Фон-Инди в Темнолесье.', 'Надпись на древнем могильном камне гласит:$B$BМОРГАН ЛАДИМОР$b$b*При внимательном рассмотрении вы замечаете, что могилу недавно раскапывали, и большая часть земли насыпана заново...*', '', '', '', '', '', '', 19865),
(227, 'ruRU', 'Морган Ладимор', 'Поговорите с командиром Алтеей Чернодрев в Темнолесье.', '*Он роется на полках и вытаскивает книгу в кожаном переплете.*$b$bЕсли хочешь узнать побольше, спроси Алтею, она занималась... проблемами... возникшими с ним в последнее время.', '', '', '', '', '', '', 19865),
(229, 'ruRU', 'Выжившая дочь', 'Поговорите с дозорным Сарой Ладимор в Темнолесье.', 'Надо было предупредить тебя раньше...$b$bКак бы тебе сказать...$b$bМорган думал, что у него погибла вся семья, но его дочь, Сара Ладимор, жива и служит в Ночном дозоре. Ее всегда беспокоили... обстоятельства... связанные с гибелью ее отца. Быть может, ты сообщишь ей о случившемся.', '', '', '', '', '', '', 19865),
(232, 'ruRU', 'Посылка для аптекаря Зинг', 'Отнесите заказ на товары Алессандро Луке в Подгород.', 'Королевскому фармацевтическому обществу нужна твоя помощь. Слушай внимательно, поскольку, если мой план удастся, мы оба окажемся в выгодном положении.$B$BСогласна, аптекарь Чанн... немного тронутый... но его исследования приносят свои плоды, если попадают в руки к умному человеку. К счастью, я как раз из таких. Отнеси этот заказ Алессандро Лусе, хозяину "Тысячи мелочей Синей Луны", он даст тебе набор для полевых испытаний. Принеси его мне, и я расскажу тебе подробнее о задании.', '', '', '', '', '', '', 19865),
(233, 'ruRU', 'Почта Холодной долины', 'Доставьте письма Талину Остроглазу в Холодную долину.', 'Не думаю, что ты горишь желанием мне помочь, $gпарень:красотка;, но у меня тут целая куча писем, а времени на доставку нет.$b$bЭто все для Талина Остроглаза. Его лагерь – у замерзшего озера, к западу отсюда.$b$bНу что, может, доставишь ему почту?', '', '', '', '', '', '', 19865),
(235, 'ruRU', 'Большая охота', 'Поговорите с Сенани Громосерд на Заставе Расщепленного Дерева в Ясеневом лесу.', 'Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!$b$bОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – Застава Расщепленного Дерева и Застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на Заставе Расщепленного Дерева, к северу от Степей. Она ждет желающих принять участие в большой охоте!', '', '', '', '', '', '', 19865),
(236, 'ruRU', 'Горючее для разрушителей', 'Осадный кузнец Крепкохват из Крепости Ледяных Оков попросил вас собрать 10 неугасимых угольков с тел воинов Орды в Огненной котловине.', '$n! Ты как раз вовремя. Хотя эта битва закончилась, мы должны подготовиться к новым сражениям. Отправляйся в Огненную котловину, который находится в на юго-востоке Озера Ледяных Оков, и принеси оттуда несколько неугасимых угольков.$B$BСмешав их с обычным углем, мы получим топливо для наших разрушителей и осадных машин.$B$BКстати, если по пути тебе встретятся солдаты Орды – не стесняйся, убей их и забери угольки. Нельзя допустить, чтобы в следующей битве преимущество оказалось на их стороне.', '', '', '', '', '', 'Вернитесь к осадному кузнецу Крепкохвату на Озеро Ледяных Оков.', 19865),
(238, 'ruRU', 'Посылка для аптекаря Зинг', 'Отнесите набор для проведения полевых испытаний аптекарю Зинг в Подгород.', 'Я подготовил набор, $n. Не сомневаюсь, аптекарю Зинг не терпится его получить. Отнеси посылку как можно скорее и сообщи ей, что я запишу стоимость набора на счет Общества. Кроме того, передай ей мой пламенный привет.$B$BНу же, не стой как истукан. Простым курьерам не ведом отдых, а?', '', '', '', '', '', '', 19865),
(239, 'ruRU', 'Гарнизон у Западного ручья просит помощи!', 'Отправляйтесь в Гарнизон у Западного ручья и поговорите с заместителем судьи Рейнером.', 'Гарнизон западной границы докладывает об усилении активности гноллов и грабителей. Они просят, чтобы мы прислали подкрепление из Штормграда... Но у нас не хватает людей!$B$BТвоя помощь не была бы лишней. Поговори с заместителем судьи Рейнером: он сейчас находится в Гарнизоне у Западного ручья. Рейнер скажет тебе, что делать.$B$BГарнизон расположен к западу отсюда: иди по дороге, а потом, когда перейдешь через речушку по мосту, сверни направо.', '', '', '', '', '', '', 19865),
(241, 'ruRU', '<TEST> ЭЙ МИСТЕР УИЛСОН!', 'Краткое описание', 'Описание', '', '', '', '', '', '', 19865),
(243, 'ruRU', 'Поход в пустыню', 'Поговорите с главным инженером Чепухастером из Прибамбасска насчет источника энергии для набора для полевых испытаний.', 'Ты отправишься в пустыню Танарис изучать состав тканей василисков, скорпидов и гиен. Добудь образцы тканей и проверь их при помощи этого набора; подозреваю, что не все окажутся удачными. Мне нужно по восемь образцов каждого вида.$B$BКроме того, у гоблинов Прибамбасска есть источники энергии, необходимые для работы измененного набора. Поговори с главным инженером Чепухастером и добудь у него источник энергии.$B$BБез образцов ткани можешь не возвращаться.', '', '', '', '', '', '', 19865),
(244, 'ruRU', 'Вторжение гноллов', 'Поговорите с заместителем судьи Фелдоном. Его можно найти у моста западнее Приозерья, что в Красногорье.', 'Привет тебе, |3-6($c). Мне приказано охранять этот участок дороги. Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов.$B$BВ Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону. Уверен, он заплатит тебе за принесенные вести.$B$BФелдон обычно обходит территорию к югу от моста по дороге в Приозерье.', '', '', '', '', '', '', 19865),
(245, 'ruRU', 'Восьминогая угроза', 'Убейте 15 карликовых ядовитых кругопрядов и доложите об этом дозорному Додсу, ожидающему вас в Сумеречном лесу.', 'Привет тебе, |3-6($c). Наверное, ты $Gвидел:видела; пауков на западной границе? Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья.$b$bМне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться. Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов.$b$bМой тебе совет: остерегайся их яда.', '', '', '', '', '', 'Вернитесь к дозорному Додсу в Сумеречный лес.', 19865),
(246, 'ruRU', 'Подсчет врагов', 'Убейте 10 полукровок из стаи Красногорья и 6 браконьеров из стаи Красногорья и сообщите об этом заместителю судьи Фелдону из Приозерья.', 'У нас нет лишних людей, но с гноллами, о которых ты говоришь, надо что-то делать.$B$BПоищи их в южной части Красногорья. Убей, кого сможешь, и сообщи мне об их общем числе и степени угрозы, которую они представляют для города. Гноллы стоят лагерем вдоль южной дороги.$B$BСделай это ради армии Штормграда, $n, и получишь награду.', '', '', '', '', '', 'Вернитесь к заместителю судьи Фелдону в Приозерье, что в Красногорье.', 19865),
(255, 'ruRU', '[DEPRECATED]Mercenaries', 'Келт Томасин из лагеря Мо''грош просит вас убить 4 огров из клана Мо''грош, 4 громил из клана Мо''грош и 4 головорезов из клана Мо''грош.', 'Пройдет два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да еще два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и Дамба – Дамба! – тоже в опасности.$b$bПохоже, у меня нет выбора. Придется искать наемников.$b$bКак насчет тебя? На первый взгляд ты подходишь, |3-6($c). На северо-восточном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?', '', '', '', '', '', '', 19865),
(259, 'ruRU', '<UNUSED>', 'Talk to Kelt Thomasin.', 'Hello there, $n. I''ve heard much about your exploits, and must say I''m honored to meet you. I don''t suppose you''ve heard the story of Ol'' Kelt? Ah, well, Ol'' Kelt--Kelt Thomasin, that is--was once considered one of the finest hunters in all the realm. There wasn''t much he hadn''t done, but then, one day, he became obsessed with an ancient story... a myth, really. Well, as the stories go, a huge threshadon lives in the waters of the lake. Hogwash, if you ask me. If you''re interested, you might talk to Kelt.', '', '', '', '', '', '', 19865),
(261, 'ruRU', 'Путями Алого ордена', 'Убейте 30 представителей нежити-опустошителей и вернитесь к брату Антону на Высоте Найджела.', 'Буду откровенен. Мы ведем войну с нечистью. Это зло, уничтожающее наш народ и оскверняющее нашу землю. Нежить нужно остановить, пока это возможно, иначе весь мир погрузится во мрак. Мы поклялись сражаться до последней капли крови, не щадя ни жизни, ни души.$B$BТы с нами? Тогда яви свое мужество и докажи свою доблесть: убей нежить-опустошителей, бродящих по Пустошам на юге, в Долине Костей.$B$BСделай это, и братство Алого ордена примет тебя.', '', '', '', '', '', 'Вернитесь к брату Антону на Высоту Найджела, что в Пустошах.', 19865),
(264, 'ruRU', 'Покуда смерть не разлучит нас', 'Положите подвеску Кларисы на могилу Юрива в Серебряном бору.', 'Гад такой! Бросил меня ради своего клятого похода! Понимаете ли, "Свет превыше всего, ибо он единственная наша защита от нежити!"$B$BА как же дети?! А я?! Много ночей я терпеливо ждала его... я всегда была второй после его чертового долга!$B$BИ посмотрите, $n, теперь на плоды борьбы за "справедливость"! Он мертв, а на меня обрушилось все то, чему он пытался помешать!$B$BВозьмите этот хлам и положите на его могилу в Гробнице. Мне не нужен больше этот мусор... и он сам тоже!', '', '', '', '', '', '', 19865),
(267, 'ruRU', 'Угроза со стороны троггов', 'Принесите 8 каменных зубов троггов капитану Ругельфассу к южной сторожевой башне.', '$C, не знаю, $gслышал:слышала; ли ты о новой угрозе, нависшей над землями дворфов. Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов. Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов.$b$bИ все же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан. Принеси в доказательство своих свершений 8 каменных зубов троггов.', '', '', '', '', '', '', 19865),
(270, 'ruRU', 'Обреченный флот', 'Отправляйтесь в Гавань Менетилов в Болотине и поговорите с дворфом по имени Глорин Стальной Лоб.', 'Много лет назад Третья флотилия Кул-Тираса затонула у берегов Болотины, огромной топи к северу от дворфийского королевства Стальгорн. Одно из судов было нагружено светосталью.$b$bЭтот металл представляет для нас большую ценность, поскольку изготовленное из него оружие и доспехи разят врагов силой святой истины. Если вы собираетесь противостоять Морбенту Скверну, вам именно такое оружие и понадобится.$b$bОтправляйтесь в Гавань Менетилов и переговорите с моим коллегой-дворфом по имени Глорин Стальной Лоб. Если утерянный груз еще можно найти – он сообразит, где нужно искать.', '', '', '', '', '', '', 19865),
(272, 'ruRU', 'Испытание Морского Льва', 'Найдите половинку подвески Ловкости водяного облика и половинку подвески Выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.$B$BСложите из половинок подвеску Морского Льва. Для этого вам надо находиться рядом со святилищем Ремула.$B$BОтнесите собранную подвеску Дендриту Блеску Звезд в деревню Ночная Гавань, что на Лунной поляне.', 'Вот твое второе испытание – тебе понадобятся две половинки подвески Морского Льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика.$B$BПоговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звезд.', '', '', '', '', '', 'Вернитесь к Дендриту Блеску Звезд в Ночную Гавань, что на Лунной поляне.', 19865),
(273, 'ruRU', 'Снабжение экспедиции', 'Поговорите с Хальдаром.', 'Еще не поздно, ты можешь поискать Хальдара. Вряд ли он ушел далеко; Миран и Сайан – крепкие ребята, но под грузом бочек ходят не слишком быстро.$b$bОни пошли к раскопу обычной дорогой – на юг от города, вдоль берега озера.$b$bНайти их будет несложно, если они еще не добрались до места назначения.', 'Найдите Хальдара, Мирана и Сайана.', 'Найдите Хальдара, Мирана и Сайана.', '', '', '', 'Поговорите с Хальдаром на озере Лок, что в Лок Модане.', 19865),
(279, 'ruRU', 'Угроза из глубин', 'Убейте 12 мурлоков из племени Синежабрых.$B$BПрикончите Жруна и принесите его голову Карлу Борану в Гавань Менетилов.', 'Мурлоки выходят из морских глубин и строят свои поселения на побережье. Они нападают на наших рыбаков и торговцев, и это уже переходит всякие границы. Их надо остановить.$B$BОдин из этих мурлоков, Жрун, придумал устраивать засады на наших купцов на дорогах. На мурлоков из племени Синежабрых нет никакой управы. Творят, что хотят, а потом прячутся в ближайших поселениях, и все – их уже не достать. Наши торговцы в опасности, и мы готовы хорошо заплатить тому, кто возьмется их защищать.$B$BЖрун промышляет в речном заливе к северу отсюда. Найди его и убей. А еще убей всех его родичей и принеси мне его голову.', '', '', '', '', '', 'Вернитесь к Карлу Борану в Гавань Менетилов, что в Болотине.', 19865),
(287, 'ruRU', 'Форт Мерзлогривов', 'Обследуйте форт Мерзлогривов и убейте 5 охотников за головами из племени Мерзлогривов по просьбе Сенира Белоборода из Караноса.', 'Я не успеваю с донесением, и твоя помощь, $n, мне бы пригодилась. Я сумел узнать, где засели тролли, но их там было столько, что я побоялся лезть туда.$b$bВот что мне нужно... Спустись в пещеру, порыскай там, прибей пару-другую троллей и возвращайся ко мне.$b$bОтправляйся из Караноса по северной дороге. Когда перейдешь через мост, следуй на запад по замерзшей реке, пока не доберешься до Заледеневшего озера. На западном берегу обнаружишь Поселок Пивоваров. Форт Мерзлогривов находится к юго-западу от него.', 'Полностью исследуйте форт Мерзлогривов.', 'Полностью исследуйте форт Мерзлогривов.', '', '', '', 'Вернитесь к Сениру Белобороду в Каранос.', 19865),
(288, 'ruRU', 'Третья флотилия', 'Купите первому помощнику Фитсиммонсу кружку медовухи.', 'Когда-то я был первым помощником на "Владычице", линейном корабле Третьей флотилии Кул-Тираса. Обреченной флотилии... Во время последнего плавания на нас напали красные драконы. А ими правили орки!$B$BУ нас не было ни единого шанса спастись от драконьего огня, и все корабли были сожжены и потоплены у побережья. Я один уцелел в этом кошмаре.$B$BОх, как же раскалывается голова! Погоди, сейчас я выпью чего-нибудь, немного приду в себя и продолжу.', '', '', '', '', '', 'Вернитесь к первому помощнику Фитсиммонсу в Гавань Менетилов, что в Болотине.', 19865),
(289, 'ruRU', 'Проклятая команда', 'Убейте 13 проклятых матросов, 5 проклятых стражей бухты и первого помощника Снеллига. Принесите табакерку Снеллига первому помощнику Фитсиммонсу в Гавань Менетилов.', '<Приободрившись, Фитсиммонс продолжает рассказывать...>$B$BЯ единственный уцелевший из всех матросов злополучной Третьей флотилии Кул-Тираса, погибшей у северного побережья. И хотя я последний из команды, чье сердце бьется и кто еще дышит, я не единственный, кто еще бродит по земле! На одном из наших кораблей хранилось великое, ужасное сокровище, и его потусторонняя зловещая сила держит души моих собратьев и не дает им покинуть гниющие остовы кораблей.$B$BЕсли ты сможешь их освободить, тогда, может быть, они избавятся от проклятия.', '', '', '', '', '', 'Вернитесь к первому помощнику Фитсиммонсу в Гавань Менетилов, что в Болотине.', 19865),
(290, 'ruRU', 'Очищение', 'Возьмите ключ от сейфа на "Отважном" у капитана Халиндора.$B$BОткройте сейф на "Отважном".', 'Чтобы избавиться от проклятия и освободить моих верных товарищей, нужно найти и очистить эту... проклятую штуковину... спрятанную на моем корабле! Не знаю, что это такое, знаю только, что эта штука хранится в корабельном сейфе, а ключ от сейфа – у капитана Халиндора.$B$BСтарина капитан снится мне до сих пор. Я знаю, он сейчас на "Отважном" – нашем несчастном корабле. Постарайся добыть ключ от сейфа, открой его и возьми эту вещь.$B$BПотом отнеси ее в город и отдай жрецу Глорину Стальному Лбу.', '', '', '', '', '', 'Отыщите запертый сейф на "Отважном", что в Болотине.', 19865),
(291, 'ruRU', 'Донесения', 'Отнесите донесение Сенира сенатору Бэрину Краснокамню в Стальгорн.', 'Замечательно! Отнеси мое донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием. Ты найдешь его в Стальгорне, в палате, где король Магни вершит суд.$B$bЧто? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы.$b$bКстати, будь $gдобр:добра;, не говори о том, как ты мне $gпомогал:помогала;. Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица.', '', '', '', '', '', '', 19865),
(297, 'ruRU', 'Сбор идолов', 'Принесите Магмару Рудоколу 8 резных каменных идолов c раскопок Сталекрута.', 'Незадолго до появления троггов на раскопках мы обнаружили множество странных резных идолов. Изучить их мы не успели, потому что вскоре после этого трогги вытеснили нас из развалин! А идолы оказывают на этих тварей странное воздействие – превращают их в берсерков!$B$BОтбей 8 идолов у троггов и принеси мне – я хочу их изучить. Идолов ты найдешь у троггов – а их в раскопе более чем достаточно.', '', '', '', '', '', '', 19865),
(298, 'ruRU', 'Отчет о ходе раскопок', 'Отнесите отчет о ходе работ Джерну Шлеморогу в Телcамар.', 'Мне нужно отправить в Телcамар отчет о ходе работ и запрос на получение нового груза пороха! Вот мой отчет. Отнеси его Джерну Шлеморогу, он наш представитель в Телcамаре.$b$bЗадание не сложное, но достаточно важное.', '', '', '', '', '', '', 19865),
(299, 'ruRU', 'Тайны прошлого', 'Обыщите раскопки и найдите четыре недостающих фрагмента скрижали: Адос, Модр, Голм и Неру. Принесите их геологу Вельгару.', 'Перед самым вторжением я обнаружил скрижаль с письменами, именуемую скрижалью Гоаз. Несколько кусков отломилось, и в четырех местах текст обрывается. Там говорится о некоем "замысле богов" и о "проклятом пророчестве".$b$bБоюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты $gмолод и полон:молода и полна; сил.$b$bОбыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру. Ищи среди древних артефактов или там, где почва разрыхлена. Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!', '', '', '', '', '', 'Вернитесь к геологу Вельгару на Раскопки Вельгара, что в Болотине.', 19865),
(301, 'ruRU', 'Отчет в Стальгорн', 'Отнесите отчет Сталекрута о ходе работ геологу Грозовой Вершине.', 'Мы не можем выдать Сталекруту новую партию взрывчатого порошка без одобрения Стальгорна. Тебе придется отнести его отчет в штаб-квартиру Лиги исследователей.$b$bВот он. Отдай его геологу Грозовой Вершине, да не забудь сразу отскочить в сторону. Грозовая Вершина – горячая голова. Его совсем не порадуют новости о медленном продвижении работ.$b$bГрозовую Вершину можно найти в Зале Исследователей.', '', '', '', '', '', '', 19865),
(302, 'ruRU', 'Порох для Сталекрута', 'Поговорите с Джерном Шлеморогом в Телcамаре.', 'Если Сталекруту нужен порох, то, именем короля Магни, он его получит! Я уже отправил вестника в Телcамар с соответствующим приказом Джерну Шлеморогу. Он подготовит груз пороха и прочих припасов для Сталекрута.$B$BИ еще одно: я хочу, чтобы ты лично $gпроследил:проследила; за доставкой груза. Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба.', '', '', '', '', '', '', 19865),
(303, 'ruRU', 'Война с Черным Железом', 'Убейте 10 дворфов Черного Железа, 5 проходчиков, 5 саботажников и 5 подрывников по просьбе Мотли Гармасона.', 'Война свирепствует повсюду: и в наших краях, и в чужих землях тоже. Пока наши могучие воины не щадят своих жизней, сражаясь во имя Альянса вдали от дома, на наших собственных землях бесчинствуют дворфы Черного Железа. Они разрушили один из мостов Тандола, потом пал и Дун Модр.$b$bТебе нужно собрать добровольцев и сдержать натиск врагов. Если сумеешь убить 10 дворфов Черного Железа, 5 проходчиков, 5 саботажников и 5 подрывников, тогда, может быть, мы и продержимся до подхода подкрепления.$b$bИ поторопись! У нас мало времени.', '', '', '', '', '', 'Вернитесь к Мотли Гармасону в Дун Модр, что в Болотине.', 19865),
(304, 'ruRU', 'Мрачное поручение', 'Убейте Балгараса Нечистого и принесите его ухо Гриму Длиннокосу в Дун Модр.', 'Сколько наших полегло в битве при Дун Модре! Мой родной брат погиб, когда обрушился западный мост Тандола. Да, дворфы Черного Железа – те еще бестии. Чертово племя, шайка головорезов. Рогго сумел разузнать, что их предводитель в Болотине – некий чернокнижник по имени Балгарас Нечистый. Трус и мерзавец, каких поискать. Посылает на битву своих солдат, а сам прячется у себя в лагере на Зловещем холме, к юго-востоку отсюда.$b$bРазыщи этого подлого слизняка, убей его, принеси мне его ухо, и получишь награду, |3-6($c).', '', '', '', '', '', 'Вернитесь к Длиннокосу Мрачному в Дун Модр, что в Болотине.', 19865),
(305, 'ruRU', 'Пропавшие ученые', 'Таррел Камнепряд просит отыскать Меррин Камнепряд на раскопках.', 'Ты, должно быть, $gтот самый разведчик:та самая разведчица;, $gкоторого:которую; обещал прислать Длиннокос? Знаешь... как-то мне неспокойно на сердце.$b$bМоя благоверная, Меррин, работает в изыскательской группе на раскопе Вельгара. Писала мне каждую неделю, весь прошлый месяц. А теперь вдруг пропала. Уже две недели ни слуху, ни духу. Наверняка что-то случилось!$b$bДлиннокос обещал, что, если я вскорости не получу никаких известий, он пришлет мне $gразведчика:разведчицу;, $gкоторый:которая; проверит, что стало с экспедицией. Как я понимаю, ты и есть $gэтот разведчик:эта разведчица;, $n. Разыщи Меррин на раскопе к востоку отсюда!', '', '', '', '', '', '', 19865),
(307, 'ruRU', 'Грязные лапы', 'Отправляйтесь к Серебряным копям и принесите 6 ящиков с инструментами шахтеров горному пехотинцу Грозовой Вершине.', 'Серебряные копи давно уже выработаны. Лига рудокопов превратила их в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на дворфийские инструменты!$B$BРано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в копи не спустились воины и не разнесли все к демонам. Задача твоя не из простых, помощники тебе не помешают.$B$BОборудование находится в ящиках лиги Рудокопов, разбросанных по копям.', '', '', '', '', '', '', 19865),
(309, 'ruRU', 'Охрана груза', 'Защитите Хальдара и караван Сталекрута, а затем поговорите с геологом Сталекрутом.', 'Надо доставить этот порох Сталекруту, но сейчас эта телега никуда не пойдет. Вес немалый, а здесь небезопасно – кто знает, что еще замышляют дворфы Черного Железа, особенно теперь, когда с ними Сайан.$b$bС тобой мне будет гораздо спокойнее. Пока мы с тобой будем охранять телегу, Миран сможет выгрузить бочонки с порохом в лагере.', 'Защитите караван Сталекрута', 'Защитите караван Сталекрута', '', '', '', 'Поговорите с геологом Сталекрутом на раскопках Сталекрута, что в Лок Модане.', 19865),
(310, 'ruRU', 'Злейшие соперники', 'Замените один бочонок эля Громоваров бочонком жгучего пива Ячменоваров в подвале "Громоварки" в Караносе.', 'Не могу не признать, эти Громовары варят славное пойло. Но они должны понять, что не только у них это хорошо получается! Может, ты поможешь преподать им урок...$B$BВот, возьми-ка этот бочонок жгучего пива Ячменоваров. Проберись в подвал "Громоварки" в Караносе и подмени один бочонок их громового эля. И посмотрим, не скажут ли их заказчики, что мое пиво лучше, чем Громоваров!$B$BЕсли бочонки охраняются, тебе придется отвлечь стражу...', '', '', '', '', '', '', 19865),
(311, 'ruRU', 'Возвращение к Марлетте', 'Принесите бочонок громового эля Марлетте Ячменовар в Поселок Пивоваров.', 'Подсунув бочонок жгучего пива Марлетты в подвал Громоварки в Караносе, вы хватаете бочонок эля Громопойлов в качестве доказательства...', '', '', '', '', '', '', 19865),
(313, 'ruRU', 'Вести наблюдение издалека', 'Сообщите о распоряжениях капитана Таррана горным пехотинцам Данстану, Льюину и Валгруму. Их можно найти в Серой берлоге.', 'Из-за катаклизма множество троггов выбрались на поверхность, в связи с чем тролли из племени Мерзлогривов были вынуждены спасаться бегством. К сожалению, они поселились совсем рядом с нами, и это создает для нас проблемы.$b$bЯ отдал распоряжение горному пехотинцу Данстану отправиться вместе со своим отрядом в Серую берлогу, что к юго-западу отсюда, приглядывать за живущими там вендиго, но сейчас мне нужно, чтобы они вернулись в Каранос. Найди их и скажи, чтобы они установили в Серой берлоге роботов удаленного наблюдения, полученных от гномов, а сами отправлялись в Каранос.', '', '', '', '', '', 'Вернитесь к капитану Таррану в Каранос, что в Дун Мороге.', 19865),
(314, 'ruRU', 'Защита стада', 'Добудьте клык Вагаша.', 'Мы услышали шум среди ночи. Поутру не досчитались двух баранов в отаре. Эта подлая тварь Вагаш покушается на наш скот. И поскольку армия Стальгорна уже невелика, приструнить этого Вагаша некому.$b$bМожет, тебе хватит отваги для того, чтобы найти и прикончить эту тварь? Принеси мне его клык, и я тебя награжу. Вагаш рыщет как раз вон над тем выгоном, но будь $gосторожен:осторожна;, он смертельно опасен.', '', '', '', '', '', 'Вернитесь к Рудре Янтарлен на ферму Янтарленов.', 19865),
(315, 'ruRU', 'Всем портерам портер', 'Принесите 7 порций звездолиста Регольду Ячменовару в Каранос.', 'Я тут по делу, а дело мое – создать самый лучший портер! Я знаю, что у меня получится, пивоварение – это мое призвание. Надо только найти правильный рецепт...$B$BНа Мерцающем хребте, что к северо-западу отсюда, тролли из племени Мерзлогривов выращивают одну травку, называется звездолист. Они используют ее в странных ритуалах своего племени. Нам она не особенно полезна, но у нее необычный вкус... И я хочу поэкспериментировать с ней при изготовлении пива!$B$BСбор звездолиста может быть опасен, но я хорошо заплачу тебе за все, что ты сможешь "позаимствовать" из корзинок с травами в поселении троллей.', '', '', '', '', '', 'Вернитесь к Регольду Ячменовару в Каранос, что в Дун Мороге.', 19865),
(316, 'ruRU', '<UNUSED 1>', '', '', '', '', '', '', '', 'Вернитесь к тестовой белке.', 19865),
(317, 'ruRU', 'Заготовка продовольствия', 'Принесите 4 куска кабанины и 2 толстых медвежьих шкуры пилоту Толстопузу в Поселок Сталежара.', 'Я веду подготовку к выполнению боевого задания Осадной бригады. Дело будет долгим, и мне нужно укомплектовать мой паровик провизией на месяц. Так что пока Сталежар работает с моим танком, не отправишься ли ты на охоту?$B$BМне нужен мех, чтобы сделать кровать, и кабанина для еды. Кабаны – на мясо, медведи – на мех... Этих животных можно найти в снежных полях к югу от Серого логова.', '', '', '', '', '', 'Вернитесь к пилоту Толстопузу в поселок Сталежара.', 19865),
(318, 'ruRU', '"Вечное сияние"', 'Возьмите бочонок "Вечного сияния" у Регольда Ячменовара в Поселке Пивоваров.', 'Регольд Ячменовар не боится экспериментировать со своим варевом. Продукт эксперимента порой хорош на вкус, а порой нет, а иногда... самого крепкого дворфа уложит в стельку.$B$BРедгольд живет в Поселке Пивоваров, к западу от Караноса, и один из его напитков, "Вечное сияние", – как раз то, что мне надо. Он согреет меня в пути.$B$BИ... этот благословенный напиток горит так, что я могу залить его в топку паровика – и будет такой силовой импульс! Эта тактическая уловка помогала мне выбираться из многих переделок.', '', '', '', '', '', '', 19865),
(319, 'ruRU', 'Услуга за "Вечное сияние"', 'Убейте 6 медведей-ледолапов, 8 старых скальных вепрей и 8 снежных леопардов. Вернитесь к Регольду Ячменовару в Поселок Пивоваров.', 'У меня есть бочонок "Вечного сияния", но... не $gмог:могла; бы ты оказать мне услугу? Поселку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко...$B$BМы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты $Gвзял:взяла; это зверье на себя, у нас было бы больше времени на ремесло и пивоварение.', '', '', '', '', '', 'Вернитесь к Регольду Ячменовару в Долину Промозглого Ветра, что в Дун Мороге.', 19865),
(321, 'ruRU', 'Светосталь', 'Найдите груз с затонувшего корабля "Орлик" в Болотине.', 'Эти обломки погибших кораблей – останки Кул-Тирасской Третьей флотилии, сожженной и потопленной красными драконами во время последней Великой войны.$B$BФлотилия вышла из Лордерона, и с ней шел эльфийский боевой корабль – "Орлик". Он вез груз светостали и присоединился к Третьей флотилии, ища покровительства и защиты. По иронии судьбы, он был потоплен теми же драконами, от которых пытался спастись...$B$BЛадно, краткий исторический экскурс будем считать законченным. "Орлик" затонул к югу от Гавани Менетилов. Если найдешь светлосталь, принеси ее мне.', '', '', '', '', '', '', 19865),
(323, 'ruRU', 'Доказательство силы', 'Убейте 15 скелетов-налетчиков, 3 скелетов-лекарей и 3 скелетов-хранителей и вернитесь к Свену.', 'Морбент Скверн – могущественный некромант и союзник темных всадников. Я не могу послать тебя на битву с ним, не испытав прежде твою силу.$B$BХрабрость твою я не подвергаю сомнению, но если ты в самом деле хочешь выступить против некроманта, сразись сначала с его приспешниками.', '', '', '', '', '', 'Вернитесь к Свену Йоргену на Затихший берег, что в Сумеречном лесу.', 19865),
(325, 'ruRU', 'Вооружен и особо опасен', 'Принесите Погибель Морбента Свену в Сумеречный лес.', 'Вот оружие против твоего врага. $n, иди и сражайся. Удачи тебе, возвращайся со славой!', '', '', '', '', '', '', 19865),
(332, 'ruRU', 'Реклама винного магазина', 'Отправляйтесь на винокурню Галлины и принесите Сюзетте Галлине талон на вино, чтобы получить бутылку вина бесплатно.', 'Если тебя интересует вино, так лучшее вино в Штормграде продает семейство Галлина! Это недалеко – в Торговом квартале, неподалеку от городских каналов.$B$BВозьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого "Даларан нуар". Не пожалеешь!', '', '', '', '', '', '', 19865),
(333, 'ruRU', 'Харлан нуждается в помощи', 'Отправляйтесь в магазин одежды в районе каналов и принесите Реме Шнайдер заказ на ткани от Харлана Багли.', 'Кажется, мы уже встречались. Наверное, насчет покупки брони и походной одежды. Кстати, ожидается суровая зима...$B$BА сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду. Мне нужна еще одна партия от нашего поставщика.$B$BЕсли ты отнесешь это послание Реме Шнайдер в ателье "Канал", моя признательность будет весьма велика.', '', '', '', '', '', '', 19865),
(334, 'ruRU', 'Посылка для Турмана', 'Отправляйтесь в суконную лавку Ларсона в Квартал Магов Штормграда, и передайте Турману Шнайдеру его набор для шитья.', 'Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, |3-6($c) вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать...$B$BПрошу вас, $n! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов.', '', '', '', '', '', '', 19865),
(335, 'ruRU', 'Благородный напиток', 'Принесите Зардету Черному Когтю слезу Тиллоа из Темнолесья и мускусный корень из Болотины.', 'Лорд Вишлок наделал немалого переполоху среди Благородных домов. Он прознал о наших делах и теперь собирается добиться полного расследования. У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь.$b$bЕсть один цветочек под названием "слеза Тиллоа", он растет в садах Сталвана поблизости от Темнолесья. Еще мне понадобится мускусный корень, который можно найти только у подножия Каменной плотины в Болотине.', '', '', '', '', '', 'Вернитесь к Зардету Черному Когтю в Штормград.', 19865),
(337, 'ruRU', 'Старинная историческая книга', 'Вернуть книгу "История Штормграда" в библиотеку Штормграда.', 'Хотя обложка книги исцарапана и заляпана грязью, на корешке все еще можно прочитать заглавие – "История Штормграда". Открыв ее, вы видите на первой странице печать библиотеки Штормграда.$B$BПохоже, кто-то взял почитать эту книгу, да так и не вернул...', '', '', '', '', '', '', 19865),
(338, 'ruRU', 'Зеленые холмы Тернистой долины', 'Соберите все недостающие страницы романа "Зеленые холмы Тернистой долины". Когда у вас на руках окажутся все четыре главы, верните их Барнилу.', 'Господин Эрнестуэй так расстроится, когда узнает об этом!$B$BОн доверил мне рукопись романа "Зеленые холмы Тернистой долины". Все шло хорошо, но по лагерю пронесся сильный порыв ветра и разметал страницы!$B$BБольшую часть мне удалось собрать, но многие страницы унесло в джунгли. Найди все страницы, и мы снова соберем четыре главы.$B$BЯ сам все разложу! Когда соберешь все четыре главы, возвращайся.', '', '', '', '', '', 'Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.', 19865),
(339, 'ruRU', 'Глава I', 'Принесите 1, 4, 6 и 8 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю первую главу.', 'Первая глава была необычайно интересной. Мастер Эрнестуэй предваряет рассказ знакомством со своими товарищами по охоте, в том числе и со мной! $b$bНо речь не об этом. Посмотрим, каких страниц не хватает. Кажется, страницы 1, 4, 6 и 8 все еще в джунглях!', '', '', '', '', '', 'Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.', 19865),
(341, 'ruRU', 'Глава III', 'Принесите 18, 20, 21 и 24 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю третью главу.', 'Глава III была моей любимой. В ней рассказывается о том, как сэр Эрлджедин и леди Руак впервые подстрелили зверя из дворфийского ружья. А какое захватывающее у нее окончание! $B$BПохоже, нам недостает страниц 18, 20, 21 и 24. Они должны быть где-то неподалеку...', '', '', '', '', '', 'Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.', 19865),
(343, 'ruRU', 'Кстати, о стойкости духа', 'Отправляйтесь в Королевскую библиотеку крепости Штормграда и поговорите с Милтоном Снопом. Он даст вам книгу по металлургии, которая интересует брата Кристофа.', 'Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, "Как закалялось железо". Копия этой книги должна быть в Королевской библиотеке крепости Штормграда. Не могли бы вы заказать ее для меня? Да осенит вас благодать Света!$B$BКоролевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесет для вас книгу.', '', '', '', '', '', '', 19865),
(344, 'ruRU', 'Брат Пакстон', 'Поговорите с братом Пакстоном из Аббатства Североземья.', '"Как закалялось железо"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провел в горах Каз Модана, добывая руду. Отличный парень!$B$BНо о чем это я? Ах, да... "Как закалялось железо"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с нее копию для своей коллекции.$B$BУж сколько тому месяцев минуло... Интересно, почему он ее задерживает.', '', '', '', '', '', '', 19865),
(345, 'ruRU', 'Запас чернил', 'Поговорите со старшиной Ослоу из Приозерья и расспросите его о ретбанской руде.', 'Я как раз собирался закончить свою работу над копией "Как закалялось железо", но...$B$BЯ пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут. Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я еще не успел закончить работу... и сделать еще чернил я не могу!$B$BДля изготовления чернил мне нужна ретбанская руда из Красногорья. Старшина Ослоу из Приозерья – мой верный поставщик...', '', '', '', '', '', '', 19865),
(347, 'ruRU', 'Ретбанская руда', 'Добудьте 5 кусков ретбанской руды и принесите их брату Пакстону в библиотеку Североземского аббатства.', 'Ретбанская руда получила свое название по имени первооткрывателя, Барта Ретбана. Выплавленный металл мягче железа, но руда имеет приятный темный цвет, и многие переписчики используют ее для изготовления чернил. Добыть руду можно в пещерах Ретбана к северу отсюда.$B$BК сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе еще вот что... Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду.$B$BТак что если тебе нужна руда... ты знаешь, как добыть ее.', '', '', '', '', '', 'Вернитесь к брату Пакстону в Долину Североземья, что в Элвиннском лесу.', 19865),
(348, 'ruRU', 'Лихорадка Тернистой долины', 'Найдите знахаря Унбагва и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.', 'Плохо... Мне... т-т-ак п-п-лохо.$B$BЯ п-подцепил... лихорадку Тернистой д-долины... Это смертельный вирус...$B$BЕдинственное лекарство... съесть сердце М-м-м-мок-ка Д-дикаря... неуловимой... белой гориллы...$B$BИщи знахаря Унбагва в с-с-скрытой пещере на южном мысу...$B$BПоспеши... я... умираю...', '', '', '', '', '', 'Вернитесь к Фину Горемыку в Пиратскую Бухту, что в Тернистой долине.', 19865),
(350, 'ruRU', 'Помощь старого друга', 'Поговорите с Иллингом Триасом в Штормграде.', 'Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара...$B$BТеперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твое свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара. Ему, в сущности, наплевать на закон.$B$BТебе понадобится помощь. Я, увы, оказать ее не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале.', '', '', '', '', '', '', 19865),
(351, 'ruRU', 'Найди КПХ-17/TN!', 'Отнесите аварийный маяк к автономному роботу Карлса.', 'Вы находите какой-то странный яйцевидный металлический предмет. Повозившись с кнопками, вы пробуждаете яйцо, и оно превращается в гномский робот! Изнутри доносится голос.$b$b"Меня зовут Карлс, и мой автономный робот потерялся! За его находку полагается награда! Прошу, отнесите этот маяк к роботу. Я уже вычислил координаты. Он сломался возле Зияющей бездны в Танарисе".', '', '', '', '', '', '', 19865),
(352, 'ruRU', '<UNUSED>', '', 'Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don''t think being ready would have helped my cause much. One swipe and poof! Darkness. They say I''m lucky to walk now...$b$bWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $n, if you''d like to try yourself against her, the Lady of the Loch,', '', '', '', '', '', '', 19865),
(353, 'ruRU', 'Посылка для Грозовой Вершины', 'Доставьте посылку горному пехотинцу Грозовой Вершине в Лок Модан.', 'Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утонченными вкусами. Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие.$B$BЗаказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если вы собираетесь на север, не возьметесь ли доставить груз?$b$BПо моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане.', '', '', '', '', '', '', 19865),
(354, 'ruRU', 'Смерти в семье', 'Принесите останки Грегора, останки Ниссы и останки Тармена Колману Фартингу в Брилл.', 'Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... еще до чумы.$B$BКогда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными...$B$BИз-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!$B$BСослужи Отрекшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки.', '', '', '', '', '', 'Вернитесь к Колману Фартингу в Брилл, что в Тирисфальских лесах.', 19865),
(355, 'ruRU', 'Разговор с Севреном', 'Поговорите с мировым судьей Севреном в Брилле.', 'Ты $gпринес:принесла; мне останки Агамондов и $gутолил:утолила; мою жажду мести. Но мельницы этой проклятой семейки все еще представляют собой угрозу не только для меня, но и для всех Отрекшихся.$B$BЯ рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично.', '', '', '', '', '', '', 19865),
(357, 'ruRU', 'Личность лича', 'Принесите книгу лича Бетору Ледострелу в Подгород.', 'На острове посреди озера Ясноводного, что к северу отсюда, обитает лич. Сам он – свободный Отрекшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится.$B$BНо раз он Отрекшийся, он понадобится Королеве. А если он еще и специалист в некромантии, то его умения нам... весьма пригодятся.$B$BЧтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний. Прокрадись в его лагерь, достань ее, и принеси мне.', '', '', '', '', '', 'Вернитесь к Бетору Ледострелу в Тирисфальские леса.', 19865),
(358, 'ruRU', 'Грабители могил', 'Убивайте грабителей могил и полукровок из стаи Гнилошкуров.$B$BПринесите мировому судье Севрену 8 образцов бальзамирующей лимфы.', 'Братские могилы к юго-западу от Фермы Гаррена были вырыты, чтобы справиться с... внушительным количеством смертей в Тирисфале после прихода Чумы.$B$BТела в этих могилах еще не превратились в нежить, но теперь Плеть подослала гноллов-гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Это недопустимо!$B$BУ тебя будет два задания: убить гноллов-гнилошкуров возле братских могил и Фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь.', '', '', '', '', '', 'Вернитесь к мировому судье Севрену в Брилл, что в Тирисфальских лесах.', 19865),
(359, 'ruRU', 'Обязанности Отрекшихся', 'Поговорите со стражем смерти Линнеей.', 'Мне нужен свежий отчет с восточной базы наших стражей смерти.$B$BЯ хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь еще одну крепость.$B$BИди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у нее есть вся нужная мне информация.', '', '', '', '', '', '', 19865),
(361, 'ruRU', 'Недоставленное письмо', 'Найдите Иветту Фартинг и вручите ей письмо от Тармена Агамонда.', 'Это письмо, написанное Тарменом, старшим сыном Грегора Агамонда. Оно адресовано Иветте Фартинг, но, похоже, так до нее и не добралось...', '', '', '', '', '', '', 19865),
(362, 'ruRU', 'Мельницы с привидениями', 'Убейте Девлина Агамонда и принесите его останки Колману Фартингу в Брилл.', 'Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно. Тармен был высоким и учтивым, а его младший брат – слабым и острым на язык.$B$BКогда Мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых. На дороге, ведущей к Мельницам Агамондов, до сих пор можно услышать его безумное бормотание.$B$BЯ собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина. Найди его, уничтожь и принеси мне его кости.', '', '', '', '', '', 'Вернитесь к Колману Фартингу в Брилл, что в Тирисфальских лесах.', 19865),
(363, 'ruRU', 'Резкое пробуждение', 'Поговорите с жрецом Тени Сарвисом.', 'Ты вовремя $gпришел:пришла; в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. $b$bМеня зовут Мордо, я смотритель склепа Похоронного Звона. А ты больше не $gраб:рабыня; Короля-лича. $b$bПоговори с жрецом Тени Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать.$B$BЧтобы выбраться из склепа, поднимайся наверх по ступенькам. Затем следуй вниз по дороге, пока не найдешь часовню.', '', '', '', '', '', '', 19865),
(364, 'ruRU', 'Безмозглые твари', 'Убейте 5 безмозглых зомби и 5 презренных вурдалаков.', 'C тех пор, как первый Отрекшийся выполз из своей могилы, мы безостановочно ведем войну с армией Короля-лича. Проклятые мертвецы, мерзкие твари с севера, извращенные создания!$b$bХотя Король-лич больше не восседает на Ледяном троне, северная часть деревни все еще находится под осадой его рабов. Уничтожь их, не щади никого, кем бы они тебе не казались. Это больше не твои павшие братья и сестры.', '', '', '', '', '', 'Вернитесь к жрецу Тени Сарвису в Похоронный Звон, что в Тирисфальских лесах.', 19865),
(365, 'ruRU', 'Поля Горя', 'Украдите 10 тыкв с западной фермы, к северу от Похоронного Звона. Потом отнесите эти тыквы аптекарю Юхану в Брилл.', 'Кто это тут? $gНовенький:Новенькая:c; |3-6($c)? Если хочешь проявить себя перед Темной Госпожой, придется следовать обычаям Отрекшихся.$B$BК западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв.$B$BКак наберешь десяток, отнеси их аптекарю Юхану в Брилл.', '', '', '', '', '', 'Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.', 19865),
(367, 'ruRU', 'Новая чума', 'Принесите аптекарю Юхану 5 склянок крови псов Тьмы.', 'Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Темная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса.$B$BВ своих изысканиях я обнаружил, что для этого потребуется кровь животных. Принесите мне 5 склянок крови пса Тьмы, чтобы я мог провести эксперимент.', '', '', '', '', '', 'Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.', 19865),
(368, 'ruRU', 'Новая чума', 'Принесите аптекарю Юхану из города Брилл 5 чешуек мурлоков из племени Злобного Плавника из Тирисфальских лесов.', 'Пока ты $gсобирал:собирала; для меня образцы, я провел исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее.$B$BМне потребуется 5 чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу.', '', '', '', '', '', 'Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.', 19865),
(369, 'ruRU', 'Новая чума', 'Принесите Аптекарю Юхану из города Брилл 4 образца яда злобного ночного кругопряда.', 'Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней. Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов.$B$BПринесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент. Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах.', '', '', '', '', '', 'Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.', 19865),
(370, 'ruRU', 'Война с Алым орденом', 'Убейте капитана Перрина, 3 ревнителей и миссионеров Алого ордена по просьбе исполнителя Зуганда.', 'В документах палача Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми.$B$BУбейте Перрина, трех фанатиков и трех миссионеров, а потом доложите мне.', '', '', '', '', '', 'Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.', 19865),
(371, 'ruRU', 'Война с Алым орденом', 'Убейте капитана Вакона и пятерых келейников из Алого ордена по заданию палача Зуганда.', 'У нас до сих пор война, а Алый орден набирает силу. В отчете палача Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ усадьбы Балнира.$B$BУбейте Вакона и пятерых келейников из Алого ордена – это должно нанести ордену сокрушающий удар!', '', '', '', '', '', 'Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.', 19865),
(373, 'ruRU', 'Неотправленное письмо', 'Доставьте письмо городскому архитектору Баросу Алекстону в Штормград.', 'Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо. Адрес таков: "Баросу Алекстону, главному архитектору Штормграда, в ратушу на Соборной площади".$B$BКажется, оно написано совсем недавно, и печать еще свежая...', '', '', '', '', '', '', 19865),
(374, 'ruRU', 'Доказательство верности', 'Принесите 10 перстней Алого ордена стражу смерти Буржесу в Брилл.', 'Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими.$B$BВариматас, лейтенант Темной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стерто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден.$B$BПомоги нам истребить их, |3-6($c). Принеси мне десять перстней членов ордена в доказательство верности Вариматасу и Темной Госпоже.', '', '', '', '', '', 'Вернитесь к стражу смерти Буржесу в Брилл, что в Тирисфальских лесах.', 19865),
(375, 'ruRU', 'Смертельный холод', 'Принесите 5 шкурок сумеречницы и грубую нить Гретхен Дедмар в Брилл.', 'Так холодно... Чума нежити расползается по моим венам, как клубок ледяных змеев, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.$B$BТеперь мои руки дрожат от холода. Если ты принесешь мне 5 шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, $n, чтобы я могла и дальше служить нашему делу.', '', '', '', '', '', 'Вернитесь к Гретхен Дедмар в Брилл, что в Тирисфальских лесах.', 19865),
(376, 'ruRU', 'Проклятые', 'Obtain 4 Scavenger Paws and 4 Duskbat Wings.', 'В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тени Сарвису, какая может потребоваться. $b$bПохоже, и ты будешь $gзаписан:записана; к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесешь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно.', '', '', '', '', '', 'Вернитесь к новобранцу Элрет в Похоронный Звон, что в Тирисфальских лесах.', 19865),
(377, 'ruRU', 'Преступление и наказание', 'Принесите советнику Миллстайпу руку Декстрена Варда.', 'Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева.$b$bВард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью. И все же Штормград объявил Варда своим пленником.$b$bУбей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу.', '', '', '', '', '', 'Вернитесь к Члену совета Миллстайпу в Темнолесье, что в Сумеречном лесу.', 19865),
(380, 'ruRU', 'Паучья низина', 'Палач Аррен хочет, чтобы вы убили 8 молодых ночных кругопрядов и 5 ночных кругопрядов.', 'Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета власти Альянса. $b$bК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. $b$bОтправляйся туда – может быть, ты сможешь чем-то помочь нам, $n.', '', '', '', '', '', 'Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.', 19865),
(381, 'ruRU', 'Алый орден', 'Принесите палачу Аррену 12 алых поручей, сняв их с новообращенных и посвященных из Алого ордена.', 'Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. $b$bМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! $b$bБудь осторожен, нечестивое рвение делает их опасными противниками.', '', '', '', '', '', 'Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.', 19865),
(382, 'ruRU', 'Красный гонец', 'Убейте гонца Мевена Коргала в лагере Алого ордена, а потом сообщите перехваченные известия палачу Аррену.', 'В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из Монастыря к Похоронному Звону. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! $b$bА ты, $n, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.', '', '', '', '', '', 'Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.', 19865),
(383, 'ruRU', 'Важные разведданные', 'Отнесите бумаги Алого ордена палачу Зуганду в Брилл.', 'Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно $gпомог:помогла; нам здесь, в Похоронном Звоне, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдется более серьезная работа. $b$bИди по дороге из Похоронного Звона на север. Вскоре после того, как дойдешь до Тирисфаля, наткнешься на перекресток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье "Остывший очаг".', '', '', '', '', '', '', 19865),
(384, 'ruRU', 'Кабаньи ребрышки в пиве', 'Принесите 4 нежных свиных ребрышка и кружку "Болтливого пива" Рагнару Громовару в Каранос.', 'Завсегдатаи моей таверны больше всего любят кабаньи ребрышки в пиве! Беда в том, что местный охотник, который снабжал меня кабаниной, теперь завербован в королевскую армию, чтобы помочь Альянсу.$B$bМожет, ты мне поможешь? Если принесешь мне немного ребер скального вепря и "Болтливое пиво" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых ребрышек в пиве, не говоря уж о дармовой порции! Вся соль – в пиве!', '', '', '', '', '', 'Вернитесь к Рагнару Громовару на Мерцающий хребет, что в Дун Мороге.', 19865),
(385, 'ruRU', 'Охота на кроколисков', 'Принесите Мареку Железносерду в Приют Странников 5 кусков мяса кроколиска и 6 шкур кроколиска.', 'Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков. Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса.$b$bМы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок. Но если хочешь отправиться на охоту, я не стану тебя отговаривать. Это действительно незабываемо.$b$bЯ и сам в свое время...', '', '', '', '', '', '', 19865),
(387, 'ruRU', 'Подавление бунта', '[Deprecated] Warden Thelwater of Stormwind wants you to kill 10 Prisoners, 8 Convicts, and 8 Insurgents in The Stockade.', 'Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда.$b$bНаказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдет в норму.', '', '', '', '', '', 'Вернитесь к тюремщику Телвотеру в Штормград.', 19865),
(389, 'ruRU', 'Базиль Тредд', 'Поговорите с надзирателем Телвотером в тюрьме.', 'ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны.$B$BКогда мы закончили работу, вельможи отказались платить нам за нее. Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии. Он поднял мятеж и покинул город, поклявшись отомстить.$b$bЕго лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме.', '', '', '', '', '', '', 19865),
(390, 'ruRU', '<UNUSED>', '', '', '', '', '', '', '', '', 19865),
(391, 'ruRU', 'Бунтовщики в тюрьме', 'Убейте Базиля Тредда и принесите его голову Телвотеру в тюрьму Штормграда.', 'Скажу тебе сразу, $n: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно.$B$BЧто от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову. А если ты на их стороне и не вернешься вовремя, то будешь долго, долго гнить заживо...', '', '', '', '', '', 'Вернитесь к тюремщику Телвотеру в Штормград.', 19865),
(392, 'ruRU', 'Таинственный посетитель', 'Отнесите запечатанное описание посетителя Тредда Баросу Алекстону в Штормград.', 'Во время первого года заключения Тредда никто его не навещал. Мне казалось, что братство отказалось от него, поскольку он стал бесполезен.$B$BНо пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип. У меня возникли подозрения, но все его документы были в полном порядке.$B$BСогласно документам, звали его Мелик; вот его описание. Не думаю, что он еще когда-нибудь придет к Тредду.', '', '', '', '', '', '', 19865),
(393, 'ruRU', 'Тень прошлого', 'Отнесите запечатанное описание посетителя Тредда Матиасу Шоу в Штормград.', 'Знаете ли, $n, мне так ничего и не пришло в голову. Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться. Матиас Шоу из ШРУ – его можно найти в казармах Старого города. Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки.$B$BЕсли кто-то и знает, о ком речь, то только он.', '', '', '', '', '', '', 19865),
(394, 'ruRU', 'Голова чудовища', 'Поговорите с Матиасом Шоу в Штормграде.', 'Найди Шоу в Старом городе. Дай ему знать, что с Лесковаром покончено, а тебе все известно о заговоре лордов против города. Я думаю, он будет рад, что среди горожан Штормграда есть еще герои.$B$BДумаю, он отправит тебя на встречу с принцем или другим лордом. Не позволяй им запудрить себе мозги, $n. Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны.', '', '', '', '', '', '', 19865),
(395, 'ruRU', 'Гибель братства', 'Поговорите с Баросом Алекстоном в Штормграде.', 'Ах, да... Пока тебя не было, приходил Алекстон, хотел с тобой поговорить. Должно быть, это касалось Братства Справедливости.$b$B$n, позволь дать тебе совет: на твоем месте я бы по первой просьбе рассказал обо всем произошедшем в подробностях. Но при этом упомяни, что Лесковара сразила именно твоя рука. Можешь мне верить – я на таких вещах собаку съел.$B$BА что касается Триаса... ну, не говори о нем. Никогда. Если сможешь.', '', '', '', '', '', '', 19865),
(398, 'ruRU', 'Разыскивается: Червеглаз', 'Убейте Червеглаза и отнесите палачу Зуганду в Брилл его лапу.', 'Разыскивается: Червеглаз!$B$BУжасное даже по меркам гноллов чудовище – Червеглаз – приговорен к смерти за его преступления против Отрекшихся. Этот гнусный злодей воровал трупы для армии Короля-лича. Червеглаза видели близ Фермы Гаррена, к северу от Брилла.$B$BГород Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить палачу Зуганду его лапу.$B$BМилосердие – удел слабых.', '', '', '', '', '', 'Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.', 19865),
(399, 'ruRU', 'Скромные дары прошлого', 'Обыщите дом Бароса Алекстона в Западном Крае, найдите компас и вернитесь на Соборную площадь Штормграда.', 'It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it''s true. Doubly true in my case, my family''s home has been burned down and taken over by transients.$b$bI have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.$b$bYou''ll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?', '', '', '', '', '', 'Вернитесь к Баросу Алекстону в Штормград.', 19865),
(400, 'ruRU', 'Инструменты для Сталежара', 'Доставьте инструменты Белдину Сталежару.', 'Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам! Но своего инструмента он не жалеет. Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые!$B$BМы только что выполнили его очередной заказ. Если ты его доставишь, я уверен, мастер заплатит тебе за труды.$B$BТы сможешь найти Сталежара к северо-востоку от Караноса. Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работенка подвернется.', '', '', '', '', '', '', 19865),
(401, 'ruRU', 'Ожидание перевода', 'Подождите немного и снова поговорите с Широй Фон-Инди.', 'Я почти закончил работу над переводом записки. Она будет готова через несколько минут.', '', '', '', '', '', '', 19865),
(404, 'ruRU', 'Грязная работа', 'Принесите 7 гнилых когтей стражу смерти Диллинжеру в Брилл.', 'Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста.$B$BОтправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти.', '', '', '', '', '', 'Вернитесь к стражу смерти Диллинжеру в Брилл, что в Тирисфальских лесах.', 19865),
(405, 'ruRU', 'Блудный лич', 'Отнесите приказы Севрена Бетору Ледострелу в Подгород.', 'Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, $n, как раз подходишь для этого.$B$BОтнеси эти приказы Бетору, а он расскажет, в чем состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдет о найме заблудшего лича. Это очень опасное дело.$B$BПриготовься как следует, |3-6($c). Не подведи нас.$B$BБетора можно найти в Квартале Магов Подгорода.', '', '', '', '', '', '', 19865),
(406, 'ruRU', '<UNUSED>', '', '', '', '', '', '', '', '', 19865),
(407, 'ruRU', 'Поля Горя', 'Отнесите отравленную тыкву пленному ревнителю Алого ордена, которого держат в погребе таверны "Петля Висельника".', 'Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития.$B$BЧуть-чуть смекалки, и простая тыква превратится в шпиона Темной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом.$B$BВот недавно мы поймали еще одного ревнителя Алого ордена, сейчас он сидит в погребе таверны "Петля Висельника". Иди, отнеси ему эту тыкву.', '', '', '', '', '', '', 19865),
(408, 'ruRU', 'Семейный склеп', 'Убейте 8 стенающих прародительниц и 8 гниющих предков.$B$BУбейте капитана Даргола и принесите его череп мировому судье Севрену в Брилл.', 'Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это Семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас.$B$BТы не $gдолжен:должна; допустить этого. Отправляйся в Семейную усыпальницу Агамондов и убей их неупокоенных предков.$B$BА заодно принеси мне череп капитана Даргола.', '', '', '', '', '', 'Вернитесь к мировому судье Севрену в Брилл, что в Тирисфальских лесах.', 19865),
(412, 'ruRU', 'Операция "Перенаправление"', 'Принесите Раззлу Шустрецу 8 гиромеханических шестерней.', 'Мне следует вернуться в Гномреган и продолжить исследования, чтобы найти способ вылечить облученных гномов.$b$bНо я оставался в Караносе, потому что это мой город, и я хотел помочь защитить его от атак Мерзлогривов. Я занимался техобслуживанием и ремонтом паровых танков.$b$bПо какой-то причине падальщики Мерзлогривов стали таскать у меня гиромеханические шестерни, которые нужны для завершения ремонта. Все они на передовой Мерзлогривов. Не поможешь мне вернуть эти шестерни?', '', '', '', '', '', 'Вернитесь к Раззлу Шустрецу в Каранос.', 19865),
(413, 'ruRU', '"Мерцающий портер"', 'Отнесите бочонок "Мерцающего портера" горному пехотинцу Ячменовару.', 'Хотелось бы мне, чтобы мой братец Велларт попробовал свежего "Мерцающего портера". Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан.$B$BМожет, он и не такой пивовар, как остальные Ячменовары, но свое пиво он любит, и я знаю, что это тоже ему понравится.$B$BНе отнесешь ему вот этот бочонок "Мерцающего портера"?', '', '', '', '', '', '', 19865);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(416, 'ruRU', 'Ловля крыс', 'Принесите 8 ушей туннельщиков горному пехотинцу Грозовой Вершине на станцию Альгаз.', 'К западу отсюда началось настоящее нашествие. Эти подземные крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю!$b$BИх необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду.$B$BКобольды-туннельщиков поселились на востоке отсюда, в районе Серебряных копей.', '', '', '', '', '', '', 19865),
(417, 'ruRU', 'Месть пилота', 'Убейте Паршивого Когтя.$B$BПринесите его коготь и дневник Хилдельва пилоту Большеногу на заставу у Южных врат.', 'Хилдельв пишет в своем дневнике, что подвергся нападению Паршивого Когтя, "огромного медведя-ледолапа". Он отогнал тварь, но та успела страшно изранить его.$B$BСудя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его.$B$BВ дневнике Хилдельв записал свое последнее пожелание:$B$B"Отомстить Паршивому Когтю".', '', '', '', '', '', '', 19865),
(418, 'ruRU', 'Телcамарские кровяные колбаски', 'Принесите Видре Жаркий Очаг в Телcамар 8 кусков медвежатины.', 'Едоки в Телcамаре не переводятся – еще бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками. Но ты ведь их еще не $gпробовал:пробовала;?$b$bНет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение, |3-6($c).$b$bМне нужна медвежатина, все остальное уже есть. Добудь ее, а уж Видра сготовит все в лучшем виде!', '', '', '', '', '', '', 19865),
(419, 'ruRU', 'Пропавший пилот', 'Пилот Большеног с заставы у Южных врат просит вас найти пилота Хилдельва.', 'Мой друг и напарник, пилот осадной машины Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его машину на крутой холм, там она сломалась!$B$BХилдельв, по-прежнему уверенный, что руда в этих горах есть, оставил меня охранять наши машины, а сам пошел дальше пешком.$B$BНо прошло уже несколько дней, а ночью я слышал какой-то звериный вой севернее озера Хельмово Ложе, к западу от туннеля. Мори – парень-кремень, но мне тревожно.$B$BПрошу тебя, $n, найди его.', '', '', '', '', '', '', 19865),
(421, 'ruRU', 'Проявить себя', 'Далар Ткач Рассвета из Гробницы хочет, чтобы вы убили 5 белоголовов Лунной Ярости.', 'Леди Сильвана поручила Вариматасу завоевать земли людей и дворфов к югу. $b$bНо этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Темного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора. $b$bМне нужен кто-то, искушенный в воинском деле, чтобы разрубить узел, завязанный Аругалом. Убейте 5 белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу. Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом.', '', '', '', '', '', 'Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.', 19865),
(422, 'ruRU', 'Безрассудство Аругала', 'Раздобудьте книгу "Зелье Аругала" и принесите ее Далару Ткачу Рассвета в Гробницу.', 'Для меня загадка, каким образом Аругал вообще был принят в Кирин-Тор. В искусстве магии он был совершеннейший невежда.$b$bСейчас важно точно выяснить, какую магию применил Аругал, чтобы я мог использовать ее против него и обеспечить владычество Темной Госпожи в Серебряном бору. $b$bВначале Аругал останавливался на пшеничной ферме, что к северу от моста. Один из ловчих смерти сообщил о том, что видел какие-то книги с заклинаниями, но не сумел их заполучить. Добудь для меня ту из этих книг, что называется "Зелье Аругала".', '', '', '', '', '', 'Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.', 19865),
(423, 'ruRU', 'Безрассудство Аругала', 'Принесите Далару Ткачу Рассвета в Гробницу 6 наручей обжор Лунной Ярости и 3 наруча чернозлобов Лунной Ярости.', 'Изучив деятельность Аругала, я понял, что мои наихудшие подозрения верны. Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин-Тор в самый трудный час. Идиоты! $b$bДля усиления своей никудышной магии Аругал использовал заколдованные предметы. В первую очередь я должен изучить эти предметы. Отправляйся в путь и убивай обжор Лунной Ярости и чернозлобов Лунной Ярости, пока не наберешь столько заколдованных наручей, сколько потребуется для моих исследований. Эти злобные создания обитают к северу и к востоку отсюда.', '', '', '', '', '', 'Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.', 19865),
(425, 'ruRU', 'Ивар Нечистый', 'Убейте Ивара Нечистого и принесите его голову Ран Йорик на делянку Ивара.', 'Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком. Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый. $b$bНам удалось уйти от Ивара, но он успел как следует приложить Квинна. Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги. $b$bУбейте Ивара, чтобы Квинн мог спокойно поправляться. Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность.', '', '', '', '', '', 'Вернитесь к Ран Йорик в Серебряный бор.', 19865),
(426, 'ruRU', 'Нападение на мельницы', 'Соберите 5 зазубренных ребер и 3 почерневших черепа для стража смерти Диллинджера в Брилле.', 'Плеть пытается основать базу на Мельницах Агамондов. Если им это удастся, они продолжат свои нападения в Тирисфале.$B$BПоступил приказ уничтожить всю Плеть на мельницах.$B$BОтправляйся туда и собери зазубренные ребра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей.$B$BЧтобы добраться до мельниц, иди по дороге на запад. После того как перейдешь мост, поверни на север, и скоро увидишь ветряные мельницы.', '', '', '', '', '', 'Вернитесь к стражу смерти Диллинжеру в Брилл, что в Тирисфальских лесах.', 19865),
(427, 'ruRU', 'Война с Алым орденом', 'Убейте 10 воинов из Алого ордена по просьбе палача Зуганда.', 'Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах.$B$BНо у стражей смерти есть заботы и поважнее: армия Короля-лича растет с каждой ночью. Нам нужен кто-то такой "инициативный", как ты, чтобы навсегда покончить с Алым орденом.$B$BДокажи мне, что $Gспособен:способна; служить Темной Госпоже: отправляйся на запад, к башне за усадьбой Соллиден, и убей 10 воинов из Алого ордена.', '', '', '', '', '', 'Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.', 19865),
(429, 'ruRU', 'Звериные сердца', 'Соберите 6 обесцвеченных сердец ворга и принесите их аптекарю Ренферрелу в Гробницу.', 'Мой брат Квинн был тяжело ранен вурдалаком, Иваром Нечистым, и я не знаю, сможет ли он как следует поправиться без помощи магии. Хотя я сама и не фармацевт, но знаю, что наши аптекари могут изготавливать исцеляющие зелья из обесцвеченных сердец воргов. $b$bСобери такие сердца и отнеси их аптекарю Ренферрелу к Гробнице, на юг отсюда. А потом возвращайся ко мне с зельем. $b$bМножество воргов водится между этим местом и садом Мальдена к востоку отсюда.', '', '', '', '', '', 'Вернитесь к аптекарю Ренферрелу в Гробницу, что в Серебряном бору.', 19865),
(430, 'ruRU', 'Назад к Квинну', 'Отнесите зелье Квинна Квинну Йорику на делянку Ивара, к северу от Гробницы.', 'Вот зелье, которое должно помочь Квинну Йорику поправиться. $b$bА теперь, простите, мне нужно продолжить одно очень важное дело...', '', '', '', '', '', '', 19865),
(432, 'ruRU', 'Проклятые трогги!', 'Убейте 8 головоломов из племени Каменной Челюсти и 8 костегрызов из племени Каменной Челюсти в карьере Гол''Болар.', 'Эти проклятые Светом трогги перевернули все мое рабочее место! Ты только глянь, еще одну бочку пороха разворотили!$b$bОх, прямо руки чешутся спуститься к ним да головы поотрывать! Всех бы поубивал!$b$bНо здоровье не позволяет, да еще это потрясение и злость... Они ничего мне не оставили!$b$bЯ бы сам их перебил, да рука уже не так тверда! Иди в карьер и перебей грязных тварей! Я заплачу! Ты только задай им шороху, перебей их!', '', '', '', '', '', 'Вернитесь к штейгеру Камнелобу в Дун Морог.', 19865),
(433, 'ruRU', 'Слуга народа', 'Раздайте руны возвращения 7 захваченным шахтерам в карьере Гол''Болар.', 'Будучи членом Сената и Лиги исследователей, я взял на себя заботу по изучению условий работы в карьере. Трогги совсем распоясались!$b$bОни просто разнесли весь карьер Гол''Болар. Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и заманивая горняков в подземные ловушки.$b$bМы должны выдворить их оттуда. Мои маги работают сверхурочно, чтобы наложить чары на эти руны возвращения. Если ты сможешь отнести руны захваченным шахтерам, они смогут безопасно вернуться на поверхность.', '', '', '', '', '', 'Вернитесь к сенатору Меру Каменной Реликвии в Дун Морог.', 19865),
(435, 'ruRU', 'Сопровождая Эрланда', 'Проводите Эрланда, защищая его от волков, к Ран Йорик.', 'Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери. Должно быть, они невероятно голодны, раз смогли счесть меня пищей. $b$bЯ должен доложиться своей коллеге, ловчей смерти Ран Йорик. Но чтобы добраться до Ран, мне нужна помощь против этих волков.$b$bПожалуйста, проводите меня! Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья...', 'Проводите Эрланда к Ран Йорик.', 'Проводите Эрланда к Ран Йорик.', '', '', '', 'Вернитесь к Ран Йорик в Серебряный бор.', 19865),
(436, 'ruRU', 'Раскопки Сталекрута', 'Обратитесь к исследователю Удару Топора.', 'Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера. В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов!$B$BСталекрут – надежный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать.$B$BОтправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу. Он ведет отчетность по раскопкам и сможет объяснить, чем вызвана задержка.$B$BЧтобы отыскать раскопки, обогни озеро с юга и направляйся на восток.', '', '', '', '', '', '', 19865),
(437, 'ruRU', 'Мертвые поля', 'Убивайте гноллов из стаи Гнилошкуров на Мертвом поле. $b$bКогда появится банши Плеть Ночи, убейте ее. $b$bСущность банши принесите верховному палачу Хадрику в Гробницу.', 'Первые отчеты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мертвом поле. Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство. $b$bМы хотим уничтожить Плеть Ночи. $b$bОтправляйтесь на Мертвое поле и атакуйте Гнилошкуров. Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и ее. $b$bСущность банши обратится в прах. Принесите мне этот прах в доказательство ее смерти.', 'Войти на Мертвое поле', 'Войти на Мертвое поле', '', '', '', 'Вернитесь к верховному палачу Хадрику в Гробницу, что в Серебряном бору.', 19865),
(438, 'ruRU', 'Старая переправа', 'Отправляйтесь к старой переправе. $b$bПоищите причину присутствия там сил Плети.', '$n, мы обнаружили еще одно место, где угнездилась Плеть: это старая переправа. Переправа находится к востоку от Гробницы, и ее патрулируют многочисленные гноллы-гнилошкуры и различная нежить. $b$bПолагаю, Плеть захватила это место неспроста. Отправляйся к старой переправе и выясни, в чем там дело.', '', '', '', '', '', '', 19865),
(440, 'ruRU', 'Кольцо с гравировкой', 'Отнесите кольцо Делии мировому судье Севрену в Брилл.', 'Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьей Севреном в Брилле. У него должны быть записи о недавних смертях и, если повезет, он сможет выяснить, кто такая Делия. $b$bНо я бы на это не рассчитывал. Тот, кто подарил ей кольцо, вероятно, уже мертв. Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии.', '', '', '', '', '', '', 19865),
(445, 'ruRU', 'Доставка в Серебряный бор', 'Отнесите находки аптекаря Холланда аптекарю Ренферрелу в Серебряном бору.', 'Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и $gсам понял:сама поняла;.$B$BЯ состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Темная Госпожа.$B$BОтнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору. Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад.', '', '', '', '', '', '', 19865),
(447, 'ruRU', 'Рецептура смерти', 'Соберите 6 сердец медведя и 6 образцов Летящей крови и принесите их опытному аптекарю Фаранеллу в Подгород.', 'Силы Артаса неисчислимы. Но, создав новую чуму, мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми. $b$bМои исследования показали, что паучья кровь в соединении с токсином, извлеченном из сердца бешеного медведя, дает смертельно опасный эликсир. Собери необходимые субстанции с пауков из Оплетающей Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору. Принеси реагенты в Подгород аптекарю Фаранеллу из Королевского фармацевтического общества.', '', '', '', '', '', 'Вернитесь к опытному аптекарю Фаранеллу в Район Фармацевтов, что в Подгороде.', 19865),
(454, 'ruRU', 'После засады', 'Поговорите с Мираном.', 'До этого... случая мы все время таскали туда-сюда бочки с порохом. Теперь придется поделить работу: Миран понесет часть бочек, а я присмотрю за остальными.$b$bМне не хочется отпускать Мирана одного. Когда он соберется в путь, проводи, пожалуйста, его.', '', '', '', '', '', '', 19865),
(455, 'ruRU', 'Альгазская битва', 'Пройдите через Дун Альгаз.$B$BУбейте 8 разведчиков из клана Драконьей Пасти и 6 рубак из клана Драконьей Пасти.$B$BОб исполнении доложите Валстагу Сталезубу из Гавани Менетилов.', 'Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине.$B$BПопытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов.$B$BНайти Менетилов несложно: пройдешь через Дун Альгаз, потом – по дороге на север, а на развилке свернешь на запад.$B$BМы очень надеемся на тебя, $n. Не подведи нас.', 'Проникнуть в Дун Альгаз.', 'Проникнуть в Дун Альгаз.', '', '', '', 'Вернитесь к Валстагу Сталезубу в Гавань Менетилов, что в Болотине.', 19865),
(456, 'ruRU', 'Природное равновесие', '[Deprecated] Kill 3 Young Nightsabers and 3 Young Thistle Boars.', 'Мои приветствия, $n. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. $b$bВесенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают.$b$bК несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. $gЮный:Юная:c; |3-6($c), помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.', '', '', '', '', '', '[Deprecated] Return to Conservator Ilthalaine in Shadowglen.', 19865),
(457, 'ruRU', 'Естественное равновесие', 'Убейте 6 облезлых ночных саблезубов и щетинистых вепрей.', 'Истребление детенышей в Тенистой долине – хорошее начало, $n. Однако нас ждет еще много работы.$b$bЛесные ресурсы очень быстро подойдут к концу, если вовремя не устранить проблему. Уничтожение лесного зверья – вынужденное зло во имя блага всех тех, кто населяет эти места. Отправляйся на северо-восток вглубь Тенистой долины и истреби облезлых ночных саблезубов и щетинистых вепрей, чтобы восстановить естественное равновесие.', '', '', '', '', '', '[Deprecated] Return to Conservator Ilthalain in Shadowglen.', 19865),
(458, 'ruRU', 'Защитница леса', 'Найдите дриаду по имени Тариндрелла.', 'Слава небесам, ты здесь, |3-6($c). Лесные духи нашептали мне удивительные вести. Будто бы таинственная защитница леса, Тариндрелла, снова вернулась в Тенистую долину. Ее присутствие не ощущалось в этих лесах с тех пор, как нас осенило благословение Тельдрассила. Должно быть, что-то случилось, раз она вернулась в эти края.$b$bНайди Тариндреллу и узнай, что за дело привело ее в нашу чащу. Одна из часовых видела ее на юго-западе от Альдрассила.', '', '', '', '', '', '', 19865),
(459, 'ruRU', 'Демонические воры', 'Верните украденные у Деллии бобы, воду и сумки.', 'Эти мерзкие мелкие грелли! Они снова крадут наш провиант.$B$BЕсли ты желаешь нам помочь, имей в виду – все, что они у нас сперли, наверняка валяется в их лагерях на западе отсюда. Я с радостью вознагражу тебя, если ты все это мне вернешь.', '', '', '', '', '', 'Вернитесь к Деллии в Альдрассил.', 19865),
(462, 'ruRU', '<UNUSED>', 'Kill Maruk Wyrmscale$B$BReport to Valstag Ironjaw in Menethil Harbor.', 'Other than you, we sent two scouts through Algaz. Only one returned. Here''s what he discovered:$B$BThe Dragonmaws sent one of their Lieutenants, Maruk Wyrmscale, to organize a crew of orcs in Algaz and cut off the land route to Menethil Harbor!$B$BWe have to stop this, now. Take out Maruk, and then report to Valstag Ironjaw in Menethil Harbor.$B$BMaruk is headquartered in a small cave, across a pond between the second and third tunnels of Algaz. Menethil is through Algaz, then west along the road.', '', '', '', '', '', 'Вернитесь к Валстагу Сталезубу в бухту Барадин, что в Болотине.', 19865),
(463, 'ruRU', 'Страж Природы', 'Найдите Стража Природы.', 'Ты ведь $Gслышал:слышала; рассказы о Страже Природы? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим.$B$BОн живет на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями.$B$BОставь-ка свои денежки мне – покойникам они все равно не нужны. Да и дядя-сторож может обломать зуб об твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?', '', '', '', '', '', '', 19865),
(464, 'ruRU', 'Боевые знамена', 'Принесите 8 боевых знамен клана Драконьей Пасти капитану Крепкому Кулаку.', 'К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен. Драконы припомнили им все, гнали бывших хозяев аж до самого Грим Батола. Затем орки скрылись в горах к востоку от раскопа Вельгара.$B$BОтсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила.$B$BНапади на этот лагерь, внеси панику в ряды орков. В доказательство содеянного принеси мне боевые знамена клана.', '', '', '', '', '', 'Вернитесь к капитану Крепкому Кулаку в Гавань Менетилов, что в Болотине.', 19865),
(465, 'ruRU', 'Гамбит Нек''роша', 'Уничтожьте катапульты Драконьей Пасти.', 'Пока ты $Gсражался:сражалась; с кланом Драконьей Пасти, мы получили сведения об их планах.$B$BНек''рош строит катапульты и планирует взять Менетил в осаду! А у нас тем временем вовсю идет битва при Дун Альгаз, и подкрепления ждать неоткуда!$B$BУничтожь катапульты, прошу тебя. Они стоят в лагере Драконьей Пасти.$B$BВозьми вот этот трут. Пробейся к катапультам и подожги их.$B$BПосле этого найди и убей Нек''роша. Этот паршивец уже свое отжил...', '', '', '', '', '', '', 19865),
(467, 'ruRU', 'Найдите Камнекожца', 'Поговорите с пилотом Камнекожицем.', 'Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин! И он всегда рад найти новый способ повысить огневую мощь своих орудий.$B$BДо него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет ее. И если тебе уже не терпится взяться за это дело, то найди Камнекожица в поселке Сталежара в Дун Мороге и спроси, чего он хочет.', '', '', '', '', '', '', 19865),
(468, 'ruRU', 'Отчитайтесь перед горным пехотинцем Рокхаром', 'Поговорите с горным пехотинцем Рокхаром.', 'Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину!$B$BЕсли желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз. Это к северу отсюда, по дороге за сторожевой башней.', '', '', '', '', '', '', 19865),
(469, 'ruRU', 'Ежедневная доставка', 'Отнесите стопку кроколисковых шкур кожевнику Джеймсу Халлорану в Гавань Менетилов.', 'Привет тебе, $Gстранник:путешественница;!$b$bНе лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок!$b$bНу а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана.$b$bЯ бы и сам отнес их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза.', '', '', '', '', '', '', 19865),
(473, 'ruRU', 'Доклад капитану Крепкому Кулаку', 'Найдите капитана Крепкого Кулака и поговорите с ним.', '$n. Орки из клана Драконьей Пасти совсем озверели. Им уже мало одного Альгаза. Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков. Он сейчас в крепости, в зале Войны.', '', '', '', '', '', '', 19865),
(475, 'ruRU', 'Ветер тревоги', 'Найдите Гэроласа Талветрена в Деревне Звездного Ветра.', 'Ветер тревоги веет над лесом.$b$bГэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен''этиль. Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе.$b$bНо вести от Гэроласа что-то задерживаются, и я начинаю волноваться. Отправляйся на восток в Деревню Звездного Ветра – мне нужен отчет Гэроласа, дабы я был спокоен, узнав, что мои братья и сестры спят спокойно.', '', '', '', '', '', '', 19865),
(476, 'ruRU', 'Порча Кривой Сосны', 'Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.', 'Племя Кривой Сосны поражено порчей!$b$bОни подстерегли меня в засаде, когда я выходил из обители Бен''этиль и разграбили Деревню Звездного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны.$b$bЯ слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придется сделать тебе, $Gюный:юная:c; |3-6($c). Остается только надеяться, что безумные фурболги Кривой Сосны еще не уничтожили Бен''этиль!', '', '', '', '', '', '', 19865),
(477, 'ruRU', 'Пересечение границ', 'Раздобудьте содержимое одного из сундуков даларанских волшебников. Деревня Погребальных Костров находится на юге.', 'Как вы, должно быть, знаете, в деревне Янтарная мельница окопалась враждебная группа людей. Она держится там в основном за счет поддержки, которую они получают от волшебников Даларана. $b$bЯ не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной мельницы, показывает, что она имеет немаленькое значение. $b$bОни отправляют повозкой из Хилсбрада сундуки. Многое из привезенного складируется в небольшом лагере к северу от деревни Погребальных Костров. Раздобудьте содержимое одного такого сундука и принесите мне.', '', '', '', '', '', '', 19865),
(481, 'ruRU', 'Анализ Далара', 'Отнесите подвеску рунической надписи Далару Ткачу Рассвета в Гробницу.', 'Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников.', '', '', '', '', '', '', 19865),
(483, 'ruRU', 'Реликвии Пробуждения', 'Добудьте реликвии Пробуждения.', 'Захватчиков Кривой Сосны видели в обители Бен''этиль на западе, они крушили там все подряд.$b$bСпящие друиды могут так никогда и не выйти из Изумрудного Cна, так и не поняв, в какую западню угодили, если мы только им не поможем. Тонкий ритуал сна нельзя нарушить без реликвий Пробуждения.$b$bОтправляйся в обитель и найди талисман Когтя Ворона, Черное перо, Небесный сапфир и руну Размещения. Друиды хранят их в священных ларцах. Принеси их мне, и я подготовлю ритуал пробуждения.', '', '', '', '', '', 'Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.', 19865),
(484, 'ruRU', 'Шкуры молодых кроколисков', 'Принесите 4 шкуры молодых кроколисков Джеймсу Халлорану в Гавань Менетилов.', 'Ты, наверное, $Gслышал:слышала; обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему континенту!$b$bУже $gвстречался:встречалась; с Эйнаром? Он – один из охотников, приносящих мне шкуры.$b$bВ последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков.$b$bУчитывая обстоятельства, я готов заплатить высшую цену за стопку шкур. Молодые кроколиски водятся на болотах прямо за городом.', '', '', '', '', '', 'Вернитесь к Джеймсу Халлорану в Гавань Менетилов, что в Болотине.', 19865),
(485, 'ruRU', 'Найти КПХ-9/HL!', 'Отнесите аварийный маяк к автономному роботу Карлса. Робот находится во Внутренних землях, в устье реки близ Осклизлой скалы.', 'Вы обнаружили странный металлический предмет яйцевидной формы. Когда вы нажали на какую-то кнопку, яйцо вдруг ожило, открылось и превратилось в непонятный механизм, который проскрежетал механическим голосом:$B$B"Меня зовут Карлс Пропеллерз, и мой автономный робот поврежден. Просьба найти робота, вставить в него этот маяк, а потом вернуть мне за вознаграждение".$B$B"Я вычислил координаты робота – он попал в аварию в устье реки близ Осклизлой скалы".', '', '', '', '', '', '', 19865),
(486, 'ruRU', 'Урсал Изверг', 'Убейте Урсала Изверга.', 'Настало время спасти друидов-воронов. Если сейчас мы потерпим неудачу, $n, их сон станет вечным.$b$bЯ подготовлю реликвии Пробуждения и совершу обряд. Но чтобы у меня все получилось, тварь, виновная в их злоключениях, должна быть уничтожена.$b$bЭто Урсал Изверг разрушил дело наших братьев, и именно он должен теперь заплатить за свои злодеяния ради их освобождения. Иди по дороге на северо-запад, потом поверни на север к Расселине. Там будет логово Урсала.', '', '', 'Урсал Изверг', '', '', 'Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.', 19865),
(487, 'ruRU', 'Дорога в Дарнас', 'Убейте 8 душителей из племени Кривой Сосны.', 'Дорогу в Дарнас нужно охранять. Путники, направляющиеся из Доланаара в Дарнас, рассказывают о варварских нападениях пораженных порчей фурболгов из племени Кривой Сосны.$b$bКаждый день из Дарнаса и в Дарнас не доходят грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам.$b$bВозьмись же за оружие во имя священного леса, |3-6($c). Их логово находится где-то над этой северной дорогой. Убей душителей из племени Кривой Сосны и возвращайся ко мне.', '', '', '', '', '', 'Вернитесь к часовому Амаре Ночной Страннице, ее можно найти к западу от Доланаара.', 19865),
(488, 'ruRU', 'Просьба Зенна', 'Достаньте 2 клыка ночного саблезуба, 2 пера островной совы и 2 мотка паутины чащобного тенетника.', 'Вижу, ты ищешь работенку. Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце $Gюному:юной:c; |3-2($c) вроде тебя.$b$bВидишь ли, $n, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесешь.$b$bМне часто бывают нужны определенные... ингредиенты. Принеси клыки ночного саблезуба, перья островной совы и мотки паутины чащобного тенетника.$b$bИ пусть это все останется между нами, |3-6($r).', '', '', '', '', '', 'Вернитесь к Зенну Грязному Копыту, его можно найти возле Доланаара.', 19865),
(489, 'ruRU', 'Искупление вины', 'Соберите 3 шишки Скверны.', 'Совет Леса узнал, что ты $Gпомог:помогла; Зенну Грязному Копыту! Этот сатир – враг леса! И ты, как |3-6($r), $Gдолжен бы:должна бы; понимать, что оскверняешь лес, убивая созданий Природы!$b$bТы $Gдолжен:должна; искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу! $b$bПреподай Грязному Копыту урок – и заслужишь прощение. Есть такие шишки Скверны – это семена, падающие с деревьев. Они испускают зеленый дым.$b$bСкорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое.', '', '', '', '', '', 'Вернитесь к Зенну Грязному Копыту, его можно найти возле Доланаара.', 19865),
(490, 'ruRU', '<UNUSED>', 'Шейла Ночной Бриз у ворот Дарнаса просит принести ей 20 клыков фурболгов из племени Кривой Сосны.', 'By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.$b$bAs decreed by the Council, you shall be rewarded for removing the furbolg menaces from Kalidar. Bring to me their fangs as proof of your deeds.', '', '', '', '', '', 'Вернитесь к часовому Шейле Ночному Бризу в Тельдрассил.', 19865),
(493, 'ruRU', 'Путешествие в предгорья Хилсбрада', 'Отнесите находки аптекаря Ренферрела аптекарю Лидону в деревню Мельница Таррен в предгорьях Хилсбрада.', 'Темная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало Новую чуму. Мы упорно трудимся и добились значительного прогресса. Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества. $b$bПоэтому я хотел бы, чтобы вы доставили мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада. Путь туда неблизкий. $b$bНаправляйтесь на юг и держитесь поближе к дорогам. Строго следуйте дорожным указателям!', '', '', '', '', '', '', 19865),
(494, 'ruRU', 'Время нанести удар', 'Отправляйтесь в Мельницу Таррен и доставьте послание ловчей смерти Леш верховному палачу Дарталии.', 'Молчи и слушай, |3-6($c).$B$BМеня направили сюда для наблюдения за Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что ловчая смерти Леш передала следующие слова:$B$B"Крик ворона на западе манит."$b$bСтупай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной поспешностью!', '', '', '', '', '', '', 19865),
(495, 'ruRU', 'Корона Воли', 'Поговорите с Мелизарой в Мельнице Таррен в предгорьях Хилсбрада.', 'Муг''тола и его отряд огров отправили в Альтеракскую долину за короной Воли для леди Сильваны. К сожалению, вместо того чтобы принести ее королеве, этот идиот решил ее примерить... наверное, огры не могут устоять перед блестящими побрякушками.$B$BЕго необдуманный поступок привел к неприятным последствиям. Корона Воли позволила Муг''толу воспротивиться заклинанию подчинения, наложенному на него леди Сильваной.$B$BТемная Госпожа хочет, чтобы это стало уроком для остальных. Отправляйся на мельницу Таррен в Хилсбраде и поговори с лейтенантом Мелизарой.', '', '', '', '', '', '', 19865),
(497, 'ruRU', '<UNUSED>', 'Go to Tarren Mill and find out the status of the party sent by Thrall.', 'As a child, raised as a gladiator at Durnholde Keep, I was befriended by Taretha, the daughter of my wet nurse and mistress of the damned bastard Blackmoore.$b$bThe past is the past, $n, but reports of human movements in Hillsbrad reminded me of that time. I dispatched a small party to the area to investigate and to retrieve an... item... given to me by Taretha, if they could.$b$bA fruitless task, no doubt, but perhaps...$b$bThey should have returned by now, I want you to go to Tarren Mill to investigate.', '', '', '', '', '', '', 19865),
(501, 'ruRU', 'Эликсир боли', 'Принесите 10 сосудов крови горного льва аптекарю Лидону из Мельницы Таррен.', 'О, $n... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит! Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесет в мир заслуженную смерть!$B$BНо как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Темной Госпожи. Помоги мне! В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти. Принеси мне немного крови, и мы повеселимся.', '', '', '', '', '', 'Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.', 19865),
(515, 'ruRU', 'Эликсир агонии', 'Отнесите микстуру из цветков Грязного Рыла, крепкое зелье тролльей крови, 5 чешуек нагов из клана Пронзающего Гребня и 5 глаз мурлоков из клана Рваный Плавник аптекарю Лидону в Мельницу Таррен.', 'Смесь из цветков Грязного Рыла? Гениально! Почему мне не пришло это в голову?$B$BПожалуй, я добавлю свой коллоид разложения в эту хитрую смесь.$b$bЧтобы активировать отраву в смеси, Лидону понадобится крепкое зелье тролльей крови, немного чешуи наги из клана Пронзающего Гребня и глаза мурлоков из клана Рваный Плавник с южного берега Хилсбрада. Когда ты принесешь ему все составляющие, он мигом все сделает. Ох, как мне не терпится узнать о результатах его эксперимента!', '', '', '', '', '', 'Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.', 19865),
(525, 'ruRU', 'Все больше тайн', 'Доставьте расшифрованное письмо мировому судье Южнобережья Малебу.', 'Я расшифровал письмо, но не знаю, что с ним дальше делать. Вы нашли его у воров в предгорьях Альтерака? Очень странно...$B$BНадо доставить это письмо мировому судье Южнобережья. Хотя письмо и зашифровано, это ближайший город к горам Альтерака, и если назревает какая-то опасность, то они должны об этом узнать.', '', '', '', '', '', '', 19865),
(532, 'ruRU', 'Битва за Хилсбрад', 'Убейте мирового судью Бернсайда, и 4 членов совета Хилсбрада. Уничтожьте Хилсбрадское официальное объявление. Украдите регистрационную книгу Хилсбрада. Возвращайтесь к Дарталии на мельницу Таррен.', 'В Хилсбраде царит паника. Думаю, он скоро падет. Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки.$B$BНевзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия. Мы должны уничтожить их главу, мирового судью Бернсайда, и весь городской совет. Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации.', '', '', '', '', '', 'Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.', 19865),
(543, 'ruRU', 'Тиара Перенольда', 'Найдите тиару Перенольда.', 'Тиара Перенольда – старая семейная реликвия одного из древнейших семейств Альтерака, входившего в правящие круги до падения королевства. Говорят, что ее изготовили мастера Стальгорна, украсив лучшими изумрудами.$B$BКогда Альтерак пал, тиара была утеряна, хотя поговаривали, что огрский маг Грел''борг Скряга нашел ее и теперь пытается разыскать на руинах Альтерака другие сокровища.$B$BМы надеемся, что вы отыщете тиару.', '', '', '', '', '', 'Вернитесь к графу Ремингтону Риджвеллу в крепость Штормграда.', 19865),
(567, 'ruRU', 'Вооружены и очень опасны!', 'Верховный палач Дарталия из Мельницы Таррен назначила награду за убийство клерка Горация Белоконя, гражданина Уилкса, шахтера Хакетта и фермерши Калабы.', 'Внимание: вооружены и очень опасны!$b$bСледующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:$b$bКлерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма.$b$BГорожанин Вилкс. Разыскивается за убийство аптекаря Эли.$b$BШахтер Хакетт. Разыскивается за убийство ловчего смерти Фрая.$b$BФермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода.$b$bВсе перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти.', '', '', '', '', '', 'Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.', 19865),
(570, 'ruRU', 'Чары Мок''тардина', 'Провозвестник Мок''тардин из лагеря Гром''гол попросил вас принести ему 8 когтей тенебрюхих пантер и безупречный тигриный клык.', 'Орда должна узнать о силе магии джунглей и подчинить ее себе. Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями. Я сделаю для тебя особую вещь, $gотважный:отважная:c; |3-6($c).$B$BПринеси мне когти тенебрюхих пантер и клык тигрицы. Учти, что клык должен быть безупречно ровным.$B$BЭти твари разгуливают по всем джунглям, но тебе не придется далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке.', '', '', '', '', '', 'Вернитесь к провозвестнику Мок''тардину в лагерь Гром''гол, что в Тернистой долине.', 19865),
(571, 'ruRU', 'Чары Мок''тардина', 'Принесите сухожилие старой гориллы провозвестнику Мок''тардину в лагерь Гром''гола.', 'Следующий компонент будет нелегко найти.$B$BЧтобы связать перья, когти и чистый клык, мне понадобится волшебный шнурок. Нам подойдет лишь сухожилие старой гориллы.$B$BЕго можно добыть только у старых горилл Мглистой долины. Они кормятся к востоку от Пиратской Бухты.$B$BТолько сухожилие должно быть в идеальном состоянии. Быть может, тебе понадобится убить нескольких зверей, чтобы понять, что именно мне нужно, но результат того стоит.', '', '', '', '', '', 'Вернитесь к провозвестнику Мок''тардину в лагерь Гром''гол, что в Тернистой долине.', 19865),
(574, 'ruRU', 'Особые войска', 'Убейте 10 коммандос и 6 охотников за головами Курцена.$B$BДоложите об этом лейтенанту Дорену из Лагеря Повстанцев.', 'После удара по обычным партизанам Курцена тебе придется вступить в схватку с его особыми отрядами. Они либо выбираются в лес и убивают наших солдат, либо отсиживаются позади поселка Курцена, в пещере, называемой Схрон.$B$BЯ знакома со многими воинами Курцена, и все они отличаются прекрасной подготовкой, верностью и жестокостью. Задание непростое, $n.$B$BЕсли ты сможешь их одолеть, доложи об этом лейтенанту Дорену, моему командиру. Он захочет услышать об этом из первых уст.', '', '', '', '', '', 'Вернитесь к лейтенанту Дорену в Лагерь Повстанцев, что в Тернистой долине.', 19865),
(576, 'ruRU', 'Смотри в оба', 'Диззи Одноглазый из Пиратской Бухты попросил вас отобрать его глаз у пиратов Кровавого Паруса.', 'Стой! Кто идет?$B$BАррр, кому я нужен без волшебного глаза. Мало того, что я лишился зрения в бою! Но тогда мне свезло, и один волшебник зачаровал для меня особый стеклянный глаз, и я снова мог видеть.$B$BА вчера на меня по дороге накинулись пираты Кровавого Паруса и отобрали у меня глаз! Кажется, эти типы чувствуют себя в Пиратской Бухте как дома.$B$BНе поможешь старому морскому волку вернуть зрение?', '', '', '', '', '', 'Вернитесь к Одноглазому Диззи в Пиратскую Бухту, что в Тернистой долине.', 19865),
(579, 'ruRU', 'Библиотека Штормграда', '', '', '', '', '', '', '', 'Вернитесь к Доналу Товальду в Штормград.', 19865),
(580, 'ruRU', 'Потерянный грог Алкача Виски', 'Алкач Виски из Пиратской Бухты попросил вас принести ему потерянные бутылки портвейна "Пупелливербос".', 'На подходе к Отвесным скалам, как раз в тот момент, когда старые добрые Внутренние земли показались на горизонте, нас настигла жуткая буря. Мы думали – все, нам каюк, море нас проглотит.$B$BНо старый Алкач знает, что такое жидкая храбрость! У кэпа был ящик портвейна "Пупелливербос", который мы взяли трофеем у одного пирата по пути в Штормград.$B$BВ общем, когда с Внутренних земель налетел шторм, я налег на грог. И тут шхуну захлестнула большая волна и смыла бутылки за борт. Кэп всыплет мне по первое число, если ты не поможешь их найти.', '', '', '', '', '', 'Вернитесь к Алкачу Виски в Пиратскую Бухту, что в Тернистой долине.', 19865),
(581, 'ruRU', 'Поиски Йеннику', 'Принесите 9 клыков тролля из племени Кровавого Скальпа Нимбойе в лагерь Гром''гол.', 'Нас постиг злой рок. И коснулось это младшего сына моего вождя. Как у нас и заведено, мы отдали его на воспитание племени Гурубаши в Зул''Гурубе, но после того, как племя Черного Копья последовало за орком Траллом, бедняга Йеннику оказался потерян для нас. Меня прислали в Тернистую долину из далекого Оргриммара на поиски сына вождя.$B$BЯ думаю, он в руках племени Кровавого Скальпа.$B$BЕсли ты хочешь помочь мне, напади на них. Они живут к северу отсюда. Собери их клыки и принеси мне.', '', '', '', '', '', 'Вернитесь к Нимбойе в лагерь Гром''гол, что в Тернистой долине.', 19865),
(583, 'ruRU', 'Добро пожаловать в джунгли', 'Поговорите с Хемингом Эрнестуэем-младшим.', 'Добро пожаловать в Тернистую долину!$b$bБыть может, ты не знаешь об этом, но этот дворф – сын единственного и неповторимого Хеминга Эрнестуэя, прославленного героя Альянса и великого охотника на крупную дичь. Подобно отцу, он не слишком жалует гостей, но на твою долю выпало немало приключений, |3-6($c).$b$bСтупай, поговори с ним. Яблочко от яблоньки, как говорится, далеко не падает... наверное, он сможет научить тебя охотиться.', '', '', '', '', '', 'Поговорите с Хемингом Эрнестуэем-младшим в лагере экспедиции Эрнестуэя, что в Северной Тернистой долине.', 19865),
(586, 'ruRU', 'Разговор с Ган''зулахом', 'Убейте 8 охотников, 6 охотников за головами и 4 берсерков из племени Дробителей Черепов.$B$BПринесите разбитую броню Анатека к бурлящему котлу в лагере Гром''гол.', '<Голова Ган''зулаха начинает говорить.>$B$BБудь ты $gпроклят:проклята;! И будь прокляты твои предки!!!$B$BЛишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что:$B$BОтправляйся в сердце владений Дробителей Черепов на востоке. Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому. Ха! Принеси мне его разбитую броню, если сможешь!$B$BДа оторвет он у тебя руки и ноги и бросит медленно гнить. Да станешь ты добычей падальщиков!', '', '', '', '', '', 'Вернитесь к бурлящему котлу в лагерь Гром''гол, что в Тернистой долине.', 19865),
(587, 'ruRU', 'Понюшка табака', 'Диг из Пиратской Бухты попросил принести ему 15 понюшек табаку.', 'Ах, жизнь моряцкая! Не скажу, что она хороша, но это моя жизнь.$B$BПришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку. Вредные привычки, но что за пират без пороков, а?$B$BТолько представь, как я был разочарован, узнав, что местный травник распродал весь товар. Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса.$B$BГотов поспорить, что $gбесстрашный:бесстрашная:c; |3-6($c) вроде тебя сможет убедить их поделиться товаром, а?', '', '', '', '', '', 'Вернитесь к Дигу в Пиратскую Бухту, что в Тернистой долине.', 19865),
(589, 'ruRU', 'Поющие кристаллы', 'Принесите 3 пульсирующих синих осколка Кин''вилаю в лагерь Гром''гол.', 'Легенды повествуют о драгоценном камне, сокрытом в самом сердце Тернистой долины. Мы зовем его Оком разума, и он хранит в себе великую мощь. Если добыть этот камень, быть может, удастся вернуть Йеннику из тьмы.$B$BЯ попрошу духов джунглей помочь нам в поисках Ока разума. Тем временем отправляйся в рудник Хрустальной шахты на юго-востоке отсюда и добудь пульсирующие синие осколки из железозубых василисков. Осколки встречаются очень редко, но без их магии мы не сможем подчинить себе Око разума.', '', '', '', '', '', 'Вернитесь к Кин''вилаю в лагерь Гром''гол, что в Тернистой долине.', 19865),
(597, 'ruRU', 'Пираты Кровавого паруса', 'Отнесите находку первому помощнику Краззу в Пиратскую Бухту.', 'На карте Пиратской Бухты нарисован красный крестик именно там, где вы стоите.$B$BНиже имеется подпись:$B$B"Разбейте здесь лагерь и сидите тихо. Не нападайте, пока не получите сигнал с южного командного поста. Если заметите кого постороннего, сразу убивайте".', '', '', '', '', '', 'Поговорите с первым помощником Краззом в Пиратской Бухте, что в Тернистой долине.', 19865),
(598, 'ruRU', 'Ожерелье расколотых костей', 'Принесите 25 ожерелий Расколотых костей Кин''вилаю в лагерь Гром''гол.', 'Раз ты $gпринес:принесла; трофеи от Кровавого Скальпа, у меня есть для тебя другое задание. На юго-востоке живет племя Дробителей Черепов, и мы воевали с ними много лет. Хотя племя Черного Копья давно не живет в Тернистой долине, мы не забыли раздоров с Дробителями Черепов.$B$BТак что начни на них охоту. Собери побольше ожерельев Расколотых костей и принеси их мне. Помоги нам, и заслужишь признательность племени Черного Копья.', '', '', '', '', '', 'Вернитесь к Кин''вилаю в лагерь Гром''гол, что в Тернистой долине.', 19865),
(605, 'ruRU', 'Осколки Поющих кристаллов', 'Принесите Шиззи Пуззыриксу 10 осколков Поющих кристаллов.', 'Поющие кристаллы добывают только в Тернистой долине, и некоторые покупатели готовы немало за них отсыпать. Кому их толкнуть, мне ясно, но проклятая Торговая Компания не дает собирать кристаллы честным предпринимателям вроде меня.$B$BЯ хочу тебя нанять.$B$BВасилиски Тернистой долины питаются этими кристаллами. Благодаря им у них прочная шкура, и иногда из нее можно добыть качественные кристаллы.$B$BГодится шкура любого василиска, но на северном побережье, южнее Зул''Кунды, они не такие свирепые.', '', '', '', '', '', 'Вернитесь к Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.', 19865),
(606, 'ruRU', 'Напугать Трусишку', 'Отнесите 5 потрохов горилл Мглистой долины Филиппу "Трусишке" в Пиратскую Бухту.', 'Вот кого я терпеть не могу, так это тех, кто не отдает карточные долги! Мне задолжали несколько партнеров по игре. Не поможешь собрать с них мзду?$B$BВо-первых, есть Филипп "Трусишка", который вечно торчит у причала. Он проиграл мне кругленькую сумму на прошлой неделе, и я хочу ее получить! Только для этого надо его хорошенько припугнуть.$B$BСтупай, поохоться на старых горилл Мглистой долины. Набери из них потрохов и отнеси Трусишке. Только не говори, что они обезьяньи, пусть в штаны со страху наложит!', '', '', '', '', '', 'Вернитесь к Филиппу "Трусишке" в Пиратскую Бухту, что в Тернистой долине.', 19865),
(608, 'ruRU', 'Пираты Кровавого Паруса', 'Командир флота Морской Рог из Пиратской Бухты попросил вас убить капитана Штиллеца, капитана Кильвателя и командира флота Фираллона.', 'Ну и наглец этот Фираллон! Он бы и Озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот!$B$BПираты Кровавого Паруса поплатятся за свою беспечность. Теперь мы знаем все их планы и нападем первыми.$B$BХотя зачем посылать целый флот, если хватит отряда отважных искателей приключений? $n, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров. Весь флот отправится на дно следом за ними...', '', '', '', '', '', 'Вернитесь к командиру флота Морскому Рогу в Пиратскую Бухту, что в Тернистой долине.', 19865),
(609, 'ruRU', 'Должники вуду', 'Принесите деревянную ногу Моури, золотую подзорную трубу Джон-Джона и огромное кольцо Чаки "Морскому волку" Маккинли в Пиратскую Бухту.', 'Список сокращается, но должники все еще остались.$B$BДалее идут Моури "Деревянная Нога" Вилкинс, Джон-Джон Ворон и Чаки "Недотепа".$B$BЭти паршивые собаки просрочили платежи на много месяцев, я-то думал, они поэтому из города сбежали! Потом, правда, мне сказали, что их прокляли и заколдовали, и они бродят по развалинам в джунглях. Но меня их судьба не волнует – мне бы свое вернуть!$B$BИх видели на северо-востоке отсюда, в руинах Абораза и руинах Жубуваля. Отыщи их и забери у них мои вещи.', '', '', '', '', '', 'Вернитесь к "Морскому волку" Маккинли в Пиратскую Бухту, что в Тернистой долине.', 19865),
(616, 'ruRU', 'Остров духов', 'Поговорите с бароном Ревилгазом в Пиратской Бухте.', 'Барон Ревилгаз велел мне не упускать слухов о странных событиях и местах в округе Пиратской Бухты и всей Тернистой долины. Обычно я не придаю большого значения историям про призраков и прочую чушь, но моряки в таверне говорили об острове элементалей недалеко от побережья. Мол, там духи Воды и сумасшедший призрак гоблина.$B$BЕсли тебе встретится Ревилгаз, перескажешь ему эту историю?', '', '', '', '', '', 'Поговорите с бароном Ревилгазом в Пиратской Бухте, что в Тернистой долине.', 19865),
(617, 'ruRU', 'Вязанка акириса', 'Принесите каперу Блоудсу из Пиратской Бухты 10 вязанок акириса.', 'Ищешь работу, $n? Если ты не боишься трудностей, могу тебе предложить одно дельце.$B$BУ меня есть дружбан, Гроу, который зашибает бешеные деньги, продавая то, что наги называют стеблями акириса. Это очень ценная морская водоросль. Он за нее отлично платит.$B$BПритащи мне 10 стеблей этой травки, и мы сторгуемся. Наги живут на берегу к северу отсюда.', '', '', '', '', '', 'Вернитесь к каперу Блоудсу в Пиратскую Бухту, что в Тернистой долине.', 19865),
(618, 'ruRU', 'Бой с Неголашем', 'Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Смоттса.$B$BУбейте Неголаша и отнесите абордажную саблю Смоттса хозяину в Тернистую долину.', 'Неголаш – великан-обжора.$B$BКогда они уничтожили наш корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!$B$BЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!', '', '', '', '', '', 'Вернитесь к капитану Гекельбери Смоттсу в Пиратскую Бухту, что в Тернистой долине.', 19865),
(620, 'ruRU', 'Кушак с монограммой', 'Верните кушак с монограммой владельцу.', 'Вдоль каймы кушака вышита монограмма "ГС".', '', '', '', '', '', 'Разыщите владельца кушака с монограммой в Пиратской Бухте, что в Тернистой долине.', 19865),
(621, 'ruRU', 'Тайна Занзила', 'Принесите Шиззи Пуззыриксу из Пиратской Бухты 12 образцов смеси Занзила.', 'Занзил Отверженный и его приспешники живут на руинах Жубуваля и Абораза на северо-востоке от Пиратской Бухты. Его изгнали из племени. Почему? Ну...$B$BЗанзил научился подчинять себе разум других, и его страшатся собственные командиры. Он заставляет своих приспешников принимать смесь из тропических растений, и она подавляет их волю и укрепляет тела.$B$BЭта смесь пригодилась бы любому, кто желает повелевать чужим разумом.$B$BПринеси мне образцы этой смеси, и уж я-то найду им применение.', '', '', '', '', '', 'Вернитесь к Шиззи Пуззыриксу на Пустынный берег, что в Тернистой долине.', 19865),
(631, 'ruRU', 'Мост Тандола', 'Найдите Ржавого Засова для Рага Гармасона.', 'Я помню, как горы содрогнулись от ужаснейшего взрыва. Неслабо рвануло, скажу я тебе!$b$bНа мосту Тандола погибли лучшие из наших солдат. Длиннокос говорит, что дворфы Черного Железа еще заплатят нам за все до конца этой войны.$b$bНо сейчас у нас отчаянное положение, подкрепления все нет и нет. Длиннокос отправил Ржавого Засова на разведку к восточному мосту – посмотреть, можно ли защитить мост теми силами, которые сейчас у нас есть.$b$bПрошло уже несколько дней. Мы не можем отправить солдат на поиски – Дун Модр осажден...$b$bБыть может, ты согласишься поискать нашего разведчика?', '', '', '', '', '', '', 19865),
(632, 'ruRU', 'Мост Тандола', 'Принесите печальное известие Рагу Гармасону в Дун Модр в Болотину и отдайте ему пергамент, найденный возле трупа Ржавого Засова.', 'Кажется, бедняга Ржавый Засов попал в засаду дворфов Черного Железа. Возле его остывшего тела лежит клочок пергамента.$b$bРасскажите Рагу Гармасону о случившемся и передайте ему пергамент.', '', '', '', '', '', '', 19865),
(633, 'ruRU', 'Мост Тандола', 'Уничтожьте взрывчатку.', 'Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня $Gопечалил:опечалила;, $n.$b$bНо его жертва будет не напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с Нагорьем Арати.$b$bЕсли ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай все возможное, чтобы спасти мост Тандола, и возвращайся ко мне.$b$bТы – наша единственная надежда.', '', '', '', '', '', 'Вернитесь к Рагу Гармасону в Дун Модр, что в Болотине.', 19865),
(634, 'ruRU', 'Просьба о помощи', 'Найдите капитана Ниалс в Опорном пункте на Нагорье Арати.', 'Я попрошу тебя о еще одном одолжении, |3-6($c). Мы ожидаем подкрепление из Стальгорна. Рогго принес сведения о лагере воинов Альянса к северу отсюда. Они расположились на Нагорье Арати, возле Опорного пункта.$b$bОтправься туда и отыщи капитана Ниалс. Спроси у очаровательного капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола.', '', '', '', '', '', '', 19865),
(642, 'ruRU', 'Плененная принцесса', 'Соберите 12 частиц Мизраэль и принесите их к радужным осколкам в Теснине Сухоусов.', 'Меня зовут Мизраэль. Я принцесса духов земли, и мои пленители – великаны – поймали меня в ловушку глубоко под Нагорьем Арати. С миром на поверхности я могу говорить только при помощи этих кристаллов.$B$BПожалуйста, помоги мне. У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в Теснине Сухоусов, к востоку отсюда. Чтобы объединить их силу, нужно отобрать у кобольдов частицы Мизраэль.$B$BПрошу тебя, $n, помоги мне!', '', '', '', '', '', 'Разыщите радужные осколки в Теснине Сухоусов, что на Нагорье Арати.', 19865),
(648, 'ruRU', 'Спасти КПХ-17/TN!', 'Сопроводите КПХ-17/TN в безопасное место, затем сообщите об этом Карлсу Пропеллерзу в Пиратской Бухте.', 'Из динамика снова слышится искаженный помехами голос гнома:$b$b"Мне необходимо перегнать КПХ-17/TN в просторное и безопасное место, чтобы провести длительную процедуру наладки. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, к Пещерам Времени! Это самое подходящее место, и там достаточно просторно, чтобы подготовить аппарат к новому полету.$b$bПроводите робота к Пещерам, а затем сообщите об этом мне. Я живу в Пиратской Бухте, меня зовут Карлс Пропеллерз. Конец связи!"', 'Проводить КПХ-17/TN в безопасное место', 'Проводить КПХ-17/TN в безопасное место', '', '', '', 'Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.', 19865),
(659, 'ruRU', 'Новая чума зарождается?', 'Найдите Кви и Кинелори у фермы Го''Шека на Нагорье Арати.', 'Приветствую, $n, приятно познакомиться. Я руковожу группой смельчаков, расследующих странные происшествия в этом районе.$b$bМоим родственникам в Хилсбраде недавно пришлось избавиться от своей собаки Стэнли, потому что животное таинственным образом выросло до невообразимых размеров и стало кидаться на каждого встречного.$b$bЯ уверен, что тут замешана нежить, и мы ищем доказательства.$b$bДве моих спутницы, Кви и Кинелори, отправились к ферме Го''Шека, что находится на Нагорье Арати, и давно не подавали о себе вестей. Найдешь их? А то я начинаю беспокоиться.', '', '', '', '', '', '', 19865),
(681, 'ruRU', 'Северное поместье', 'Убейте 10 проходимцев из Синдиката и 6 наемников Синдиката.$B$BЗатем вернитесь к капитану Ниалс в Опорном пункте.', 'Мы ведем войну со Стромгардом и терпим в ней поражение. Мы делим наш некогда великий город с ограми и Синдикатом, каждая группировка бьется с другой, и конца этому не видно.$b$bНо наши силы иссякают, в то время как силы наших врагов – растут.$b$bНам нужна помощь из Южнобережья, но есть проблемы с доставкой припасов, поскольку Синдикат контролирует территорию между нами.$B$BПойдите на базу Синдиката в Северном поместье и убейте их. Тогда, может быть, давление на наши транспортные пути ослабеет, и доставлять припасы станет проще.', '', '', '', '', '', 'Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.', 19865),
(682, 'ruRU', 'Знаки Стромгарда', 'Принесите 7 знаков Стромгарда Капитану Ниалс в Опорный пункт.', 'Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.$B$BМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!$B$BОтправляйтесь в район Стромгарда, контролируемый Синдикатом, и отберите у их бойцов наши знаки.', '', '', '', '', '', 'Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.', 19865),
(684, 'ruRU', 'Разыскивается: Марез Клобук', 'Принесите капитану Ниалс в Опорный пункт голову Марез.', 'Назначена награда за голову Марез Клобук, высокопоставленной советницы и деятеля Синдиката. В последний раз ее видели на контролируемой Синдикатом территории Стромгарда.$B$BНаграду можно будет получить у капитана Ниалс.$B$BПредупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. Вооружена и очень опасна!', '', '', '', '', '', 'Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.', 19865),
(685, 'ruRU', 'Разыскивается: Отто и лорд Соколиный Шлем', 'Принесите головы Отто и лорда Соколиного Шлема капитану Ниалс в Опорный пункт.', 'Ополчение Стромгарда уведомляет о назначении награды за головы лорда Соколиного Шлема и его телохранителя Отто. Соколиный Шлем руководит деятельностью Синдиката на Нагорье Арати, и его смерть внесла бы большую сумятицу.$B$BЕго телохранитель Отто, хотя и не является стратегической целью, представляет собой опасного противника, на счету которого – смерть десятков наших воинов.$B$BНаграды за их головы можно получить у капитана Ниалс.', '', '', '', '', '', 'Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.', 19865),
(690, 'ruRU', 'Просьба Малина', 'Найдите Скуэрто в Опорном пункте на Нагорье Арати.', 'Приветствую вас, $n. Вы похожи на искателя приключений, а у меня как раз есть задание, требующее склонности к авантюрам.$B$BВерховный маг Трелан, мой первый наставник, не так давно бежал из Стромгарда, что на Нагорье Арати, и просил меня помочь ему вернуть несколько предметов, которые он там оставил.$B$BГород был осажден, и Трелан попытался защитить Башню Аратора, но потерпел неудачу. У меня на нагорье есть агенты, но они просили дополнительной помощи. Вы согласитесь мне помочь?', '', '', '', '', '', '', 19865),
(691, 'ruRU', 'На вес золота', 'Найдите 10 клыков троллей племени Сухокожих, 4 лекарских сумки племени Сухокожих и нож Темного охотника и принесите их ученику Крайтену в Опорном пункте.', 'Верховный маг Малин послал нас со Скуэрто собирать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда вы здесь, думаю, моя проблема решена.$B$BВот что мне нужно: клыки троллей из племени Сухокожих, лекарские сумки племени Сухокожих и нож темного охотника.$B$BНе могли бы вы добыть это все для меня? Племя Сухокожих обитает к юго-востоку от Арати.', '', '', '', '', '', 'Вернитесь к ученику Крайтену на Опорный пункт, что на Нагорье Арати.', 19865),
(704, 'ruRU', 'Судьба Эгмонда', 'Принесите 4 резные каменные урны геологу Сталекруту в Лок Модан.', 'Последний рапорт от Эгмонда был весьма тревожен, возможно, бедняги уже нет в живых! Он сообщил, что его землекопы обнаружили некие "древние погребальные урны" на раскопках близ Ульдамана. Боюсь, эта находка привлекла внимание троггов, так же как и идолы, найденные мною здесь. $B$BМне нужно получить эти урны для исследований. Отправляйся к раскопкам Ульдамана, собери урны и возвращайся ко мне', '', '', '', '', '', 'Вернитесь к геологу Сталекруту на Раскопки Сталекрута, что в Лок Модане.', 19865),
(707, 'ruRU', 'Вы нужны Сталекруту!', 'Поговорите с геологом Сталекрутом на раскопках Сталекрута близ озера Лок.', '$n. Я получил отчет геолога Сталекрута о ходе раскопок в Лок Модане. Ему нужен курьер для осуществления контроля за другими нашими земляными работами.$B$BБольше ничего сказать не могу, но если желаешь ноги поразмять, отправляйся к Сталекруту.', '', '', '', '', '', '', 19865),
(709, 'ruRU', 'Лекарство от судьбы', 'Принесите табличку Рьюн''эха Тельдарину Заблудшему.', 'О небеса милосердные! Сама судьба стучится в двери! Помяните мое слово! Рок! Фатум! $B$BНет, я не могу более ничего сказать... Не могу поминать их имен, чтобы они не услышали меня! Но если нам удастся хотя бы узнать о них больше... Может, мы сможем противостоять им! $B$BМожет быть... $B$BИди в Ульдаман – проклятье, я все же произнес это! Найди табличку... табличку Рьюнэха. Да, найди ее! Не заставляй меня повторять! $B$BОна там, в глубине, в древнем сундуке, более древнем, чем любая доселе найденная работа дворфов.', '', '', '', '', '', 'Вернитесь к Тельдарину Заблудшему в Удел Эгмонда, что в Бесплодных землях.', 19865),
(718, 'ruRU', 'Миражи', 'Верните ящик с припасами Сигруну Рудотесу.', 'В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами. Местные огры из лагеря Кош набросились на них, как стервятники на падаль. Хотя воняют огры не лучше... чем падаль, я имею в виду. $b$bВ общем, они растащили все наши обозы с оружием и прочим скарбом и... Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды... $b$bНе $gмог:могла; ли бы ты нам помочь?', '', '', '', '', '', 'Вернитесь к Сигруну Рудотесу в Бесплодные земли.', 19865),
(719, 'ruRU', 'Дворф и его инструменты', 'Найдите счастливую кирку Ржанца и верните ее геологу Ржанцу к югу от карьера Тяжелоступа.', 'Будь $gосторожен:осторожна;, $n! Повсюду шныряют дворфы Черного Железа – видимо, из клана Тенегорн. $B$BОни только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа. Я едва ноги унес.$B$BРаскоп прямо к северу отсюда. Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку.$B$BКак думаешь – сумеешь помочь? Наверняка кто-нибудь из этих гадов Черного Железа спер мою кирку!', '', '', '', '', '', 'Вернитесь к геологу Ржанцу в Бесплодные земли.', 19865),
(720, 'ruRU', 'Предвестник надежды', 'Найдите геолога Ржанца и сообщите, что Грез Тяжелоступ жив.', '<куском мела на карте нацарапаны слова>"Ржанец, они уводят меня в Ульдаман. Пришли помощь!$B-Тяжелоступ"', '', '', '', '', '', 'Поговорите с геологом Ржанцем в Бесплодных землях.', 19865),
(721, 'ruRU', 'Предвестник надежды', 'Найдите Греза Тяжелоступа в Ульдамане.', '$n, ты сможешь разыскать его? Ты разыщешь Тяжелоступа? $B$BПроклятые дворфы из Тенегорна схватили его, чтобы выпытать, что он знает о раскопках поселения титанов. Если это случится, весь Стальгорн будет в большой опасности! $B$BДворфы Черного Железа уже давно разыскивают способы сотворения могущественных големов. Конечно, такова была цель и Тяжелоступа, но это только для того, чтобы остановить Черное Железо!$B$BВозможно, они сохранят ему жизнь, пока не вытянут из него все секреты. Поспеши, быть может, его еще удастся спасти!', '', '', '', '', '', '', 19865),
(738, 'ruRU', 'Найти Эгмонда', 'Найдите Эгмонда.', 'Геолог Эгмонд вел раскопки в Бесплодных землях, на юго-западе. Я говорю "вел", потому что, к несчастью, от него нет вестей уже не одну неделю. Его нужно найти. $B$BВ последний раз его видели на самом южном раскопе Бесплодных земель – он расположен за крепостью Ангор. Думаю, стоит начать поиски там.', '', '', '', '', '', '', 19865),
(739, 'ruRU', 'Мурдалок', 'Уничтожьте убийцу Эгмонда, Мурдалока. $B$BУбейте 12 костегрызов из племени Каменного Свода. $B$BСообщите геологу Сталекруту в Лок Модане обо всем, что произошло.', 'Следы Эгмонда уводят на запад. Судя по кровавым следам на камнях и песке, дворф полз на коленях. $B$BИ здесь он умер. $B$BПод правой рукой мертвеца еле виднеется слово, нацарапанное на куске песчаника. $B$B"Мурдалок," – гласит надпись.', '', '', '', '', '', 'Вернитесь к геологу Сталекруту на Раскопки Сталекрута, что в Лок Модане.', 19865),
(742, 'ruRU', 'Большая охота', 'Поговорите с Сенани Громосерд на Заставе Расщепленного Дерева в Ясеневом лесу.', 'Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!$b$bОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – Застава Расщепленного Дерева и Застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на Заставе Расщепленного Дерева, к северу от Степей. Она ждет желающих принять участие в большой охоте!', '', '', '', '', '', '', 19865),
(743, 'ruRU', 'Соседство со стаей Неистовства Ветра', 'Принесите 8 когтей гарпий из стаи Неистовства Ветра Руулу Орлиному Когтю в деревню Кровавого Копыта.', 'Спасибо, что $gвыбрал:выбрала; время поговорить со мной, $n. Я Руул, воин и учитель.$B$BПришло время пройти испытания и покинуть Мулгор.$B$BЕсли ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги.$B$BЭти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе.', '', '', '', '', '', 'Вернитесь к Руулу Орлиному Когтю в деревню Кровавого Копыта, что в Мулгоре.', 19865),
(744, 'ruRU', 'Подготовка к церемонии', 'Добудьте 6 лазурных перьев и 6 бронзовых перьев.', '$n, вскоре мой брат предстанет перед вождем Кровавым Копытом, и мне выпала большая честь сделать для него головной убор.$B$BМне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски. Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом?$B$BПерья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утеса. Мне нужно всего-то 6 лазурных и 6 бронзовых перьев, чтобы закончить работу.', '', '', '', '', '', 'Вернитесь к Эйану Орлиному Когтю в Лагерь Солнечного Пастбища, что в Мулгоре.', 19865),
(745, 'ruRU', 'Недобрые соседи', 'Убейте 10 дубильщиков, 8 шкуродеров и 5 браконьеров из стаи Бледногривов и возвращайтесь к Бейну Кровавому Копыту в деревню Кровавого Копыта.', '$n, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.$B$BГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.$B$BСловами их не остановить.', '', '', '', '', '', 'Вернитесь к Бейну Кровавому Копыту в деревню Кровавого Копыта, что в Мулгоре.', 19865),
(746, 'ruRU', 'Дворфийские делишки', 'Соберите 5 кирок геолога.$B$BСломайте их в кузнице. $B$BОтнесите 5 сломанных инструментов Бейну Кровавому Копыту в деревню Кровавого Копыта.', 'К северо-западу отсюда дворфы готовятся к раскопкам. Они думают, что тайны скрыты глубоко в земле, и это правда, но у нее надо учиться, а не осквернять бесконечными ямами.$B$BСобери инструменты дворфов, уничтожь их и принеси мне.$B$BЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.', '', '', '', '', '', 'Вернитесь к Бейну Кровавому Копыту в деревню Кровавого Копыта, что в Мулгоре.', 19865),
(747, 'ruRU', 'Охота начинается', 'Принесите 7 перьев равнинных долгоногов и 7 кусков мяса равнинных долгоногов Груллу Соколиному Ветру в Лагерь Нараче.', 'Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утес. Но прежде чем это случится, тебе придется доказать моему отцу, вождю Соколиному Ветру, что ты $Gдостоин:достойна; этой чести. $b$bНа плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты $gспособен:способна;, – поохоться на равнинных долгоногов и принеси мяса в деревню.', '', '', '', '', '', 'Вернитесь к Груллу Соколиному Ветру в Лагерь Нараче, что в Мулгоре.', 19865),
(749, 'ruRU', 'Разграбленный караван', 'Морин Ловец Облаков попросил вас изучить содержимое ящиков с припасами в разграбленном караване.', 'Несколько дней назад мы наткнулись на охраняемый караван Торговой Компании, следовавший вдоль северного берега озера Каменного Быка. В предыдущей битве мы потеряли двоих, поэтому на сей раз мы напали без промедления и уничтожили караван.$B$BМы бросили их ящики с припасами, полагая, что наши факелы уничтожат все ценное, но учитывая, что возле сожженных телег видели мародеров Торговой Компании, похоже, мы ошиблись.$B$BБыть может, ты сходишь к каравану и посмотришь, что в ящиках?', '', '', '', '', '', '', 19865),
(751, 'ruRU', 'Разграбленный караван', 'Отнесите бумаги Торговой Компании Морину Ловцу Облаков, которого можно найти неподалеку от деревни Кровавого Копыта.', 'Приоткрыв крышку, вы видите плотно упакованную руду и минералы – новое свидетельство деятельности Торговой Компании в Мулгоре. Поверх руды и минералов лежит пачка бумаг.$B$BСо стороны восточных предгорий доносятся звуки работы и к небу поднимается дым от больших костров.', '', '', '', '', '', '', 19865),
(752, 'ruRU', 'Скромная просьба', 'Поищите матушку вождя Соколиный Ветер у источника к юго-востоку от Лагеря Нараче.', 'Все члены племени живут вместе в мире и гармонии. $b$bМы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой. $b$bМоя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты ее, пока я занимаюсь делами племени?', '', '', '', '', '', '', 19865),
(753, 'ruRU', 'Скромная просьба', 'Наберите кувшин воды из колодца.$b$bОтнесите кувшин вождю Соколиному Ветру в Лагерь Нараче, который находится к северо-западу от источника.', 'В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я еще могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. $b$bДумаю, ты $gдостойный:достойная:c; |3-6($c). Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. $b$bПомни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин.', '', '', '', '', '', 'Вернитесь к вождю Соколиному Ветру в Лагерь Нараче, что в Мулгоре.', 19865),
(759, 'ruRU', 'Тотем Буйногривых', 'Отнесите 8 зубов могучего волка прерий Муллу Громовому Рогу в деревню Кровавого Копыта.', 'Тебе осталось очистить лишь один колодец, названный в честь племени Буйногривых. Для этого тебе понадобятся зубы лютых хищников, могучих волков прерий. Ступай на север, поохоться на них и возвращайся.$B$BМогучие волки прерий водятся неподалеку от славного города Громового Утеса.', '', '', '', '', '', 'Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.', 19865),
(761, 'ruRU', 'Охота на перепелятников', 'Принесите 8 трофейных перьев перепелятника Харкену Тотему Ветра в деревне Кровавого Копыта.', 'Перепелятники – хитрые птицы. Их нелегко найти и убить. Связка перьев перепелятника – все равно что медаль для охотника, говорящая о его уме и решимости.$B$BЕсли ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников. $b$bПринеси мне их перья, и прославь свой клан этой победой.$B$BПерепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта.', '', '', '', '', '', 'Вернитесь к Харкену Тотему Ветра в деревню Кровавого Копыта, что в Мулгоре.', 19865),
(763, 'ruRU', 'Обряды Матери-Земли', 'Отнесите тотем Соколиного Ветра Бейну Кровавому Копыту в деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.', 'Чтобы продолжить прохождение обрядов Матери-Земли, ты $gдолжен:должна; выдержать еще два испытания. Тебе бы не помешало поднабраться опыта, $n.$b$bОтправляйся в деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. $b$bОтнеси этот тотем Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.$b$bСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!', '', '', '', '', '', '', 19865),
(764, 'ruRU', 'Торговая Компания', 'Убейте 14 рабочих Торговой Компании и 6 бригадиров Торговой Компании по поручению Морина Ловца Облаков из деревни Кровавого Копыта.', 'Теперь понятно, почему в Мулгоре появилось много сотрудников и оборудования Торговой Компании. Эти гоблины... Компания слишком быстро растет, не жди добра. Как говорят, гоблинам палец в рот не клади.$B$BМаленькие жадины. К несчастью для их деловых операций, таурены не согласны терпеть их присутствие в своих землях. Ступай в их рудник на северо-востоке от разграбленного каравана и преподай им урок.', '', '', '', '', '', 'Вернитесь к Морину Ловцу Облаков в Мулгор.', 19865),
(765, 'ruRU', 'Бригадир Шумовик', 'Убейте бригадира Шумовика и принесите его планшет Морину Ловцу Облаков в деревню Кровавого Копыта.', 'Согласно документам, которые ты $gотыскал:отыскала; в караване, Торговая Компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить.$B$BМне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы. Его зовут бригадир Шумовик, он сейчас в руднике Торговой Компании на востоке от разграбленного каравана. Принеси мне его планшет, посмотрим, нет ли там чего полезного.', '', '', '', '', '', 'Вернитесь к Морину Ловцу Облаков в Мулгор.', 19865),
(767, 'ruRU', 'Обряд прозрения', 'Поговорите с Зарельманом Две Луны в деревне Кровавого Копыта.', 'Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утеса.$B$BНаш народ твердо усвоил, что кормящая нас земля – священна. Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождем деревни, Зарельманом Две Луны.', '', '', '', '', '', '', 19865),
(768, 'ruRU', 'Добывание шкур', 'Принесите 12 кусков тонкой кожи Верену Долгоногу в Громовой Утес.', 'Привет тебе, $Gюноша:девица;. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесешь ты честь своему клану!$B$BЯ работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утеса.$B$BЕсли принесешь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью.', '', '', '', '', '', 'Вернитесь к Верену Долгоногу в Громовой Утес.', 19865),
(769, 'ruRU', 'Сумка из шкуры кодо', 'Принесите 4 куска легкой кожи и 4 мотка грубой нити Верену Высокому Страннику в Громовой Утес.', 'Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем. Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы.$B$BИ тогда я поделюсь с тобой своими знаниями.', '', '', '', '', '', 'Вернитесь к Верену Долгоногу в Громовой Утес.', 19865),
(770, 'ruRU', 'Поцарапанный демоном плащ', 'Отыщите кого-нибудь, кто слышал о Призрачном Вое.', 'На потрепанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом.$B$BМожет быть, следует рассказать кому-нибудь в Лагере Солнечного Пастбища о кончине Призрачного Воя...', '', '', '', '', '', '', 19865),
(773, 'ruRU', 'Обряд мудрости', 'Отправляйтесь в Красные Скалы на востоке от Громового Утеса и поговорите с духом предков.', 'Чтобы завоевать признание старейшин Громового Утеса, тебе следует пройти Обряд мудрости.$B$BТы уже $gпрошел:прошла; Обряд прозрения, и духи Красных скал благословят тебя силой предков. Лишь те, кто испили воды Провидцев, могут обрести это благословение.$b$bСтупай на восток от Громового Утеса, к Красным скалам, и отыщи там дух предков.', '', '', '', '', '', '', 19865),
(774, 'ruRU', '<UNUSED>', '', '', '', '', '', '', '', '', 19865),
(775, 'ruRU', 'Путешествие в Громовой Утес', 'Поговорите с Кэрном Кровавым Копытом в Громовом Утесе.', 'Отныне тебя будут почитать в стенах нашего великого города. $GПрошедший:Прошедшая; обряды Матери-Земли заслуживает такой чести.$B$bВыполни последнее задание, отыщи благородного вождя Кэрна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.', '', '', '', '', '', '', 19865),
(781, 'ruRU', 'Нападение на Лагерь Нараче', 'Отнесите план нападения племени Дыбогривов вождю Соколиному Ветру в Лагерь Нараче.', 'Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения племени Дыбогривов на Лагерь Нараче. $b$bВождь Соколиный Ветер непременно должен об этом узнать!', '', '', '', '', '', '', 19865),
(782, 'ruRU', 'Разорванные союзы', 'Убейте главаря То''груна и принесите знак земли Горну в Каргат.', 'От союзника Орды времен Второй войны, дракона Смертокрыла мы знаем, что два его лейтенанта, Чернохлыст и Гематус, были заточены в долине Летлор. Чтобы отстоять честь Орды и не допустить предательства, мы должны заставить замолчать наших растленных бывших союзников! $B$BМы наняли То''груна и его шайку огров-наемников, чтобы они помогли нам получить знак земли – ключ, необходимый, чтобы открыть драконье узилище. Но То''грун предал нас, забрав знак себе. Отправляйся в лагерь Бофф и отбери знак!', '', '', '', '', '', 'Вернитесь к Горну в Каргат, что в Бесплодных землях.', 19865),
(783, 'ruRU', 'Внутренняя угроза', 'Поговорите с маршалом Макбрайдом.', 'Надеюсь, ты $gготов:готова; к подвигам, |3-6($c), потому что у нас тут такое творится! Смертокрыл со своими Сумеречными армиями напал на Азерот. Король призвал к оружию всех верных Альянсу горожан годных к воинской службе.$B$BСтража Штормграда с трудом поддерживает здесь мир: слишком многие наши находятся в дальних краях, и отовсюду приходят тревожные вести. Мы с радостью примем любую помощь от всех, кто готов защитить свой дом и своих близких.$B$BЕсли ты $gготов:готова; откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он где-то здесь, рядом с аббатством.', '', '', '', 'Test', '', '', 19865),
(784, 'ruRU', 'Бей предателей!', 'Убейте 10 моряков Кул-Тираса, 8 стражей бухты Кул-Тираса и лейтенанта Бенедикта и возвращайтесь к Га''Току на Колючий Холм.', 'Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда.$b$bВторжение людей удалось отбить, крепость Тирагард пала. Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность! Эти люди совершенно не чтут договоров!$b$bПокажи свою доблесть, $n. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей.', '', '', '', '', '', 'Вернитесь к Га''Току в Дуротар.', 19865),
(786, 'ruRU', 'Предотвращение агрессии племени Колкар', 'Лар Ночной Клык из деревни Сен''джин хочет, чтобы вы уничтожили 3 плана нападения, которые хранятся в лагере кентавров, что на Утесе Колкар.', 'Говори потише, |3-6($c)! Кентавры из племени Колкар совсем близко, вон там, к западу от Утеса Колкара.$b$bПрошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!$b$bНельзя допустить, чтобы они это сделали! Достаточно ли ты $gхрабр:храбра;, чтобы напасть на Утес Колкар и уничтожить их планы?$b$bЯ заметил, что они хранятся у трех лидеров кентавров.', '', '', '', '', '', 'Вернитесь к Лару Ночному Клыку в Деревню Сен''джин, что в Дуротаре.', 19865),
(787, 'ruRU', 'Новая Орда', 'Зайти в Логово к Горнеку.', 'Тром''ка, |3-6($c)! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов.$b$bОрда уже не такая, как раньше. Некогда я оставил ее: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся.$b$bГорнек скажет тебе, что делать дальше.', '', '', '', '', '', '', 19865),
(788, 'ruRU', 'Кабаньи клыки', 'Убейте 8 пятнистых вепрей и вернитесь в Логово к Горнеку.', 'Вот тебе первое поручение, чтобы ты $gнабрался:набралась; опыта и $gпоказал:показала; себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему.$b$bПожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда.', '', '', '', '', '', 'Вернитесь к Горнеку в Долину Испытаний, что в Дуротаре.', 19865),
(789, 'ruRU', 'Жала скорпидов', 'Добудьте 8 хвостов рабочих скорпидов и принесите их в Логово Горнеку.', 'Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков. К северо-западу отсюда водится множество этих членистоногих. Принеси мне восемь их хвостов, чтобы доказать свою воинскую доблесть.$b$bИз яда жал скорпионов можно изготовить противоядие. Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя...$b$bНо тебе-то оно не понадобится, а?', '', '', '', '', '', 'Вернитесь к Горнеку в Долину Испытаний, что в Дуротаре.', 19865),
(790, 'ruRU', 'Саркот', 'Убейте Саркота и принесите его коготь Хана''зуа.', '$C! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу.$b$bА вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда...', '', '', '', '', '', 'Вернитесь к Хана''зуа в Дуротар.', 19865),
(791, 'ruRU', 'Больше сумок – больше добычи!', 'Принесите 8 лоскутов холста Фурлу Хмурому Лбу, стоящему на сторожевой башне Колючего Холма.', 'Старость сделала меня бесполезным в бою. Теперь я служу Орде иным путем.$b$bЯ сижу здесь, на вышине, и смотрю, не появятся ли враги. Но по мере того, как наши силы растут, мне все реже и реже приходится трубить в сигнальный рог.$b$bА чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину.$b$bЯ могу сделать тебе сумку для пожитков. Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров.', '', '', '', '', '', 'Вернитесь к Фурлу Хмурому Лбу в Колючий Холм, что в Дуротаре.', 19865),
(792, 'ruRU', 'Злобные фамилиары', 'Убейте 8 злобных фамилиаров и вернитесь к Зурите Востроглазой, которая ждет вас у Логова.', 'Что ж, |3-6($c), надеюсь, у нас ты многому научишься.$b$bМеня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не все ладно!$b$bВ Долине Испытаний обосновался ковен Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамилиары выбираются оттуда и сеют хаос.$b$bИтак, вот твое первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне.', '', '', '', '', '', 'Вернитесь к Зурите Востроглазой в Долину Испытаний, что в Дуротаре.', 19865),
(794, 'ruRU', 'Медальон Пылающего Клинка', 'Принесите медальон Пылающего Клинка Зурите Востроглазой, стоящей у Логова.', 'С помощью ворожбы я узнала, что в глубине Грота Пылающего Клинка находится мощный магический предмет. Его стерегут звери и черная магия.$b$bЭтот предмет – медальон Пылающего Клинка. Твоя очередная задача – найти его и отнять у ковена.$b$bНо берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамилиары, с которыми тебе уже доводилось встречаться!$b$bСтупай, $n. Грот находится к северо-западу отсюда.', '', '', '', '', '', 'Вернитесь к Зурите Востроглазой в Долину Испытаний, что в Дуротаре.', 19865),
