INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(31853, 'ruRU', 'Все на борт!', 'Поговорите с генералом Назгримом на борту корабля "Кулак Адского Крика".', '$gСлыхал:Слыхала;, $n? Мне нужна команда опытных бойцов для опасного задания.$b$bНужно как следует потрепать Альянс, и ты отправляешься со мной!$b$bМы не вернемся, пока не выполним задачу, так что собирай вещи и готовься.$b$bЯ буду на борту свежеотстроенного боевого судна над бухтой Острорука.$b$bНе заставляй меня ждать!', '', '', '', '', '', '', 19865),
(31854, 'ruRU', 'Аналинн', 'Победите Аналинн в битве питомцев.', 'Вижу, ты снова меня $gнашел:нашла;. Видимо, хочешь снова вызвать меня на бой? Что ж, я не против.', '', '', '', '', '', 'Поговорите с Аналинн.', 19865),
(31855, 'ruRU', 'Пик Безмятежности - продолжение обучения', 'Воспользуйтесь способностью "Духовное путешествие", чтобы отправиться на Пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время вернуться на Пик Безмятежности и продолжить твои тренировки. Воспользуйся способностью "Духовное путешествие" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 19865),
(31856, 'ruRU', 'Пик Безмятежности – начало обучения', 'Воспользуйтесь способностью "Духовное путешествие", чтобы отправиться на Пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время отправиться на Пик Безмятежности и начать твои тренировки. Воспользуйся способностью "Духовное путешествие" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 19865),
(31857, 'ruRU', 'Пик Безмятежности - продолжение обучения', 'Воспользуйтесь способностью "Духовное путешествие", чтобы отправиться на Пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время вернуться на Пик Безмятежности и продолжить твои тренировки. Воспользуйся способностью "Духовное путешествие" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 19865),
(31858, 'ruRU', 'Пик Безмятежности - продолжение обучения', 'Воспользуйтесь способностью "Духовное путешествие", чтобы отправиться на Пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время вернуться на Пик Безмятежности и продолжить твои тренировки. Воспользуйся способностью "Духовное путешествие" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 19865),
(31859, 'ruRU', 'Пик Безмятежности - продолжение обучения', 'Воспользуйтесь способностью "Духовное путешествие", чтобы отправиться на Пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время вернуться на Пик Безмятежности и продолжить твои тренировки. Воспользуйся способностью "Духовное путешествие" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 19865),
(31860, 'ruRU', 'Пик Безмятежности - продолжение обучения', 'Воспользуйтесь способностью "Духовное путешествие", чтобы отправиться на Пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время вернуться на Пик Безмятежности и продолжить твои тренировки. Воспользуйся способностью "Духовное путешествие" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 19865),
(31861, 'ruRU', 'Пик Безмятежности - продолжение обучения', 'Воспользуйтесь способностью "Духовное путешествие", чтобы отправиться на Пик Безмятежности. По прибытии поговорите с мастером Хайтом в Святилище Быка.', 'Пришло время вернуться на Пик Безмятежности и продолжить твои тренировки. Воспользуйся способностью "Духовное путешествие" и поговори с мастером Хайтом по прибытии.', '', '', '', '', '', 'Поговорите с мастером Хайтом в Святилище Быка.', 19865),
(31862, 'ruRU', 'Зоня Садистка', 'Победите Зоню Садистку в битве питомцев.', 'Добыча сама идет в лапы хищника, даже не подозревая об опасности. На этот раз Зоня с тобой позабавится.', '', '', '', '', '', 'Поговорите с Зоней Садисткой.', 19865),
