(36059, 'ruRU', 'Достойный преемник', 'Пробудите короля воронов.', 'Время пришло, $p.
INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(36342, 'ruRU', 'Изначальное неистовство', 'Поговорите с темным охотником Рокханом в северном Таладоре, затем одолейте Горгорека и Азуку Ярость Клинка.', 'Похоже, время пришло, командир.$B$BМы должны остановить Железную Орду любой ценой. Я отправила буревестников в твой гарнизон и попросила темного охотника Рокхана перебросить твои войска к Вратам Танаана.$B$BК тому времени, как ты доберешься в северный Таладор, он будет ждать тебя там... Со всей армией.$B$BОткладывать больше нельзя.', '', '', '', '', '', 'Вернитесь к верховному магу Кадгару в Башню Кадгара, что в Таладоре.', 19865),
(36344, 'ruRU', 'Накормить армию', 'Используйте улучшенную железную ловушку, чтобы поймать вепря или речное чудище в Горгронде, а затем разместите заказ в своем хлеву.', 'Мы уже довольно хорошо изучили этих животных и разработали для тебя новую ловушку. Она должна быть намного прочнее предыдущей.$B$BУлучшенная железная ловушка поможет тебе поймать на Дреноре зверей помясистее. Одним речным чудищем или вепрем из Горгронда можно накормить многих воинов.$B$BПоймай зверя и доставь его сюда, а мы приготовим потрясающий обед.', '', '', '', '', '', 'Вернитесь к фермеру Лок''лубу в свой гарнизон.', 19865),
(36345, 'ruRU', 'Игры с ловушками', 'Используйте железную ловушку, чтобы поймать копытня или волка на Хребте Ледяного Огня, а затем разместите заказ в своем хлеву.', 'Проходя через портал, мы не смогли взять с собой наших животных. Чтобы наладить производство шкур и меха, тебе нужно поймать и доставить сюда несколько местных зверей.$B$BНесмотря на то, что равнины замерзли, на Хребте Ледяного Огня предостаточно копытней и волков. С копытней можно получить шкуры, а с волков – мех.$B$BВозьми эту железную ловушку и поймай с ее помощью раненого взрослого зверя. Затем доставь пойманное животное сюда, и мы возьмемся за дело.', '', '', '', '', '', 'Вернитесь к фермеру Лок''лубу в свой гарнизон.', 19865),
(36346, 'ruRU', 'Больше ловушка – крупнее награда', 'Поймайте в смертоносную железную ловушку самца железношкурого копытня, самца лютоклыка или болотного тяжелоступа.', 'А, командир, рад снова видеть тебя. Благодаря собранным на Дреноре материалам, мы смогли соорудить ловушку, способную обездвижить даже самого крупного зверя.$B$BЭтих громадных созданий можно найти в западной части Награнда, на самых плодородных равнинах.$B$BНо предупреждаю: эти звери большие и сильные. Возможно, тебе стоит позвать на помощь товарищей.', '', '', '', '', '', 'Вернитесь к фермеру Лок''лубу в свой гарнизон.', 19865),
(36347, 'ruRU', 'Атака на Плато Сокретара', '', '', '', '', '', '', '', '', 19865),
(36348, 'ruRU', 'Атака на Плато Сокретара', '', '', '', '', '', '', '', '', 19865),
(36352, 'ruRU', 'В поисках ювелира', 'Разыщите владельца медальона в Вор''голе.', 'Ты точно $gуверен:уверена;, что не хочешь это продать? Я дам отличную цену!$B$BЛадно, ладно... раз ты настаиваешь на том, чтобы найти владельца, тебе стоит заглянуть в Вор''гол.$B$BГоворят, там живет искусный мастер, занимающийся обработкой драгоценных металлов и камней. Возможно, он тебе и нужен.', '', '', '', '', '', '', 19865),
(36353, 'ruRU', 'По старой дружбе', '', '', '', '', '', '', '', '', 19865),
