(30560, 'ruRU', '[DNT] Tools of Divination TRACKER', '', '', '', '', '', '', '', '', 19865),
(30561, 'ruRU', '[DNT] Fun for the Little Ones TRACKER', '', '', '', '', '', '', '', '', 19865),
