(31348, 'ruRU', 'Tracking Event: Gina Mudclaw Exalted', '', '', '', '', '', '', '', '', 19865),
(31349, 'ruRU', 'Tracking Event: Haohan Mudclaw Exalted', '', '', '', '', '', '', '', '', 19865),
(31350, 'ruRU', 'Tracking Event: Jogu the Drunk Exalted', '', '', '', '', '', '', '', '', 19865),
